export const events = [
  { id:1, season:"பருவம் 01", seasonNum:1, date:"அக்டோபர் 1, 2015", title:"விஜய்யைக் குறிவைத்த முதல் ஐடி ரெய்டு", filter:"raid", tags:[["ரெய்டு","red"],["விஜய்","gray"],["ஐடி துறை","gray"]], desc:"நடிகர் விஜய்யின் 'புலி' படம் வெளியாவதற்கு ஒரு நாள் முன்பு, சென்னை சாலிகிராமம் மற்றும் நீலாங்கரை உட்பட 30-க்கும் மேற்பட்ட இடங்களில் ஐடி துறை ஒரே நேரத்தில் சோதனை நடத்தியது. நயன்தாரா, சமந்தா வீடுகளிலும் சோதனை நடந்தது; படத்தின் சிறப்புக் காட்சிகள் ரத்தாயின. எந்த பெரிய வரி ஏய்ப்பும் நிரூபிக்கப்படாமல் போனதால், இது விஜய்யின் வளர்ந்துவரும் செல்வாக்கைக் கட்டுப்படுத்த ஏவப்பட்ட அரசியல் மிரட்டல் என்று பரவலாக விமர்சிக்கப்பட்டது. தீவிர அரசியலுக்குள் நுழைய வேண்டும் என்ற சிந்தனையை விஜய்யிடம் ஆழமாக விதைத்த முதல் புள்ளி இதுவே." , year:2015, parties:["tvk", "it_dept"], newsQuery:"விஜய்யைக் குறிவைத்த முதல் ஐடி ரெய்டு 2015"},
  { id:2, season:"பருவம் 01", seasonNum:1, date:"ஏப்ரல் 22, 2016", title:"கரூரில் அன்புநாதன் குடோன் மெகா ரெய்டு", filter:"raid", tags:[["ரெய்டு","red"],["கரூர்","gray"],["தேர்தல் பணம்","gray"]], desc:"2016 தேர்தலுக்குச் சில வாரங்களே இருந்தபோது, கரூரில் பைனான்சியர் அன்புநாதனுக்குச் சொந்தமான குடோன் நள்ளிரவில் சுற்றிவளைக்கப்பட்டது. ₹4.77 கோடி ரொக்கம் கைப்பற்றப்பட்டது; ஆம்புலன்ஸ் மூலம் வாக்காளர்களுக்கு பணம் விநியோகிக்கப்பட்டதற்கான பகீர் தகவல்கள் வெளியாயின. பினாமி சொத்து ஆவணங்களும், போலி முத்திரைத்தாள்களும் சிக்கியதால் கரூர் மாவட்டம் ரகசிய பணப் பட்டுவாடா மையமாகச் செயல்படுவது முதன்முதலாக வெளிச்சத்திற்கு வந்தது." , year:2016, parties:["unknown"], newsQuery:"கரூரில் அன்புநாதன் குடோன் மெகா ரெய்டு 2016"},
  { id:3, season:"பருவம் 01", seasonNum:1, date:"மே 14, 2016", title:"திருப்பூர் ₹570 கோடி கன்டெய்னர் விவகாரம்", filter:"raid", tags:[["ரெய்டு","red"],["திருப்பூர்","gray"],["₹570 கோடி","gray"]], desc:"வாக்குப்பதிவுக்கு இரண்டு நாட்களுக்கு முன்பு திருப்பூரில் 3 மர்ம கன்டெய்னர் லாரிகள் சிறைபிடிக்கப்பட்டன. உள்ளே ₹570 கோடி ரொக்கம் கண்டுபிடிக்கப்பட்டது. நள்ளிரவில் எவ்வித உரிய ஆவணங்களும் இன்றி கொண்டு செல்லப்பட்டதால் பெரும் சந்தேகங்கள் எழுந்தன. பின்னர் இது கோயம்புத்தூரிலிருந்து விசாகப்பட்டினத்திற்கு மாற்றப்படும் SBI பணம் என அதிகாரப்பூர்வமாக தெரிவிக்கப்பட்டது. எதிர்க்கட்சிகள் இதை ஒரு மாபெரும் அரசியல் சூழ்ச்சியாகவே கடைசிவரை கண்டன." , year:2016, parties:["unknown"], newsQuery:"திருப்பூர் ₹570 கோடி கன்டெய்னர் விவகாரம் 2016"},
  { id:4, season:"பருவம் 01", seasonNum:1, date:"மே 16 & 19, 2016", title:"சட்டமன்றத் தேர்தல் மற்றும் வரலாற்று முடிவுகள்", filter:"election", tags:[["தேர்தல்","red"],["அதிமுக","gray"],["திமுக","gray"]], desc:"15-வது தமிழ்நாடு சட்டமன்றத் தேர்தல் வாக்குப்பதிவு மே 16 அன்று நடைபெற்றது. ஆளுங்கட்சிக்கு எதிராக அலை இருப்பதாகக் கருதப்பட்ட நிலையில், மே 19 முடிவுகள் அனைவரையும் ஆச்சரியத்தில் ஆழ்த்தின. ஜெயலலிதா தலைமையிலான அதிமுக 134 இடங்கள் வென்று 1984-க்குப் பிறகு தொடர்ந்து இரண்டாவது முறையாக ஆட்சி தக்கவைத்தது. திமுக 98 இடங்களுடன் வரலாற்றின் மிக வலுவான எதிர்க்கட்சியாக நுழைந்தது. தேமுதிக, பாமக உட்பட பல கட்சிகள் ஒரு இடம் கூட வெல்லவில்லை." , year:2016, parties:["dmk", "aiadmk"], newsQuery:"சட்டமன்றத் தேர்தல் மற்றும் வரலாற்று முடிவுகள் 2016"},
  { id:5, season:"பருவம் 01", seasonNum:1, date:"மே 23, 2016", title:"6-வது முறையாக ஜெயலலிதா பதவியேற்பு", filter:"oath", tags:[["பதவியேற்பு","red"],["ஜெயலலிதா","gray"],["அதிமுக","gray"]], desc:"மெட்ராஸ் பல்கலைக்கழக நூற்றாண்டு விழா மண்டபத்தில் ஜெயலலிதா 6-வது முறையாக முதலமைச்சராகப் பதவியேற்றார். ஓபிஎஸ் நிதி அமைச்சராகவும், எடப்பாடி நெடுஞ்சாலை அமைச்சராகவும் நியமிக்கப்பட்டனர். முதல் நாளே 500 டாஸ்மாக் கடை மூடல், பெண்களுக்கு மானிய ஸ்கூட்டர் உட்பட 5 முக்கியக் கோப்புகளில் கையெழுத்திட்டார். ஸ்டாலின் பின்வரிசையில் அமரவைக்கப்பட்ட சர்ச்சையும் நடந்தது. இது ஜெயலலிதாவின் இறுதி மகுடமாக ஆகும் என்பதை அப்போது யாரும் எதிர்பார்க்கவில்லை." , year:2016, parties:["dmk", "aiadmk"], newsQuery:"6-வது முறையாக ஜெயலலிதா பதவியேற்பு 2016"},
  { id:6, season:"பருவம் 01", seasonNum:1, date:"செப்டம்பர் 22, 2016", title:"அப்பல்லோவில் ஜெயலலிதா அவசர அனுமதி", filter:"crisis", tags:[["நெருக்கடி","red"],["ஜெயலலிதா","gray"],["அப்பல்லோ","gray"]], desc:"நள்ளிரவு நேரத்தில் ஜெயலலிதா திடீர் உடல்நலக்குறைவால் அப்பல்லோ மருத்துவமனையில் அவசரமாக அனுமதிக்கப்பட்டார். காய்ச்சல் மற்றும் நீர்ச்சத்து குறைபாடே காரணம் என மருத்துவமனை தெரிவித்தது. ஆனால் பலத்த பாதுகாப்பும், லண்டன் மற்றும் எய்ம்ஸ் மருத்துவர்கள் வரவழைப்பும் நிலைமையின் தீவிரத்தை உணர்த்தின. ஒட்டுமொத்த தமிழக அரசும் அப்பல்லோ வாயிலில் இருந்தே செயல்படத் தொடங்கியது — தமிழக அரசியலின் இருண்ட பக்கங்களுக்கான தொடக்கம் இதுவே." , year:2016, parties:["aiadmk"], newsQuery:"அப்பல்லோவில் ஜெயலலிதா அவசர அனுமதி 2016"},
  { id:7, season:"பருவம் 01", seasonNum:1, date:"அக்டோபர் 12, 2016", title:"ஓபிஎஸ் வசம் பொறுப்புகள் மாற்றம்", filter:"crisis", tags:[["நிர்வாகம்","red"],["ஓபிஎஸ்","gray"],["பொறுப்பு மாற்றம்","gray"]], desc:"ஜெயலலிதாவின் சிகிச்சை நீண்டுகொண்டதால், காவல், பொது நிர்வாகம், உள்வகை உட்பட அனைத்து முக்கிய இலாகாக்களும் நிதி அமைச்சர் ஓபிஎஸ்ஸிடம் ஒப்படைக்கப்பட்டன. ஆளுணர் வித்தியாசாகர் ராவ் அரசாணை மூலம் ஓபிஎஸ் அமைச்சரவை கூட்டங்களை நடத்துவார் என அறிவிக்கப்பட்டது. முதலமைச்சர் பொறுப்பில் ஜெயலலிதாவே தொடர்வார் என்றும் இது தற்காலிக ஏற்பாடே என்றும் ஆளுணர் மாளிகை தெளிவுபடுத்தியது." , year:2016, parties:["aiadmk"], newsQuery:"ஓபிஎஸ் வசம் பொறுப்புகள் மாற்றம் 2016"},
  { id:8, season:"பருவம் 01", seasonNum:1, date:"டிசம்பர் 4, 2016", title:"ஜெயலலிதாவுக்குக் கடும் மாரடைப்பு", filter:"crisis", tags:[["நெருக்கடி","red"],["மாரடைப்பு","gray"],["அப்பல்லோ","gray"]], desc:"குணமடைந்துவிட்டார் என நம்பிக்கையிருந்தபோது, டிசம்பர் 4 மாலை 5:15 மணிக்கு ஜெயலலிதாவுக்கு கடும் மாரடைப்பு ஏற்பட்டதாக அப்பல்லோ அறிவித்தது. அவர் உடனடியாக எக்மோ கருவியின் தீவிரக் கண்காணிப்பில் வைக்கப்பட்டார். லட்சக்கணக்கான அதிமுக தொண்டர்கள் மருத்துவமனை முன்பு கண்ணீருடன் குவிந்தனர். தமிழகம் முழுவதும் பேருந்து நிறுத்தம், கடைகள் அடைத்தல் மாபெரும் பதற்றச் சூழல் நிலவியது." , year:2016, parties:["dmk", "aiadmk"], newsQuery:"ஜெயலலிதாவுக்குக் கடும் மாரடைப்பு 2016"},
  { id:9, season:"பருவம் 01", seasonNum:1, date:"டிசம்பர் 5, 2016 — இரவு 11:30", title:"இரும்புப் பெண்மணி காலமானார்", filter:"crisis", tags:[["மரணம்","red"],["ஜெயலலிதா","gray"],["தமிழக வரலாறு","gray"]], desc:"டிசம்பர் 5 இரவு 11:30 மணிக்கு அனைத்து சிகிச்சைகளும் பலனளிக்காமல் ஜெயலலிதா காலமானார் என அப்பல்லோ அறிவித்தது. 30 ஆண்டுகளுக்கும் மேலாக தமிழக அரசியலை கட்டியாண்ட ஒரு சரித்திரம் முடிவுக்கு வந்தது. சென்னை ராஜாஜி அரங்கில் பொதுமக்கள் அஞ்சலிக்காக வைக்கப்பட்ட அவரது உடலைக் கண்டு தமிழகம் கண்ணீர் கடலில் மூழ்கியது. எம்ஜிஆருக்குப் பிறகு மக்கள் ஆழமாக நேசித்த தலைவியின் மரணம் தமிழக அரசியலில் நிரப்ப முடியாத வெற்றிடத்தை ஏற்படுத்தியது." , year:2016, parties:["aiadmk"], newsQuery:"இரும்புப் பெண்மணி காலமானார் 2016"},
  { id:10, season:"பருவம் 01", seasonNum:1, date:"டிசம்பர் 5, 2016 — நள்ளிரவு 1:15", title:"ஓபிஎஸ் புதிய முதலமைச்சராகப் பதவியேற்பு", filter:"oath", tags:[["பதவியேற்பு","red"],["ஓபிஎஸ்","gray"],["புதிய அத்தியாயம்","gray"]], desc:"ஜெயலலிதாவின் மரணம் அறிவிக்கப்பட்ட சில மணி நேரங்களிலேயே, நள்ளிரவு 1:15 மணிக்கு ஆளுணர் மாளிகையில் ஓ. பன்னீர்செல்வம் புதிய முதலமைச்சராகக் கண்ணீருடன் பதவியேற்றார். முந்தைய அமைச்சரவையிலிருந்த 31 அமைச்சர்களும் மீண்டும் பொறுப்பேற்றனர். எவ்வித அதிகார போட்டியும் இன்றி அமைதியாக நடந்த இம்மாற்றம் சசிகலாவின் நேரடிக் கட்டுப்பாட்டிலேயே நிகழ்ந்தது என்பது பரவலாக அறியப்பட்டது. இந்தப் பதவியேற்பு தமிழக அரசியலின் புதிய, இருண்ட அத்தியாயத்தைத் தொடங்கி வைத்தது." , year:2016, parties:["aiadmk"], newsQuery:"ஓபிஎஸ் புதிய முதலமைச்சராகப் பதவியேற்பு 2016"},
  { id:11, season:"பருவம் 02", seasonNum:2, date:"டிசம்பர் 8, 2016", title:"சேகர் ரெட்டி வீட்டில் மெகா ரெய்டு", filter:"raid", tags:[["ரெய்டு","red"],["சேகர் ரெட்டி","gray"],["ஐடி துறை","gray"]], desc:"ஜெயலலிதா மறைந்த வெறும் 3-வது நாளிலேயே, ஐஆர்எஸ் அதிகாரி கே.ஜி. அருண்ராஜ் தலைமையிலான வருமான வரித்துறை புலனாய்வுப் பிரிவினர் அரசு ஒப்பந்ததாரர் மற்றும் மணல் தொழிலதிபர் ஜே. சேகர் ரெட்டி வீடுகளில் நுழைந்தனர். ஓபிஎஸ் உட்பட பல முக்கிய அமைச்சர்களுடன் நெருங்கிய தொடர்பில் இருந்த சேகர் ரெட்டியின் வீடு, அலுவலகங்கள் என பல இடங்களில் ஒரே நேரத்தில் சோதனை நடந்தது. பணமதிப்பிழப்பு அறிவிக்கப்பட்ட சில வாரங்களிலேயே இந்தச் சோதனை நடந்ததால் தேசிய அளவில் மிகப்பெரிய கவனத்தை ஈர்த்தது. தமிழக அரசியலை ஆட்டிப்படைத்த பணப் பரிவர்த்தனைகளின் ரகசியங்களை மத்திய அரசு நேரடியாகக் கையிலெடுக்கத் தொடங்கியதன் முதல் படியாக இது அமைந்தது." , year:2016, parties:["aiadmk", "it_dept"], newsQuery:"சேகர் ரெட்டி வீட்டில் மெகா ரெய்டு 2016"},
  { id:12, season:"பருவம் 02", seasonNum:2, date:"டிசம்பர் 11, 2016", title:"₹131 கோடி ரொக்கம் & 100 கிலோ தங்கம் பறிமுதல்", filter:"raid", tags:[["ரெய்டு","red"],["₹131 கோடி","gray"],["100 கிலோ தங்கம்","gray"]], desc:"சேகர் ரெட்டி மற்றும் அவரது கூட்டாளிகளின் இடங்களில் 4 நாட்களாகத் தொடர்ந்த மெகா சோதனை முடிவுகள் அனைவரையும் திகைக்க வைத்தன. அதிகாரிகள் மொத்தம் ₹131 கோடி ரொக்கப் பணத்தைப் பறிமுதல் செய்தனர்; அதில் ₹34 கோடி முற்றிலும் புதிய ₹2,000 நோட்டுகள். சுமார் 100 கிலோ தங்கக் கட்டிகளும் எண்ணற்ற பினாமி சொத்து ஆவணங்களும் கைப்பற்றப்பட்டன. சாதாரண மக்கள் ஏடிஎம் வாசலில் புதிய நோட்டுகளுக்காகத் தவம் கிடக்கையில், இவ்வளவு புதிய நோட்டுகள் இவரிடம் வந்தது ரிசர்வ் வங்கியையே அதிர்ச்சியடையச் செய்தது. உடனடியாக சிபிஐ மற்றும் அமலாக்கத்துறை சேகர் ரெட்டியைக் கைது செய்ததுடன் தமிழக அமைச்சர்களின் ஊழல் வளையத்தைச் சுருக்கத் தொடங்கின." , year:2016, parties:["cbi"], newsQuery:"₹131 கோடி ரொக்கம் & 100 கிலோ தங்கம் பறிமுதல் 2016"},
  { id:13, season:"பருவம் 02", seasonNum:2, date:"டிசம்பர் 21, 2016", title:"தலைமைச் செயலகத்தில் ஐடி ரெய்டு", filter:"raid", tags:[["ரெய்டு","red"],["தலைமைச் செயலகம்","gray"],["ராம் மோகன் ராவ்","gray"]], desc:"தமிழக வரலாற்றில் எந்தவொரு அரசும் சந்தித்திராத ஒரு மாபெரும் களங்கமாக மாநிலத்தின் தலைமைச் செயலகத்திற்குள் வருமான வரித்துறை அதிகாரிகள் நுழைந்தனர். தலைமைச் செயலாளர் ராம் மோகன் ராவ் அலுவலகம் மற்றும் வீடுகளில் சிஆர்பிஎஃப் துப்பாக்கி ஏந்திய பாதுகாப்போடு ரெய்டு நடந்தது. சேகர் ரெட்டி வீட்டில் சிக்கிய முக்கிய ஆவணங்கள் மற்றும் டைரிக் குறிப்புகளின் அடிப்படையிலேயே மாநிலத்தின் உச்சபட்ச அதிகாரி குறிவைக்கப்பட்டார். ₹30 லட்சம் புதிய நோட்டுகள், 5 கிலோ தங்கம், பல முக்கிய பினாமி சொத்து ஆவணங்கள் சிக்கியதாக வருமான வரித்துறை தெரிவித்தது." , year:2016, parties:["it_dept"], newsQuery:"தலைமைச் செயலகத்தில் ஐடி ரெய்டு 2016"},
  { id:14, season:"பருவம் 02", seasonNum:2, date:"டிசம்பர் 21, 2016 (மாலை)", title:"ராம் மோகன் ராவ் பணியிடை நீக்கம்", filter:"crisis", tags:[["நெருக்கடி","red"],["ராம் மோகன் ராவ்","gray"],["நிர்வாக மாற்றம்","gray"]], desc:"தலைமைச் செயலக ரெய்டு முடிவடைந்த சில மணி நேரங்களிலேயே ராம் மோகன் ராவை தலைமைச் செயலாளர் பதவியில் இருந்து தமிழக அரசு அதிரடியாகப் பணியிடை நீக்கம் செய்தது. நேர்மையான அதிகாரி எனப் பெயர் பெற்ற கிரிஜா வைத்தியநாதன் புதிய தலைமைச் செயலாளராக உடனடியாக நியமிக்கப்பட்டார். முதலமைச்சர் ஓபிஎஸ் இந்த விவகாரத்தில் எவ்வித எதிர்ப்பும் தெரிவிக்காமல் அமைதி காத்தது மத்திய அரசுடன் அவர் இணக்கமாகச் செல்கிறாரா என்ற சந்தேகத்தை எழுப்பியது. பின்னர் ராம் மோகன் ராவ், 'ஜெயலலிதா உயிருடன் இருந்திருந்தால் சிஆர்பிஎஃப் தலைமைச் செயலகத்திற்குள் நுழைய முடியுமா?' எனக் கொந்தளித்தார்." , year:2016, parties:["aiadmk"], newsQuery:"ராம் மோகன் ராவ் பணியிடை நீக்கம் 2016"},
  { id:15, season:"பருவம் 02", seasonNum:2, date:"டிசம்பர் 29, 2016", title:"சசிகலா பொதுச்செயலாளராகத் தேர்வு", filter:"alliance", tags:[["கட்சி","red"],["சசிகலா","gray"],["அதிமுக","gray"]], desc:"ஜெயலலிதாவின் மறைவுக்குப் பிறகு கட்சியைக் கைப்பற்ற வானகரத்தில் அதிமுக பொதுக்குழு மற்றும் செயற்குழுக் கூட்டம் பிரம்மாண்டமாகக் கூடியது. ஜெயலலிதாவின் நெருங்கிய தோழி வி.கே. சசிகலா கட்சியின் தற்காலிகப் பொதுச்செயலாளராக ஒருமனதாகத் தேர்ந்தெடுக்கப்பட்டார். முதலமைச்சர் ஓபிஎஸ் தீர்மானத்தை முன்மொழிய, கட்சியின் அனைத்து மூத்த தலைவர்களும் வழிமொழிந்தனர். போயஸ் கார்டனில் தீர்மான நகலை ஏற்றுக்கொண்ட சசிகலா, கண்ணீருடன் ஜெயலலிதா படத்திற்கு அஞ்சலி செலுத்திப் பொறுப்பேற்றார். 30 ஆண்டுகளாகத் திரைக்குப் பின்னால் இருந்த அதிகார மையம் முதன்முறையாக நேரடியாகத் தமிழக அரசியலின் மையபீடத்திற்கு வந்த வரலாற்று நிகழ்வாக இது அமைந்தது." , year:2016, parties:["dmk", "aiadmk"], newsQuery:"சசிகலா பொதுச்செயலாளராகத் தேர்வு 2016"},
  { id:16, season:"பருவம் 02", seasonNum:2, date:"ஜனவரி 17, 2017", title:"ஜல்லிக்கட்டு மெரினா புரட்சி", filter:"protest", tags:[["போராட்டம்","red"],["ஜல்லிக்கட்டு","gray"],["மெரினா","gray"]], desc:"பீட்டா (PETA) அமைப்பின் வழக்கால் தடைப்பட்டிருந்த தமிழர் வீர விளையாட்டான ஜல்லிக்கட்டை மீட்க, எந்தவொரு அரசியல் பின்புலமும் இன்றி இளைஞர்கள் மெரினாவில் திரண்டனர். வாட்ஸ்அப் மற்றும் ஃபேஸ்புக் மூலம் மட்டுமே ஒருங்கிணைக்கப்பட்ட இந்த அறப்போராட்டம் உலக வரலாற்றில் ஒரு மாபெரும் அமைதிப் புரட்சியாக மாறியது. மாணவர்களுடன் ஐடி ஊழியர்கள், பெண்கள், குழந்தைகள் என லட்சக்கணக்கானோர் மெரினாவை இரவு பகலாக ஆக்கிரமித்தனர். அரசியல் தலைவர்களோ சினிமா பிரபலங்களோ போராட்டக் களத்திற்குள் நுழைய அனுமதிக்கப்படாமல் முற்றிலும் மக்களின் சுய எழுச்சியாக ஏழு நாட்கள் நீடித்தது." , year:2017, parties:["unknown"], newsQuery:"ஜல்லிக்கட்டு மெரினா புரட்சி 2017"},
  { id:17, season:"பருவம் 02", seasonNum:2, date:"ஜனவரி 23, 2017", title:"அவசரச் சட்டம் இயற்றப்பட்டுத் தடை நீக்கம்", filter:"verdict", tags:[["தீர்ப்பு","red"],["ஜல்லிக்கட்டு","gray"],["அவசரச் சட்டம்","gray"]], desc:"மெரினாவில் மட்டுமின்றித் தமிழகம் முழுவதும் வெடித்த மாபெரும் மக்கள் கொந்தளிப்பைக் கண்டு அதிர்ந்த தமிழக அரசும் மத்திய அரசும் உடனடியாகச் செயல்படத் தொடங்கின. முதலமைச்சர் ஓபிஎஸ் நேரடியாக டெல்லி சென்று பிரதமரைச் சந்தித்து ஜல்லிக்கட்டு தடை நீக்கத்திற்கான சட்ட நுணுக்கங்களை ஆலோசித்தார். குடியரசுத் தலைவரின் ஒப்புதலைப் பெற்று மிருகவதை தடுப்புச் சட்டத்தில் திருத்தம் செய்து தமிழக அரசு வரலாற்றுச் சிறப்புமிக்க அவசரச் சட்டத்தை இயற்றியது. மக்களின் ஒன்றுபட்ட குரலுக்கு முன்னால் எந்தவொரு அதிகாரமும் சட்டமும் வளைந்து கொடுக்க வேண்டும் என்பதை இந்த வெற்றி இந்திய ஜனநாயகத்திற்கு ஆணித்தரமாக உணர்த்தியது." , year:2017, parties:["unknown"], newsQuery:"அவசரச் சட்டம் இயற்றப்பட்டுத் தடை நீக்கம் 2017"},
  { id:18, season:"பருவம் 02", seasonNum:2, date:"பிப்ரவரி 5, 2017", title:"ஓ. பன்னீர்செல்வம் திடீர் ராஜினாமா", filter:"crisis", tags:[["நெருக்கடி","red"],["ஓபிஎஸ்","gray"],["சசிகலா","gray"]], desc:"சசிகலாவை முதலமைச்சராக்க வேண்டும் என்று கட்சிக்குள் அமைச்சர்கள் மற்றும் மூத்த தலைவர்கள் மூலம் திட்டமிட்ட அழுத்தம் கொடுக்கப்படத் தொடங்கியது. கட்சித் தலைமை சசிகலாவிடமும் ஆட்சித் தலைமை ஓபிஎஸ்-விடமும் இருந்த இரட்டை அதிகார மையம் சரிபட்டு வராது எனத் தீர்மானிக்கப்பட்டது. வேறு வழியின்றி, பிப்ரவரி 5 அன்று ஓ. பன்னீர்செல்வம் தனது முதலமைச்சர் பதவியை ராஜினாமா செய்வதாக முறைப்படி அறிவித்தார். அதே கூட்டத்தில் சட்டமன்றக் குழுத் தலைவராக சசிகலா ஒருமனதாகத் தேர்ந்தெடுக்கப்பட்டு முதலமைச்சராகப் பதவியேற்பதற்கான அனைத்து ஏற்பாடுகளும் தொடங்கின." , year:2017, parties:["aiadmk"], newsQuery:"ஓ. பன்னீர்செல்வம் திடீர் ராஜினாமா 2017"},
  { id:19, season:"பருவம் 02", seasonNum:2, date:"பிப்ரவரி 7, 2017 (இரவு)", title:"ஓபிஎஸ்-ன் 'தர்மயுத்தம்' தொடக்கம்", filter:"crisis", tags:[["தர்மயுத்தம்","red"],["ஓபிஎஸ்","gray"],["மெரினா","gray"]], desc:"முதலமைச்சர் பதவியை ராஜினாமா செய்த இரண்டு நாட்களுக்குப் பிறகு, இரவு 9 மணியளவில் மெரினாவில் உள்ள ஜெயலலிதா நினைவிடத்திற்கு ஓ. பன்னீர்செல்வம் தனியாக வந்தார். சமாதியின் முன் 40 நிமிடங்கள் தியானத்தில் ஈடுபட்டு பின்னர் செய்தியாளர்களிடம் ஒரு மாபெரும் குண்டை வீசினார். சசிகலா தரப்பினர் தன்னை மிரட்டியே பதவியை ராஜினாமா செய்ய வைத்ததாகவும் பகிரங்கமாகக் குற்றம் சாட்டினார். 'அம்மா என்னிடம் ஒப்படைத்த ஆட்சியைக் காப்பாற்ற நான் தனியாக நின்று போராடுவேன்' என அறிவித்து தனது வரலாற்றுச் சிறப்புமிக்க தர்மயுத்தத்தைத் தொடங்கினார். இந்த ஒற்றைப் பேட்டியால் ஆளுங்கட்சி அதிமுக நெடுக்காக இரண்டாகப் பிளந்தது." , year:2017, parties:["dmk", "aiadmk"], newsQuery:"ஓபிஎஸ்-ன் 'தர்மயுத்தம்' தொடக்கம் 2017"},
  { id:20, season:"பருவம் 02", seasonNum:2, date:"பிப்ரவரி 8, 2017", title:"கூவத்தூர் ரிசார்ட் அரசியல்", filter:"crisis", tags:[["நெருக்கடி","red"],["கூவத்தூர்","gray"],["எம்.எல்.ஏ. சிறை","gray"]], desc:"ஓபிஎஸ் தர்மயுத்தத்தால் ஈர்க்கப்பட்டுப் பல எம்.எல்.ஏ-க்கள் அவர் பக்கம் தாவத் தொடங்கியதால் சசிகலா தரப்பு கடும் அதிர்ச்சியடைந்தது. ஆட்சியைத் தக்கவைக்க 120-க்கும் மேற்பட்ட அதிமுக சட்டமன்ற உறுப்பினர்களைக் கட்சித் தலைமை அவசரமாகப் பேருந்துகளில் ஏற்றியது. காஞ்சிபுரம் அருகே உள்ள கூவத்தூர் 'கோல்டன் பே ரிசார்ட்டில்' அவர்கள் அனைவரும் செல்போன்கள் பறிக்கப்பட்டு வெளி உலகத் தொடர்பின்றி சிறைவைக்கப்பட்டனர். ஜனநாயக முறைப்படி தேர்ந்தெடுக்கப்பட்ட பிரதிநிதிகள் ஒரு ரிசார்ட்டுக்குள் அடைத்து வைக்கப்பட்ட இந்தச் சம்பவம் இந்தியத் தேர்தல் அரசியலின் மிக மோசமான கறுப்புப் பக்கங்களில் ஒன்றாகப் பதிவானது." , year:2017, parties:["dmk", "aiadmk"], newsQuery:"கூவத்தூர் ரிசார்ட் அரசியல் 2017"},
  { id:21, season:"பருவம் 02", seasonNum:2, date:"பிப்ரவரி 14, 2017", title:"சசிகலாவுக்கு 4 ஆண்டு சிறை உறுதி", filter:"verdict", tags:[["தீர்ப்பு","red"],["சசிகலா","gray"],["சொத்துக்குவிப்பு","gray"]], desc:"சசிகலா முதலமைச்சராகப் பதவியேற்க ஆளுணரின் அனுமதிக்காகக் காத்திருந்த நிலையில், 20 ஆண்டுகளாக இழுத்தடிக்கப்பட்ட சொத்துக்குவிப்பு வழக்கின் தீர்ப்பு உச்ச நீதிமன்றத்தில் வெளியானது. சசிகலா, இளவரசி மற்றும் சுதாகரன் ஆகிய மூவருக்கும் தலா 4 ஆண்டுகள் சிறைத்தண்டனையும் ₹10 கோடி அபராதமும் விதிக்கப்பட்டது. முதலமைச்சராகி விடலாம் என்ற சசிகலாவின் மாபெரும் கனவு ஒரு நொடியில் சுக்குநூறாக உடைந்தது. பெங்களூரு சிறைக்குச் செல்வதற்கு முன்பு ஜெயலலிதா நினைவிடத்தில் அவர் சபதம் ஏற்றுச் சென்ற காட்சி தமிழக அரசியல் வரலாற்றில் நீங்காத இடம்பிடித்தது." , year:2017, parties:["aiadmk"], newsQuery:"சசிகலாவுக்கு 4 ஆண்டு சிறை உறுதி 2017"},
  { id:22, season:"பருவம் 02", seasonNum:2, date:"பிப்ரவரி 14, 2017", title:"டிடிவி தினகரன் நியமனம் & ஈபிஎஸ் தேர்வு", filter:"alliance", tags:[["கூட்டணி","red"],["டிடிவி தினகரன்","gray"],["எடப்பாடி","gray"]], desc:"சிறை செல்வதற்குச் சில மணி நேரங்களுக்கு முன்பு, பல ஆண்டுகளாகக் கட்சியிலிருந்து ஒதுக்கி வைக்கப்பட்டிருந்த தன் மருமகன் டி.டி.வி. தினகரனை சசிகலா மீண்டும் கட்சிக்குள் கொண்டு வந்தார். அவரை அதிமுக-வின் துணைப் பொதுச்செயலாளராக நியமித்து கட்சியின் முழு அதிகாரத்தையும் அவர் கையில் ஒப்படைத்தார். அதேசமயம் தனக்கு விசுவாசமான எடப்பாடி கே. பழனிசாமியை முதலமைச்சர் வேட்பாளராக தேர்வு செய்தார். சசிகலா சிறை சென்றாலும், கட்சி தினகரன் கையிலும் ஆட்சி எடப்பாடி கையிலுமாகச் சசிகலா குடும்பத்தின் பிடியிலேயே தமிழகம் இருப்பதை இந்த நியமனங்கள் உறுதி செய்தன." , year:2017, parties:["dmk", "aiadmk"], newsQuery:"டிடிவி தினகரன் நியமனம் & ஈபிஎஸ் தேர்வு 2017"},
  { id:23, season:"பருவம் 03", seasonNum:3, date:"பிப்ரவரி 14, 2017", title:"சசிகலாவுக்கு 4 ஆண்டு சிறைத்தண்டனை உறுதி", filter:"verdict", tags:[["தீர்ப்பு","red"],["சசிகலா","gray"],["உச்ச நீதிமன்றம்","gray"]], desc:"20 ஆண்டுகளாக இழுபறியில் இருந்த சொத்துக்குவிப்பு வழக்கில் உச்ச நீதிமன்ற நீதிபதிகள் பினாகி சந்திர கோஷ் மற்றும் அமிதவா ராய் தங்களது இறுதித் தீர்ப்பை வாசித்தனர். பெங்களூரு சிறப்பு நீதிமன்றம் விதித்த 4 ஆண்டு சிறைத்தண்டனையையும் ₹10 கோடி அபராதத்தையும் உச்ச நீதிமன்றம் முழுமையாக உறுதி செய்தது. இதன் மூலம் முதலமைச்சராகப் பதவியேற்கும் சசிகலாவின் கனவு தகர்ந்ததுடன் அடுத்த 10 ஆண்டுகள் தேர்தலில் போட்டியிட முடியாத நிலையும் உருவானது. கூவத்தூர் ரிசார்ட்டில் இருந்த சசிகலா மற்றும் ஆதரவு எம்.எல்.ஏ-க்கள் ஒட்டுமொத்தமாக அதிர்ச்சியிலும் சோகத்திலும் உறைந்தனர். பெங்களூரு பரப்பன அக்ரஹாரா சிறைக்குக் கிளம்பும் முன் மெரினாவில் உள்ள ஜெயலலிதா சமாதியில் சசிகலா மூன்று முறை கைகளால் அடித்துச் சபதம் ஏற்ற காட்சி தமிழக வரலாற்றில் உறைந்து போனது." , year:2017, parties:["aiadmk"], newsQuery:"சசிகலாவுக்கு 4 ஆண்டு சிறைத்தண்டனை உறுதி 2017"},
  { id:24, season:"பருவம் 03", seasonNum:3, date:"பிப்ரவரி 14, 2017 (தொடர்ச்சி)", title:"டிடிவி தினகரன் துணைப் பொதுச்செயலாளராக நியமனம்", filter:"alliance", tags:[["கட்சி","red"],["டிடிவி தினகரன்","gray"],["சசிகலா","gray"]], desc:"தான் சிறைக்குச் சென்றாலும் கட்சியின் கட்டுப்பாடு தன் குடும்பத்தை விட்டுப் போய்விடக் கூடாது என்பதில் சசிகலா மிகவும் தீவிரமாகச் செயல்பட்டார். ஜெயலலிதாவால் கட்சியிலிருந்து நீக்கப்பட்டு போயஸ் கார்டனை விட்டு ஒதுக்கி வைக்கப்பட்டிருந்த தன் மருமகன் டி.டி.வி. தினகரனை அவசரமாக மீண்டும் கட்சிக்குள் சேர்த்தார். கட்சியின் விதிகளைப் பயன்படுத்தி டி.டி.வி. தினகரனை அதிமுக-வின் துணைப் பொதுச்செயலாளராக அதிரடியாக நியமித்து முழு அதிகாரத்தையும் அவர் வசம் ஒப்படைத்தார். இந்த நியமனம் ஓபிஎஸ் அணியினரை மட்டுமன்றி கட்சியில் நீண்டகாலமாக இருந்த பல மூத்த நிர்வாகிகளையும் உள்ளுக்குள் அதிருப்தியடையச் செய்தது. சசிகலாவின் இந்த ஒற்றை நகர்வு சிறைக்குப் பின்னாலிருந்தும் போயஸ் கார்டன் குடும்பமே அதிமுக-வை இயக்கும் என்பதை வெளிப்படையாக அறிவித்தது." , year:2017, parties:["dmk", "aiadmk"], newsQuery:"டிடிவி தினகரன் துணைப் பொதுச்செயலாளராக நியமனம் 2017"},
  { id:25, season:"பருவம் 03", seasonNum:3, date:"பிப்ரவரி 14, 2017 (தொடர்ச்சி)", title:"முதல்வர் வேட்பாளராக எடப்பாடி கே. பழனிசாமி தேர்வு", filter:"alliance", tags:[["கூட்டணி","red"],["எடப்பாடி","gray"],["கூவத்தூர்","gray"]], desc:"சசிகலா சிறை தண்டனை பெற்றதால் கூவத்தூர் ரிசார்ட்டில் அடைக்கப்பட்டிருந்த 120-க்கும் மேற்பட்ட எம்.எல்.ஏ-க்களை வழிநடத்த புதிய சட்டமன்றக் குழுத் தலைவர் தேர்வு அவசியமானது. சசிகலாவின் தீவிர விசுவாசியாகவும் கொங்கு மண்டலத்தின் பலமான முகமாகவும் இருந்த நெடுஞ்சாலைத்துறை அமைச்சர் எடப்பாடி கே. பழனிசாமி முதல்வர் வேட்பாளராக முன்மொழியப்பட்டார். கூவத்தூர் ரிசார்ட்டில் அவசரமாகக் கூடிய எம்.எல்.ஏ-க்கள் கூட்டத்தில் ஈபிஎஸ் ஒருமனதாகத் தலைவராகத் தேர்ந்தெடுக்கப்பட்டு ஆளுணருக்கு கடிதம் அனுப்பப்பட்டது. அதுவரை பெரிய அளவில் ஊடக வெளிச்சம் இல்லாத எடப்பாடி பழனிசாமி தமிழகத்தின் மிக உயரிய அதிகார பீடத்தை நோக்கி நகர்ந்த மிக முக்கியமான திருப்புமுனை இதுவாகும். ஓபிஎஸ் வசம் எம்.எல்.ஏ-க்கள் யாரும் தாவிவிடக் கூடாது என்பதற்காக தேர்வு முடிந்த நிமிடமே ரிசார்ட்டில் பாதுகாப்பு பல மடங்கு அதிகரிக்கப்பட்டது." , year:2017, parties:["aiadmk"], newsQuery:"முதல்வர் வேட்பாளராக எடப்பாடி கே. பழனிசாமி தேர்வு 2017"},
  { id:26, season:"பருவம் 03", seasonNum:3, date:"பிப்ரவரி 16, 2017", title:"முதலமைச்சராக எடப்பாடி கே. பழனிசாமி பதவியேற்பு", filter:"oath", tags:[["பதவியேற்பு","red"],["எடப்பாடி","gray"],["ஆளுணர் மாளிகை","gray"]], desc:"கூவத்தூர் எம்.எல்.ஏ-க்களின் ஆதரவுக் கடிதத்தை ஏற்றுக்கொண்ட ஆளுணர் சி. வித்தியாசாகர் ராவ் எடப்பாடி பழனிசாமியை ஆட்சி அமைக்க அழைத்தார். சென்னை ஆளுணர் மாளிகையில் நடந்த எளிய விழாவில் எடப்பாடி கே. பழனிசாமி முதலமைச்சராக முறைப்படி பதவிப் பிரமாணம் எடுத்துக் கொண்டார். அவருடன் ஓபிஎஸ் நீங்கலாக ஜெயலலிதா அமைச்சரவையில் இருந்த 31 அமைச்சர்களும் மீண்டும் அதே இலாகாக்களுடன் பதவியேற்றனர். பதவியேற்றவுடன் 15 நாட்களுக்குள் சட்டமன்றத்தில் பெரும்பான்மையை நிரூபிக்க வேண்டும் என்று ஆளுணர் ஈபிஎஸ்-க்கு உத்தரவிட்டார். பதவிப் பிரமாணத்தின் போது ஈபிஎஸ் மற்றும் அமைச்சர்கள் ஜெயலலிதா மற்றும் சசிகலாவின் படங்களைச் சட்டைப் பையில் வைத்திருந்தது விசுவாச அரசியலின் உச்சமாகக் கருதப்பட்டது." , year:2017, parties:["aiadmk"], newsQuery:"முதலமைச்சராக எடப்பாடி கே. பழனிசாமி பதவியேற்பு 2017"},
  { id:27, season:"பருவம் 03", seasonNum:3, date:"பிப்ரவரி 18, 2017", title:"சட்டசபையில் நம்பிக்கை வாக்கெடுப்பும் மாபெரும் கலவரமும்", filter:"crisis", tags:[["நெருக்கடி","red"],["சட்டசபை","gray"],["திமுக","gray"]], desc:"முதலமைச்சர் எடப்பாடி பழனிசாமி தனது அரசின் மீதான நம்பிக்கை வாக்கெடுப்பைக் கோருவதற்காகத் தமிழகச் சட்டமன்றத்தின் சிறப்புக் கூட்டத்தொடர் கூடியது. ரகசிய வாக்குப்பதிவு கோரி எதிர்க்கட்சித் தலைவர் மு.க.ஸ்டாலின் தலைமையிலான திமுக எம்.எல்.ஏ-க்கள் சபாநாயகர் இருக்கையை முற்றுகையிட்டுப் பெரும் அமளியில் ஈடுபட்டனர். சபாநாயகர் தனபாலின் சட்டை கிழிக்கப்பட்டு மாபெரும் வன்முறை வெடித்ததால் மார்ஷல்கள் மூலம் திமுக எம்.எல்.ஏ-க்கள் அனைவரும் குண்டுக்கட்டாக வெளியேற்றப்பட்டனர். சட்டை கிழிந்த நிலையிலேயே எதிர்க்கட்சித் தலைவர் மு.க.ஸ்டாலின் நேராக மெரினா கடற்கரைக்குச் சென்று ஆளுணருக்கு எதிராகத் திடீர் தர்ணா போராட்டத்தில் ஈடுபட்டார். தமிழகச் சட்டமன்ற வரலாற்றில் ஜனநாயகம் மிக மோசமாகக் கேள்விக்குறியாக்கப்பட்ட கறுப்பு நாளாக இந்த பிப்ரவரி 18 தடம் பதித்தது." , year:2017, parties:["dmk", "aiadmk"], newsQuery:"சட்டசபையில் நம்பிக்கை வாக்கெடுப்பும் மாபெரும் கலவரமும் 2017"},
  { id:28, season:"பருவம் 03", seasonNum:3, date:"பிப்ரவரி 18, 2017 (தொடர்ச்சி)", title:"122–11 கணக்கில் நம்பிக்கை வாக்கெடுப்பில் ஈபிஎஸ் வெற்றி", filter:"verdict", tags:[["தீர்ப்பு","red"],["எடப்பாடி","gray"],["122 வாக்குகள்","gray"]], desc:"பிரதான எதிர்க்கட்சியான திமுக முழுமையாக வெளியேற்றப்பட்ட பின்னரும் காங்கிரஸ் உறுப்பினர்கள் அவையைப் புறக்கணித்த நிலையிலும் வாக்கெடுப்பு நடைபெற்றது. கூவத்தூர் ரிசார்ட்டில் இருந்து பலத்த பாதுகாப்புடன் அழைத்து வரப்பட்ட சசிகலா அணியின் 122 எம்.எல்.ஏ-க்களும் எடப்பாடி பழனிசாமிக்கு ஆதரவாக வாக்களித்தனர். ஓ. பன்னீர்செல்வம் தலைமையிலான தர்மயுத்த அணியின் 11 எம்.எல்.ஏ-க்கள் மட்டுமே ஈபிஎஸ் அரசுக்கு எதிராக வாக்களித்தனர். வாக்கெடுப்பின் முடிவில் சபாநாயகர் தனபால் எடப்பாடி பழனிசாமி தலைமையிலான அரசு 122 வாக்குகளுடன் பெரும்பான்மையை வெற்றிகரமாக நிரூபித்ததாக அறிவித்தார். அனைத்து அரசியல் சவால்களையும் கூவத்தூர் உத்திகளையும் தாண்டி எடப்பாடி பழனிசாமியின் ஆட்சிக்கான அஸ்திவாரம் அதிகாரப்பூர்வமாக நிலைநிறுத்தப்பட்டது." , year:2017, parties:["dmk", "aiadmk", "congress"], newsQuery:"122–11 கணக்கில் நம்பிக்கை வாக்கெடுப்பில் ஈபிஎஸ் வெற்றி 2017"},
  { id:29, season:"பருவம் 03", seasonNum:3, date:"மார்ச் 22, 2017", title:"தேர்தல் ஆணையத்தால் 'இரட்டை இலை' சின்னம் முடக்கம்", filter:"verdict", tags:[["தீர்ப்பு","red"],["இரட்டை இலை","gray"],["தேர்தல் ஆணையம்","gray"]], desc:"ஜெயலலிதா மறைவால் காலியான ஆர்.கே. நகர் சட்டமன்றத் தொகுதிக்கு இடைத்தேர்தல் நடத்தப்படும் எனத் தேர்தல் ஆணையம் அறிவித்தது. இதில் சசிகலா அணி சார்பாக டிடிவி தினகரனும் ஓபிஎஸ் அணி சார்பாக இ. மதுசூதனனும் போட்டியிடப் போவதாக அறிவித்து 'இரட்டை இலை' சின்னத்திற்கு உரிமை கோரினர். இரு தரப்பும் லட்சக்கணக்கான பக்கங்கள் கொண்ட பிரமாணப் பத்திரங்களை டெல்லி தேர்தல் ஆணையத்தில் தாக்கல் செய்து வாதிட்டனர். இரு அணிகளின் முரண்பட்ட வாதங்களால் இடைக்கால உத்தரவாக அதிமுக-வின் அதிகாரப்பூர்வ பெயரையும் பாரம்பரியமிக்க 'இரட்டை இலை' சின்னத்தையும் தேர்தல் ஆணையம் அதிரடியாக முடக்கியது. ஈபிஎஸ் அணி 'அதிமுக அம்மா' என்றும் ஓபிஎஸ் அணி 'அதிமுக புரட்சித் தலைவி அம்மா' என்றும் புதிய பெயர்களில் களம் கண்டன." , year:2017, parties:["dmk", "aiadmk"], newsQuery:"தேர்தல் ஆணையத்தால் 'இரட்டை இலை' சின்னம் முடக்கம் 2017"},
  { id:30, season:"பருவம் 03", seasonNum:3, date:"ஏப்ரல் 7, 2017", title:"அமைச்சர் சி. விஜயபாஸ்கர் இல்லத்தில் மெகா ஐடி ரெய்டு", filter:"raid", tags:[["ரெய்டு","red"],["விஜயபாஸ்கர்","gray"],["ஆர்.கே. நகர்","gray"]], desc:"ஆர்.கே. நகர் இடைத்தேர்தல் பிரச்சாரம் இறுதிக் கட்டத்தை எட்டியிருந்த வேளையில் தேர்தல் வரலாற்றிலேயே இல்லாத வகையில் ஒரு மாபெரும் அதிரடி திருப்பம் நிகழ்ந்தது. டிடிவி தினகரனின் தேர்தல் பொறுப்பாளராகவும் சுகாதாரத்துறை அமைச்சராகவும் இருந்த சி. விஜயபாஸ்கரின் சென்னை இல்லம் மற்றும் புதுக்கோட்டை கல்குவாரிகளில் ஐடி துறை புகுந்தது. அதிகாலை 5 மணி முதல் சிஆர்பிஎஃப் துணையுடன் வருமான வரித்துறை புலனாய்வுப் பிரிவினர் மெகா சோதனையை நடத்தினர். சோதனையின் போது அமைச்சரின் ஆதரவாளர்கள் ஐடி அதிகாரிகளுடன் வாக்குவாதத்தில் ஈடுபட்டு சில முக்கிய ஆவணங்களை வெளியில் வீசி எறிந்ததாகப் பரபரப்பு குற்றச்சாட்டுகள் எழுந்தன. ஆளுங்கட்சியின் மிக முக்கிய அமைச்சர் வீட்டில் தேர்தல் நேரத்தில் நடந்த இந்த ரெய்டு டெல்லியின் நேரடி அரசியல் ஆட்டத்தை வெளிப்படையாகக் காட்டியது." , year:2017, parties:["it_dept"], newsQuery:"அமைச்சர் சி. விஜயபாஸ்கர் இல்லத்தில் மெகா ஐடி ரெய்டு 2017"},
  { id:31, season:"பருவம் 03", seasonNum:3, date:"ஏப்ரல் 9, 2017", title:"89 கோடி பணப்பட்டுவாடா ஆவணங்கள் சிக்கியதால் ஆர்.கே. நகர் தேர்தல் ரத்து", filter:"election", tags:[["தேர்தல்","red"],["ஆர்.கே. நகர்","gray"],["₹89 கோடி","gray"]], desc:"அமைச்சர் விஜயபாஸ்கர் வீட்டில் நடந்த ஐடி சோதனையில் ஆர்.கே. நகர் வாக்காளர்களுக்குப் பணம் விநியோகம் செய்வதற்காகத் தயாரிக்கப்பட்ட ரகசிய ஆவணங்கள் மற்றும் 'டார்கெட் ஷீட்கள்' சிக்கின. தொகுதி முழுவதும் உள்ள வாக்காளர்களுக்கு விநியோகிக்க ₹89 கோடி ரூபாய் பல்வேறு அமைச்சர்களிடம் பிரித்து வழங்கப்பட்டிருந்த விபரங்கள் அச்சு அசலாகக் குறிப்பிடப்பட்டிருந்தன. இந்த ஆவணங்களின் அடிப்படையில் தேர்தல் நேர்மையாக நடக்க வாய்ப்பில்லை எனத் தீர்மானித்த இந்தியத் தேர்தல் ஆணையம் ஆர்.கே. நகர் இடைத்தேர்தலை அதிகாரப்பூர்வமாக ரத்து செய்தது. ஒட்டுமொத்த இந்திய ஜனநாயகத்திற்கும் தமிழக தேர்தல் முறைக்கும் உலக அளவில் ஒரு மாபெரும் களங்கத்தை ஏற்படுத்திய சம்பவமாக இது பார்க்கப்பட்டது." , year:2017, parties:["unknown"], newsQuery:"89 கோடி பணப்பட்டுவாடா ஆவணங்கள் சிக்கியதால் ஆர்.கே. நகர் தேர்தல் ரத்து 2017"},
  { id:32, season:"பருவம் 03", seasonNum:3, date:"ஏப்ரல் 18, 2017", title:"நள்ளிரவு அதிரடி: தினகரன் குடும்பம் அதிமுக-விலிருந்து ஒதுக்கம்", filter:"alliance", tags:[["கட்சி","red"],["டிடிவி தினகரன்","gray"],["நள்ளிரவு அறிவிப்பு","gray"]], desc:"ஆர்.கே. நகர் தேர்தல் ரத்து மற்றும் டெல்லி ஏஜென்சிகளின் தொடர் நெருக்கடிகளால் எடப்பாடி பழனிசாமி தலைமையிலான அமைச்சர்கள் கடும் பீதிக்குள்ளாகினர். ஓபிஎஸ் அணியுடன் இணைந்தால் மட்டுமே ஆட்சியைக் காப்பாற்ற முடியும் என்ற சூழலில் சசிகலா குடும்பத்தை நீக்க வேண்டும் என்ற ஓபிஎஸ்-ன் நிபந்தனையை ஏற்க அமைச்சர்கள் முன்வந்தனர். ஏப்ரல் 18 நள்ளிரவில் அதிமுக தலைமைக் கழகத்தில் அவசரமாகக் கூடிய அமைச்சர்கள் சசிகலா மற்றும் டிடிவி தினகரன் குடும்பத்தினரைக் கட்சியிலிருந்து முழுமையாக ஒதுக்கி வைப்பதாகப் பிரகடனம் செய்தனர். நிதியமைச்சர் ஜெயக்குமார் 'கட்சியும் ஆட்சியும் இனி சசிகலா குடும்பத்தின் தலையீடு இன்றி தனித்து இயங்கும்' என்ற வரலாற்றுச் சிறப்புமிக்க நள்ளிரவு அறிவிப்பை வெளியிட்டார். கூவத்தூரில் தங்களை வாழ வைத்த சசிகலா குடும்பத்தை பதவி சுகத்திற்காக ஈபிஎஸ் அணியினர் முதன்முறையாகக் கைவிட்ட மாபெரும் துரோக அரசியல் புள்ளி இதுவாகும்." , year:2017, parties:["dmk", "aiadmk"], newsQuery:"நள்ளிரவு அதிரடி: தினகரன் குடும்பம் அதிமுக-விலிருந்து ஒதுக்கம் 2017"},
  { id:33, season:"பருவம் 04", seasonNum:4, date:"ஏப்ரல் 24, 2017 (நள்ளிரவு)", title:"கொடநாடு எஸ்டேட் கொள்ளை & காவலாளி ஓம்பகதூர் கொடூரக் கொலை", filter:"crisis", tags:[["கொடூரக் கொலை","red"],["கொடநாடு","gray"],["மர்மம்","gray"]], desc:"நீலகிரி மலையில் அமைந்துள்ள ஜெயலலிதாவின் மிக ரகசியமான கோட்டையாகக் கருதப்படும் 900 ஏக்கர் பரப்பளவு கொண்ட கொடநாடு எஸ்டேட் பங்களாவிற்குள் நள்ளிரவில் ஒரு ஆயுதமேந்திய கும்பல் புகுந்தது. நேபாள நாட்டைச் சேர்ந்த காவலாளி ஓம்பகதூரை கும்பல் கத்தி மற்றும் ஆயுதங்களால் கொடூரமாகக் கொலை செய்து மரத்தில் தொங்கவிட்டது. மற்றொரு காவலாளி கிஷன் பகதூரைத் தாக்கி கட்டிப்போட்டுவிட்டு பங்களாவின் கதவுகளை உடைத்து முக்கிய ரகசிய ஆவணங்கள் மற்றும் நகைகளைக் கொள்ளையடித்தனர். ஜெயலலிதா மறைவுக்குப் பின் அங்கு வைக்கப்பட்டிருந்த பல கோடி மதிப்புள்ள சொத்து விபரங்கள் மற்றும் அரசியல் ரகசியங்கள் அடங்கிய டைரிகளை எடுக்கவே இந்தத் துணிகரக் கொள்ளை நடந்ததாகக் கூறப்பட்டது. ஷோலூர்மட்டம் காவல் நிலையத்தில் பதிவு செய்யப்பட்ட இந்த வழக்கு (FIR No. 51/2017) தமிழக வரலாற்றின் மிக நீளமான மற்றும் பயங்கரமான அரசியல் மர்மக் கதையாக மாறியது." , year:2017, parties:["aiadmk"], newsQuery:"கொடநாடு எஸ்டேட் கொள்ளை & காவலாளி ஓம்பகதூர் கொடூரக் கொலை 2017"},
  { id:34, season:"பருவம் 04", seasonNum:4, date:"ஏப்ரல் 25, 2017 (நள்ளிரவு)", title:"இரட்டை இலைக்கு லஞ்சம்: டெல்லியில் டிடிவி தினகரன் கைது", filter:"verdict", tags:[["கைது","red"],["டிடிவி தினகரன்","gray"],["₹50 கோடி லஞ்சம்","gray"]], desc:"முடக்கப்பட்ட இரட்டை இலைச் சின்னத்தைத் தனது அணிக்குப் பெற்றுத்தரத் தேர்தல் ஆணைய அதிகாரிகளுக்கு ₹50 கோடி லஞ்சம் கொடுக்க முயன்றதாகப் புகார் வெடித்தது. டெல்லி நட்சத்திர விடுதியில் சொகுசு கார் மற்றும் ₹1.3 கோடி ரொக்கத்துடன் பிடிபட்ட இடைத்தரகர் சுகேஷ் சந்திரசேகரன் அளித்த வாக்குமூலத்தின் அடிப்படையில் வழக்கு பதியப்பட்டது. டெல்லி குற்றப்பிரிவு (Crime Branch) போலீசார் சென்னை வந்து தங்கியிருந்த டிடிவி தினகரனிடம் தொடர்ந்து 4 நாட்கள் நள்ளிரவு வரை தீவிர விசாரணை நடத்தினர். விசாரணை முடிவில் ஏப்ரல் 25 நள்ளிரவில் டிடிவி தினகரன் மற்றும் அவரது உதவியாளர் ஜனார்த்தனனை டெல்லி போலீசார் கைது செய்து திகார் சிறையில் அடைத்தனர். சசிகலா சிறை சென்ற சில வாரங்களிலேயே தினகரனும் சிறைக்குச் சென்றது போயஸ் கார்டன் குடும்பத்தின் அதிகார பலத்தை முழுமையாக முடக்கும் டெல்லியின் சாணக்கிய உத்தியாகப் பார்க்கப்பட்டது." , year:2017, parties:["aiadmk"], newsQuery:"இரட்டை இலைக்கு லஞ்சம்: டெல்லியில் டிடிவி தினகரன் கைது 2017"},
  { id:35, season:"பருவம் 04", seasonNum:4, date:"ஏப்ரல் 28, 2017", title:"கொடநாடு மர்மம் 1: சேலத்தில் ஓட்டுநர் கனகராஜ் மர்ம விபத்தில் பலி", filter:"crisis", tags:[["மர்மம்","red"],["கனகராஜ்","gray"],["கொடநாடு","gray"]], desc:"கொடநாடு கொலை மற்றும் கொள்ளை வழக்கில் முதன்மைக் குற்றவாளியாகவும் ஜெயலலிதாவின் முன்னாள் கார் ஓட்டுநராகவும் இருந்த சேலம் இடைப்பாடியைச் சேர்ந்த கனகராஜ் தேடப்பட்டு வந்தார். போலீசார் அவரைப் பிடிப்பதற்குள் சேலம் மாவட்டம் ஆத்தூர் அருகே இருசக்கர வாகனத்தில் சென்றுகொண்டிருந்த கனகராஜ் மீது ஒரு கார் மோதி அவர் சம்பவ இடத்திலேயே மர்மமான முறையில் உயிரிழந்தார். கொடநாடு பங்களாவில் எந்தெந்த அறைகளில் என்னென்ன ஆவணங்கள் உள்ளன என்பதை நன்கு அறிந்த ஒரே நபர் கனகராஜ் மட்டுமே என்பது குறிப்பிடத்தக்கது. அவர் இறப்பதற்குச் சில மணி நேரங்களுக்கு முன்பு வரை பல முக்கிய அரசியல் புள்ளிகளுடன் போனில் பேசியதாகத் தகவல்கள் வெளியாகிப் பரபரப்பைக் கூட்டின. முக்கியக் குற்றவாளி விபத்தில் பலியானது கொடநாடு வழக்கின் பின்னால் உள்ள உண்மைகளை மூடி மறைப்பதற்காக நடத்தப்பட்ட திட்டமிட்ட கொலையா என்ற சந்தேகத்தை எழுப்பியது." , year:2017, parties:["aiadmk"], newsQuery:"கொடநாடு மர்மம் 1: சேலத்தில் ஓட்டுநர் கனகராஜ் மர்ம விபத்தில் பலி 2017"},
  { id:36, season:"பருவம் 04", seasonNum:4, date:"ஏப்ரல் 29, 2017", title:"கொடநாடு மர்மம் 2: கேரளாவில் சயான் கார் விபத்து; மனைவி-மகள் சம்பவ இடத்திலேயே பலி", filter:"crisis", tags:[["மர்மம்","red"],["சயான்","gray"],["கேரளா விபத்து","gray"]], desc:"கனகராஜ் இறந்த அடுத்த சில மணி நேரங்களிலேயே கொடநாடு வழக்கின் இரண்டாம் குற்றவாளியான சயான் (கோவை) மீதும் மரண பயம் சூழ்ந்தது. சயான் தனது குடும்பத்துடன் காரில் கேரளா நோக்கிச் சென்றுகொண்டிருந்தபோது பாலக்காடு அருகே சாலையோரம் நின்றிருந்த லாரி மீது அவரது கார் அதிவேகமாக மோதி நொறுங்கியது. இந்த அதிபயங்கர விபத்தில் சயானின் மனைவி வினுப்பிரியா மற்றும் அவரது 5 வயது மகள் நீது ஆகியோர் சம்பவ இடத்திலேயே ரத்த வெள்ளத்தில் பலியாயினர். சயான் மிகக் கடுமையான காயங்களுடன் உயிர் தப்பி கோவையில் உள்ள தனியார் மருத்துவமனையின் தீவிர சிகிச்சைப் பிரிவில் அனுமதிக்கப்பட்டார். 24 மணி நேர இடைவெளியில் கொடநாடு வழக்கின் முதல் இரண்டு குற்றவாளிகள் மீது ஒரே மாதிரியான விபத்துக்கள் நிகழ்ந்தது தமிழக மக்களை உறைந்து போகச் செய்தது." , year:2017, parties:["unknown"], newsQuery:"கொடநாடு மர்மம் 2: கேரளாவில் சயான் கார் விபத்து; மனைவி-மகள் சம்பவ இடத்திலேயே பலி 2017"},
  { id:37, season:"பருவம் 04", seasonNum:4, date:"ஜூலை 3, 2017", title:"கொடநாடு மர்மம் 3: சிசிடிவி ஆபரேட்டர் தினேஷ் குமார் மர்மத் தற்கொலை", filter:"crisis", tags:[["மர்மம்","red"],["தினேஷ் குமார்","gray"],["சிசிடிவி","gray"]], desc:"கொடநாடு எஸ்டேட் கொள்ளை நடந்த நள்ளிரவில் அங்குள்ள அதிநவீன சிசிடிவி (CCTV) கேமராக்கள் மற்றும் கணினி அமைப்புகள் அனைத்தும் திட்டமிட்டு அணைக்கப்பட்டிருந்தன. அந்த எஸ்டேட்டின் கணினிப் பிரிவில் நீண்டகாலமாக ஆபரேட்டராகவும் கணக்காளராகவும் பணியாற்றி வந்த கோத்தகிரியைச் சேர்ந்த 24 வயது இளைஞர் தினேஷ் குமார் ஆவார். போலீசார் சிசிடிவி காட்சிகள் அழிக்கப்பட்டது குறித்து தினேஷ் குமாரிடம் விசாரணை நடத்தத் திட்டமிட்டிருந்த வேளையில் அவர் கோத்தகிரியில் உள்ள வீட்டில் தூக்கில் தொங்கியபடி பிணமாகக் கண்டெடுக்கப்பட்டார். அவரது உடலைக் கைப்பற்றிய கோத்தகிரி போலீசார் இது தற்கொலை என்று வழக்குப்பதிவு செய்து விசாரணையை முடிவுக்குக் கொண்டு வர முயன்றனர். கொடநாடு பங்களாவின் ரகசியங்களை அறிந்த 4 பேர் அடுத்தடுத்து மரணமடைந்தது இந்த வழக்கைத் தமிழ்நாட்டின் மிக விவரிக்க முடியாத ஒரு அரசியல் மர்மமாக மாற்றியது." , year:2017, parties:["unknown"], newsQuery:"கொடநாடு மர்மம் 3: சிசிடிவி ஆபரேட்டர் தினேஷ் குமார் மர்மத் தற்கொலை 2017"},
  { id:38, season:"பருவம் 04", seasonNum:4, date:"ஆகஸ்ட் 10, 2017", title:"கட்சிப் பதவியிலிருந்து தினகரன் நீக்கம்", filter:"alliance", tags:[["கட்சி","red"],["தினகரன்","gray"],["நீக்கம்","gray"]], desc:"திகார் சிறையிலிருந்து ஜாமீனில் வெளிவந்த டிடிவி தினகரன் தன்னை ஒதுக்கிய அமைச்சர்களுக்குப் பாடம் புகட்ட எம்.எல்.ஏ-க்களைத் தன் பக்கம் இழுக்கும் பணிகளில் தீவிரமாக இறங்கினார். இதனால் அதிருப்தியடைந்த முதலமைச்சர் எடப்பாடி பழனிசாமி தலைமைக் கழகத்தில் கட்சியின் அவசர ஆலோசனைக் கூட்டத்தைக் கூட்டினார். அந்தக் கூட்டத்தில் டிடிவி தினகரன் கட்சியின் துணைப் பொதுச்செயலாளர் நியமனம் செல்லாது என்றும் அவரை பதவியிலிருந்து முழுமையாக நீக்குவதாகவும் அதிரடித் தீர்மானம் நிறைவேற்றப்பட்டது. மேலும் தினகரன் பிறப்பிக்கும் உத்தரவுகள் மற்றும் நியமனங்கள் எதையும் அதிமுக தொண்டர்கள் யாரும் மதிக்கக் கூடாது என ஈபிஎஸ் தரப்பு அதிகாரப்பூர்வமாக அறிவித்தது. சசிகலாவால் நாற்காலியில் அமரவைக்கப்பட்ட எடப்பாடி பழனிசாமி அதே சசிகலாவின் குடும்பத்திற்கு எதிராகத் தனது முழு அதிகாரத்தையும் பிரயோகித்த முக்கியப் புள்ளி இதுவாகும்." , year:2017, parties:["dmk", "aiadmk"], newsQuery:"கட்சிப் பதவியிலிருந்து தினகரன் நீக்கம் 2017"},
  { id:39, season:"பருவம் 04", seasonNum:4, date:"ஆகஸ்ட் 21, 2017", title:"ஓபிஎஸ் – ஈபிஎஸ் அணிகள் இணைப்பு (Merger)", filter:"alliance", tags:[["இணைப்பு","red"],["ஓபிஎஸ்","gray"],["ஈபிஎஸ்","gray"]], desc:"சசிகலா மற்றும் தினகரன் குடும்பத்தை முழுமையாகக் கட்சியிலிருந்து ஒதுக்கி வைக்க இரு தரப்பும் சம்மதித்ததைத் தொடர்ந்து அணிகள் இணைப்புக்கான இறுதி ஒப்பந்தம் தயாரானது. சென்னை ராயப்பேட்டையில் உள்ள அதிமுக தலைமை அலுவலகத்தில் முதலமைச்சர் எடப்பாடி பழனிசாமியும் ஓ. பன்னீர்செல்வமும் கைகளைக் கோர்த்துக்கொண்டு தங்களது அணிகள் இணைப்பை முறைப்படி அறிவித்தனர். கட்சியின் ஒருங்கிணைப்பாளராக ஓ. பன்னீர்செல்வமும் இணை ஒருங்கிணைப்பாளராக முதலமைச்சர் எடப்பாடி பழனிசாமியும் புதிய தற்காலிகப் பதவிகளை உருவாக்கிக் கொண்டனர். சசிகலாவின் படங்களும் பேனர்களும் அதிமுக அலுவலகத்தில் இருந்து உடனடியாகக் கிழிக்கப்பட்டு ஓபிஎஸ்-ன் 6 மாத கால 'தர்மயுத்தம்' ஒரு வழியாய் முடிவுக்கு வந்தது. இந்த இணைப்பின் மூலம் தமிழ்நாட்டின் ஒட்டுமொத்த அரசியல் அதிகாரமும் கொங்கு மண்டலம் மற்றும் தென் மாவட்டங்களின் கூட்டுப் பொறுப்பிற்குள் வந்தது." , year:2017, parties:["dmk", "aiadmk"], newsQuery:"ஓபிஎஸ் – ஈபிஎஸ் அணிகள் இணைப்பு (Merger) 2017"},
  { id:40, season:"பருவம் 04", seasonNum:4, date:"ஆகஸ்ட் 21, 2017 (மாலை)", title:"துணை முதலமைச்சராக ஓ. பன்னீர்செல்வம் பதவியேற்பு", filter:"oath", tags:[["பதவியேற்பு","red"],["ஓபிஎஸ்","gray"],["துணை முதல்வர்","gray"]], desc:"அணிகள் இணைந்த அன்றே மாலையில் சென்னை கிண்டியில் உள்ள ஆளுணர் மாளிகையில் அவசரமாகப் பதவியேற்பு விழா ஏற்பாடுகள் செய்யப்பட்டன. தமிழக வரலாற்றிலேயே முதன்முறையாக துணை முதலமைச்சர் என்ற புதிய பதவி உருவாக்கப்பட்டு ஓ. பன்னீர்செல்வம் துணை முதல்வராகப் பதவிப் பிரமாணம் எடுத்துக் கொண்டார். அவருக்கு நிதி, வீட்டுவசதி மற்றும் நகர்ப்புற வளர்ச்சி உள்ளிட்ட மிக முக்கிய இலாகாக்கள் முதலமைச்சர் எடப்பாடி பழனிசாமியால் ஒதுக்கப்பட்டன. ஓபிஎஸ் அணியைச் சேர்ந்த மாஃபா பாண்டியராஜன் தமிழ் வளர்ச்சி மற்றும் தொல்லியல் துறை அமைச்சராகப் பொறுப்பேற்றுக் கொண்டார். சசிகலாவை வீழ்த்த வேண்டும் என்ற ஒற்றை இலக்கில் டெல்லி பாஜ தலைமையின் ஆலோசனையின் பேரில் இந்த ஆட்சிப் பகிர்வு கச்சிதமாக அரங்கேறியது." , year:2017, parties:["aiadmk"], newsQuery:"துணை முதலமைச்சராக ஓ. பன்னீர்செல்வம் பதவியேற்பு 2017"},
  { id:41, season:"பருவம் 04", seasonNum:4, date:"ஆகஸ்ட் 22, 2017", title:"தினகரன் ஆதரவு 19 எம்.எல்.ஏ-க்கள் ஆளுணரிடம் அதிரடி கடிதம்", filter:"crisis", tags:[["நெருக்கடி","red"],["19 எம்.எல்.ஏ","gray"],["ஆளுணர் கடிதம்","gray"]], desc:"ஈபிஎஸ் – ஓபிஎஸ் அணிகள் இணைந்த அடுத்த 24 மணி நேரத்திற்குள் முதலமைச்சர் எடப்பாடி பழனிசாமியின் ஆட்சிக்கு மிகப் பெரிய ஆபத்து முளைத்தது. டிடிவி தினகரனின் பின்னால் அணிவகுத்த 19 அதிமுக எம்.எல்.ஏ-க்கள் (வி. செந்தில் பாலாஜி, தங்கத்தமிழ்செல்வன் உட்பட) பொறுப்பு ஆளுணர் வித்தியாசாகர் ராவை ராஜ்பவனில் சந்தித்தனர். அவர்கள் ஆளுணரிடம் அளித்த கடிதத்தில் 'முதலமைச்சர் எடப்பாடி பழனிசாமி மீது நாங்கள் வைத்திருந்த நம்பிக்கையை வாபஸ் பெறுகிறோம்; புதிய முதலமைச்சரைத் தேர்ந்தெடுக்க உத்தரவிட வேண்டும்' எனக் குறிப்பிட்டிருந்தனர். இந்த அதிரடி நகர்வால் எடப்பாடி அரசு நாடாளுமன்றத்தில் தங்களது பெரும்பான்மையை இழந்து எந்த நிமிடமும் கவிழும் என்ற இக்கட்டான சிக்கலுக்குள் சிக்கியது. கடிதம் கொடுத்த 19 எம்.எல்.ஏ-க்களும் உடனடியாக புதுச்சேரியில் உள்ள 'விண்ட்ஃபிளவர்' ரிசார்ட்டிற்குப் பாதுகாப்பிற்காகக் கடத்திச் செல்லப்பட்டனர்." , year:2017, parties:["dmk", "aiadmk"], newsQuery:"தினகரன் ஆதரவு 19 எம்.எல்.ஏ-க்கள் ஆளுணரிடம் அதிரடி கடிதம் 2017"},
  { id:42, season:"பருவம் 04", seasonNum:4, date:"செப்டம்பர் 12, 2017", title:"சசிகலா நீக்கம் & ஜெ. 'நிரந்தரப் பொதுச்செயலாளர்' அறிவிப்பு", filter:"alliance", tags:[["கட்சி","red"],["சசிகலா நீக்கம்","gray"],["ஜெயலலிதா நினைவு","gray"]], desc:"தினகரன் அணியின் மிரட்டல்களை எதிர்கொள்ள ஒருங்கிணைந்த அதிமுக-வின் பொதுக்குழு மற்றும் செயற்குழு கூட்டம் சென்னை வானகரத்தில் பிரம்மாண்டமாகக் கூடியது. இந்த வரலாற்று முக்கியத்துவம் வாய்ந்த கூட்டத்தில் வி.கே. சசிகலாவை தற்காலிகப் பொதுச்செயலாளர் பதவியிலிருந்து முழுமையாக நீக்கி அதிரடித் தீர்மானம் நிறைவேற்றப்பட்டது. மேலும் சசிகலா சிறைக்குச் செல்லும் முன் செய்த டிடிவி தினகரனின் நியமனங்கள் மற்றும் அனைத்துக் கட்சி உத்தரவுகளும் சட்டப்படி செல்லாது என அறிவிக்கப்பட்டது. அதிமுக-வின் 'நிரந்தரப் பொதுச்செயலாளர்' என்ற உயரிய பதவி மறைந்த ஜெயலலிதாவுக்கு மட்டுமே சொந்தம் என்றும் இனி அந்தப் பதவிக்கு யாரும் தேர்ந்தெடுக்கப்பட மாட்டார்கள் என்றும் விதி திருத்தப்பட்டது. போயஸ் கார்டனின் 30 ஆண்டுகால ஏகபோகப் பிடியிலிருந்து அதிமுக என்ற பேரியக்கம் அதிகாரப்பூர்வமாக விடுபட்ட நாளாக இது மாறியது." , year:2017, parties:["dmk", "aiadmk"], newsQuery:"சசிகலா நீக்கம் & ஜெ. 'நிரந்தரப் பொதுச்செயலாளர்' அறிவிப்பு 2017"},
  { id:43, season:"பருவம் 04", seasonNum:4, date:"செப்டம்பர் 18, 2017", title:"சபாநாயகர் தனபால் அதிரடி: தினகரன் ஆதரவு 18 எம்.எல்.ஏ-க்கள் தகுதி நீக்கம்", filter:"verdict", tags:[["தீர்ப்பு","red"],["18 எம்.எல்.ஏ","gray"],["தகுதி நீக்கம்","gray"]], desc:"ஆளுணரிடம் முதலமைச்சருக்கு எதிராகக் கடிதம் கொடுத்து கொறடா உத்தரவை மீறி புதுச்சேரி ரிசார்ட்டில் தங்கியிருந்த தினகரன் ஆதரவு எம்.எல்.ஏ-க்களுக்குச் சபாநாயகர் நோட்டீஸ் அனுப்பினார். எடப்பாடி பழனிசாமியின் ஆட்சியை எவ்வாறாவது காப்பாற்றியாக வேண்டும் என்ற இக்கட்டான சூழலில் சபாநாயகர் பி. தனபால் ஒரு அதிரடி அஸ்திரத்தைப் பிரயோகித்தார். கட்சித் தாவல் தடைச் சட்டத்தின் கீழ் (Anti-Defection Law) வி. செந்தில் பாலாஜி உள்ளிட்ட தினகரன் ஆதரவு 18 எம்.எல்.ஏ-க்களைப் பதவியிலிருந்து தகுதி நீக்கம் செய்து உத்தரவிட்டார். இந்தத் தகுதி நீக்கத்தின் மூலம் சட்டசபையின் மொத்த பலம் 216 ஆகக் குறைந்ததால் எடப்பாடி அரசு தங்களுக்குக் கிடைத்த எம்.எல்.ஏ-க்களை வைத்து நூலிழையில் ஆட்சியைக் காப்பாற்றிக் கொண்டது. தகுதி நீக்கம் செய்யப்பட்ட 18 எம்.எல்.ஏ-க்களின் தொகுதிகளும் காலியானதாக அறிவிக்கப்பட்டு தமிழக அரசியல் களம் உச்சகட்ட சட்டப் போராட்டங்களை நோக்கி நகர்ந்தது." , year:2017, parties:["aiadmk"], newsQuery:"சபாநாயகர் தனபால் அதிரடி: தினகரன் ஆதரவு 18 எம்.எல்.ஏ-க்கள் தகுதி நீக்கம் 2017"},
  { id:44, season:"பருவம் 05", seasonNum:5, date:"நவம்பர் 9, 2017", title:"இந்தியாவின் மெகா ஐடி ரெய்டு (Operation Clean Money) தொடக்கம்", filter:"raid", tags:[["ரெய்டு","red"],["சசிகலா குடும்பம்","gray"],["ஆபரேஷன் க்ளீன் மணி","gray"]], desc:"சசிகலா குடும்பத்தினர் மற்றும் அவர்களது தொழில் கூட்டாளிகளின் பொருளாதார பலத்தை ஒட்டுமொத்தமாக முடக்குவதற்கு மத்திய நேரடி வரிகள் வாரியம் (CBDT) இரகசியத் திட்டம் தீட்டியது. ஐஆர்எஸ் அதிகாரி கே.ஜி. அருண்ராஜ் தலைமையிலான புலனாய்வுப் பிரிவினர் 'ஆபரேஷன் க்ளீன் மணி' என்ற பெயரில் சசிகலாவின் உறவினர்கள் மற்றும் மிடாஸ் ஆலைகளுக்குச் சொந்தமான இடங்களில் அதிரடியாக நுழைந்தனர். ஜெயா டிவி, நமது எம்.ஜி.ஆர் நாளிதழ், மிடாஸ் மதுபான ஆலை மற்றும் கோடநாடு எஸ்டேட் ஆகியவற்றை முதன்மையாகக் குறிவைத்து இந்தச் சோதனை திட்டமிடப்பட்டது. தமிழ்நாட்டின் வரலாற்றிலேயே இல்லாத வகையில் ஒரே நாளில் நூற்றுக்கணக்கான கார்களில் ஐடி அதிகாரிகள் மாநிலத்தின் பல மாவட்டங்களுக்கும் ஒரே நேரத்தில் பிரிந்து சென்றனர். சசிகலா சிறைக்குச் சென்ற பிறகு அவரது குடும்பத்தினர் நடத்தி வந்த நிழல் பொருளாதாரப் பேரரசை வேரறுக்க மத்திய அரசு எடுத்த மிக பயங்கரமான அதிரடி ஆட்டம் இதுவாகும்." , year:2017, parties:["aiadmk", "it_dept"], newsQuery:"இந்தியாவின் மெகா ஐடி ரெய்டு (Operation Clean Money) தொடக்கம் 2017"},
  { id:45, season:"பருவம் 05", seasonNum:5, date:"நவம்பர் 13, 2017", title:"5 நாள் மெகா ரெய்டு முடிவு: 1,430 கோடி வரி ஏய்ப்பு கண்டுபிடிப்பு", filter:"raid", tags:[["ரெய்டு","red"],["₹1,430 கோடி","gray"],["வருமான வரித்துறை","gray"]], desc:"சசிகலாவின் அண்ணன் மகன் டிடிவி தினகரன், திவாகரன், டாக்டர் வெங்கடேஷ் மற்றும் இளவரசியின் வாரிசுகளான விவேக் ஜெயராமன், கிருஷ்ணப்பிரியா ஆகியோரது இல்லங்களில் 5 நாட்கள் தொடர் சோதனை நடந்தது. சுமார் 1,800-க்கும் மேற்பட்ட ஐடி அதிகாரிகள் மற்றும் மத்தியப் பாதுகாப்புப் படையினர் இணைந்து 187 இடங்களில் அணு அணுவாகச் சோதனைகளை மேற்கொண்டனர். சோதனையின் இறுதி நாளில் சசிகலா குடும்பத்தினர் மற்றும் அவர்களது கூட்டாளிகள் மூலம் சுமார் ₹1,430 கோடி ரூபாய் வரி ஏய்ப்பு செய்யப்பட்டிருப்பது அதிகாரப்பூர்வமாகக் கண்டுபிடிக்கப்பட்டது. கணக்கில் வராத நூற்றுக்கணக்கான சொத்து ஆவணங்கள், போலி நிறுவனங்களின் (Shell Companies) பங்குகள் மற்றும் கிலோ கணக்கில் தங்கம், வைர நகைகள் பறிமுதல் செய்யப்பட்டன. இந்திய வருமான வரித்துறை வரலாற்றிலேயே ஒரே ஒரு குடும்பத்தின் மீது நடத்தப்பட்ட மிகப்பெரிய மெகா ரெய்டாக இந்த 'ஆபரேஷன் க்ளீன் மணி' உலக அளவில் பதிவானது." , year:2017, parties:["aiadmk", "it_dept"], newsQuery:"5 நாள் மெகா ரெய்டு முடிவு: 1,430 கோடி வரி ஏய்ப்பு கண்டுபிடிப்பு 2017"},
  { id:46, season:"பருவம் 05", seasonNum:5, date:"நவம்பர் 17, 2017", title:"போயஸ் கார்டன் 'வேதா நிலையத்துக்குள்' நள்ளிரவில் ஐடி அதிகாரிகள் என்ட்ரி", filter:"raid", tags:[["ரெய்டு","red"],["வேதா நிலையம்","gray"],["போயஸ் கார்டன்","gray"]], desc:"'ஆபரேஷன் க்ளீன் மணி' சோதனையின் நீட்சியாக தமிழக அரசியலின் புனிதத் தலமாகக் கருதப்பட்ட ஜெயலலிதா வாழ்ந்த போயஸ் கார்டன் 'வேதா நிலையம்' இல்லத்தைக் குறிவைத்தனர். வருமான வரித்துறை அதிகாரிகள் எழும்பூர் நீதிமன்றத்தில் இருந்து சிறப்புச் சோதனை வாரண்ட் பெற்று நள்ளிரவு 9 மணியளவில் வேதா நிலையத்திற்குள் அதிரடியாக நுழைந்தனர். அங்குள்ள சசிகலாவின் அறைகள் மற்றும் ஜெயலலிதாவின் தனிப்பட்ட செயலாளராக இருந்த பூங்குன்றனின் அறைகளை மட்டுமே குறிவைத்து இந்தச் சோதனை நடத்தப்பட்டது. நள்ளிரவில் ஐடி அதிகாரிகள் நுழைந்த செய்தி கேட்டுப் போயஸ் கார்டன் வாசலில் திரண்ட டிடிவி தினகரன் ஆதரவாளர்கள் மத்திய அரசுக்கு எதிராகக் கொந்தளித்துப் போராட்டத்தில் ஈடுபட்டனர். இந்தச் சோதனையில் சசிகலா பயன்படுத்திய லேப்டாப்கள், டெஸ்க்டாப் கணினிகள் மற்றும் சில ரகசிய டைரிகள் கைப்பற்றப்பட்டதாக ஐடி வட்டாரங்கள் தெரிவித்தன." , year:2017, parties:["aiadmk", "it_dept"], newsQuery:"போயஸ் கார்டன் 'வேதா நிலையத்துக்குள்' நள்ளிரவில் ஐடி அதிகாரிகள் என்ட்ரி 2017"},
  { id:47, season:"பருவம் 05", seasonNum:5, date:"நவம்பர் 23, 2017", title:"இரட்டை இலை சின்னம் ஈபிஎஸ்-ஓபிஎஸ் அணிக்கே ஒதுக்கீடு", filter:"verdict", tags:[["தீர்ப்பு","red"],["இரட்டை இலை","gray"],["தேர்தல் ஆணையம்","gray"]], desc:"சின்னம் முடக்கப்பட்டு பல மாதங்களாகத் தேர்தல் ஆணையத்தில் நடந்து வந்த 'இரட்டை இலை' சின்னம் யாருக்கு என்ற இறுதி விசாரணை முடிவுக்கு வந்தது. 90% க்கும் மேற்பட்ட பொதுக்குழு உறுப்பினர்கள் மற்றும் எம்.எல்.ஏ-க்களின் ஆதரவு தங்களுக்கு இருப்பதாக ஈபிஎஸ் - ஓபிஎஸ் தரப்பு தாக்கல் செய்த ஆவணங்களை ஆணையம் பரிசீலித்தது. இந்தியத் தேர்தல் ஆணையம் (ECI) தனது இறுதித் தீர்ப்பில் அதிமுக என்ற கட்சியின் பெயரும் அதன் பாரம்பரியமிக்க 'இரட்டை இலை' சின்னமும் எடப்பாடி - ஓபிஎஸ் தலைமையிலான ஒருங்கிணைந்த அணிக்கே சொந்தம் என அறிவித்தது. சசிகலா மற்றும் டிடிவி தினகரன் தரப்பு தாக்கல் செய்த பல பிரமாணப் பத்திரங்கள் போலியானவை எனக் கூறி அவர்களது மனுக்களைத் தேர்தல் ஆணையம் நிராகரித்தது. இந்தத் தீர்ப்பின் மூலம் எடப்பாடி பழனிசாமி தலைமையிலான அரசு சட்டப்பூர்வமாகவும் அரசியல் ரீதியாகவும் தங்களது அசைக்க முடியாத பலத்தை மாநில அளவில் நிலைநிறுத்தியது." , year:2017, parties:["dmk", "aiadmk"], newsQuery:"இரட்டை இலை சின்னம் ஈபிஎஸ்-ஓபிஎஸ் அணிக்கே ஒதுக்கீடு 2017"},
  { id:48, season:"பருவம் 05", seasonNum:5, date:"டிசம்பர் 21, 2017", title:"ஆர்.கே. நகர் இடைத்தேர்தல் மறுவாக்குப்பதிவு", filter:"election", tags:[["தேர்தல்","red"],["ஆர்.கே. நகர்","gray"],["மறுவாக்குப்பதிவு","gray"]], desc:"பணப்பட்டுவாடா புகாரால் ஏப்ரல் மாதம் ரத்து செய்யப்பட்ட சென்னை ஆர்.கே. நகர் சட்டமன்றத் தொகுதிக்கு பலத்த பாதுகாப்பு மற்றும் நவீன கண்காணிப்புக்கு இடையே மறுவாக்குப்பதிவு நடைபெற்றது. தேர்தல் ஆணையம் ஒவ்வொரு தெருவிலும் சிசிடிவி கேமராக்கள், பறக்கும் படைகள் மற்றும் மத்தியப் பாதுகாப்புப் படையினரை நிறுத்தித் தேர்தலைத் தீவிரமாகக் கண்காணித்தது. சின்னத்தை இழந்த டிடிவி தினகரன் சுயேச்சை வேட்பாளராக 'பிரஷர் குக்கர்' சின்னத்திலும் ஒருங்கிணைந்த அதிமுக சார்பில் இ. மதுசூதனன் இரட்டை இலை சின்னத்திலும் களம் கண்டனர். திமுக சார்பில் மருதுகணேஷ் போட்டியிட இடதுசாரிகள் மற்றும் மநீம போன்ற கட்சிகள் இந்தத் தேர்தலை உற்று நோக்கின. ஜெயலலிதாவின் மறைவுக்குப் பின் அவரது தொகுதியைத் தன்வசப்படுத்தப் போவது யார் என்பதைத் தீர்மானிக்கும் இந்தத் தேர்தலில் 77.6% வாக்குகள் பதிவாகின." , year:2017, parties:["dmk", "aiadmk"], newsQuery:"ஆர்.கே. நகர் இடைத்தேர்தல் மறுவாக்குப்பதிவு 2017"},
  { id:49, season:"பருவம் 05", seasonNum:5, date:"டிசம்பர் 24, 2017", title:"ஆர்.கே. நகரில் 'குக்கர்' வெற்றி: டிடிவி தினகரன் வரலாற்றுச் சாதனை", filter:"verdict", tags:[["வெற்றி","red"],["டிடிவி தினகரன்","gray"],["குக்கர் சின்னம்","gray"]], desc:"கிறிஸ்துமஸ் பண்டிகைக்கு முந்தைய நாள் வெளியான ஆர்.கே. நகர் இடைத்தேர்தல் முடிவுகள் தமிழக திராவிட அரசியல் வரலாற்றையே அடியோடு உலுக்கின. சுயேச்சை வேட்பாளராகப் போட்டியிட்ட டிடிவி தினகரன் 89,013 வாக்குகள் பெற்று ஆளுங்கட்சியின் 'இரட்டை இலை' வேட்பாளர் மதுசூதனனை விட 40,000 வாக்குகள் வித்தியாசத்தில் மாபெரும் வெற்றி பெற்றார். தமிழ்நாட்டு தேர்தல் வரலாற்றிலேயே ஆளுங்கட்சி, எதிர்க்கட்சி இரண்டையும் மீறி ஒரு சுயேச்சை வேட்பாளர் இடைத்தேர்தலில் வென்ற முதல் வரலாற்றுச் சாதனை இதுவாகும். பிரதான எதிர்க்கட்சியான திமுக வாக்கு வங்கியை இழந்தது மட்டுமன்றி வைப்புத்தொகையையும் (Deposit) இழந்து படுதோல்வியைச் சந்தித்தது. இரட்டை இலைச் சின்னம் இல்லாவிட்டாலும் போயஸ் கார்டன் குடும்பத்தின் செல்வாக்கு இன்னும் மக்களிடம் குறையவில்லை என்பதை தினகரன் இந்த வெற்றியின் மூலம் டெல்லிக்கு நிரூபித்தார்." , year:2017, parties:["dmk"], newsQuery:"ஆர்.கே. நகரில் 'குக்கர்' வெற்றி: டிடிவி தினகரன் வரலாற்றுச் சாதனை 2017"},
  { id:50, season:"பருவம் 05", seasonNum:5, date:"பிப்ரவரி 21, 2018", title:"மதுரையில் கமல்ஹாசனின் 'மக்கள் நீதி மய்யம்' தொடக்கம்", filter:"alliance", tags:[["கட்சி","red"],["கமல்ஹாசன்","gray"],["மக்கள் நீதி மய்யம்","gray"]], desc:"ஜெயலலிதா, கருணாநிதி ஆகிய இரு பெரும் ஆளுமைகள் இல்லாத தமிழக அரசியலில் மாற்றுச் சக்தியாக உருவெடுக்கப் போவதாக நடிகர் கமல்ஹாசன் அறிவித்தார். தென் தமிழகத்தின் மையமான மதுரையில் லட்சக்கணக்கான மக்கள் திரண்ட பிரம்மாண்ட பொதுக்கூட்டத்தில் 'மக்கள் நீதி மய்யம்' (MNM) என்ற தனது புதிய அரசியல் கட்சியைத் தொடங்கினார். டெல்லி முதலமைச்சர் அரவிந்த் கெஜ்ரிவால் மற்றும் கேரளா முதலமைச்சர் பினராயி விஜயன் ஆகியோர் வாழ்த்துகளுடன் கட்சியின் கொடியையும் கொள்கையையும் உலகிற்கு அறிமுகப்படுத்தினார். கழன்றுகொண்டிருக்கும் ஆறு கைகள் ஒன்றிணைந்து நடுவில் ஒரு நட்சத்திரம் இருப்பது போன்ற கட்சியின் கொடி தென்னக மாநிலங்களின் ஒற்றுமையைப் பிரதிபலிப்பதாக விளக்கினார். 'நான் இடதுசாரியும் அல்ல வலதுசாரியும் அல்ல; நான் மய்யம்' என்ற புதிய அரசியல் தத்துவத்தை முன்வைத்து கமல்ஹாசன் தனது அரசியல் பயணத்தைத் தொடங்கினார்." , year:2018, parties:["dmk", "aiadmk"], newsQuery:"மதுரையில் கமல்ஹாசனின் 'மக்கள் நீதி மய்யம்' தொடக்கம் 2018"},
  { id:51, season:"பருவம் 05", seasonNum:5, date:"மார்ச் 15, 2018", title:"மதுரையில் டிடிவி தினகரனின் 'அம்மா மக்கள் முன்னேற்றக் கழகம்' தொடக்கம்", filter:"alliance", tags:[["கட்சி","red"],["டிடிவி தினகரன்","gray"],["அமமுக","gray"]], desc:"ஆர்.கே. நகர் இடைத்தேர்தல் வெற்றிக்குப் பிறகு அதிமுக-வை மீட்டெடுக்கத் தனக்கென ஒரு நிரந்தர அரசியல் இயக்கத்தின் தேவை இருப்பதை டிடிவி தினகரன் உணர்ந்தார். மதுரை மேலூர் அருகே நடந்த பிரம்மாண்ட பொதுக்கூட்டத்தில் 'அம்மா மக்கள் முன்னேற்றக் கழகம்' (AMMK) என்ற புதிய அமைப்பை அதிகாரப்பூர்வமாகத் தொடங்கினார். கருப்பு, வெள்ளை, சிவப்பு நிறக் கொடியின் நடுவே மறைந்த முதலமைச்சர் ஜெயலலிதாவின் முகம் பொறிக்கப்பட்ட கட்சியின் கொடியை அவர் அறிமுகப்படுத்தினார். 'துரோகிகளின் கைகளில் இருக்கும் அதிமுக-வை மீட்டெடுக்கும் வரை இந்த இயக்கம் ஒரு தற்காலிகப் பாலமாகச் செயல்படும்' எனத் தினகரன் பிரகடனம் செய்தார். அதிமுக-வின் அடிமட்டத் தொண்டர்கள் மற்றும் வாக்கு வங்கியைத் தன் பக்கம் முழுமையாக இழுக்க தினகரன் எடுத்த இந்த நகர்வு ஈபிஎஸ் - ஓபிஎஸ் தலைமைக்குக் கடும் சவாலாக மாறியது." , year:2018, parties:["dmk", "aiadmk"], newsQuery:"மதுரையில் டிடிவி தினகரனின் 'அம்மா மக்கள் முன்னேற்றக் கழகம்' தொடக்கம் 2018"},
  { id:52, season:"பருவம் 05", seasonNum:5, date:"மே 22, 2018", title:"தூத்துக்குடி ஸ்டெர்லைட் துப்பாக்கிச் சூடு: 13 பேர் பலி", filter:"crisis", tags:[["நெருக்கடி","red"],["ஸ்டெர்லைட்","gray"],["துப்பாக்கிச் சூடு","gray"]], desc:"தூத்துக்குடியில் உள்ள ஸ்டெர்லைட் செப்பு ஆலைக்கு எதிராக சுற்றுவட்டாரக் கிராம மக்கள் தொடர்ந்து 100 நாட்களாக அமைதியான முறையில் போராட்டம் நடத்தி வந்தனர். 100-வது நாளான மே 22 அன்று மாவட்ட ஆட்சியர் அலுவலகத்தை முற்றுகையிட ஆயிரக்கணக்கான பொதுமக்கள் பேரணியாகப் புறப்பட்ட போது வன்முறை வெடித்தது. கலவரத்தைக் கட்டுப்படுத்த போலீசார் நடத்திய கண்மூடித்தனமான துப்பாக்கிச் சூட்டில் பள்ளி மாணவி ஸ்னோலின் உட்பட 13 அப்பாவி பொதுமக்கள் ரத்த வெள்ளத்தில் பலியாயினர். போலீசார் வாகனங்களின் மீது ஏறி நின்று குறி பார்த்துச் சுட்ட காட்சிகள் ஊடகங்களில் வெளியாகி சர்வதேச அளவில் மனித உரிமை மீறல் சர்ச்சையை ஏற்படுத்தியது. சுதந்திர இந்தியாவில் நடந்த மிக மோசமான போலீஸ் துப்பாக்கிச் சூடுகளில் ஒன்றாக இந்தச் சம்பவம் பதிவாகி ஒட்டுமொத்த தமிழகத்தையும் உலுக்கியது." , year:2018, parties:["unknown"], newsQuery:"தூத்துக்குடி ஸ்டெர்லைட் துப்பாக்கிச் சூடு: 13 பேர் பலி 2018"},
  { id:53, season:"பருவம் 05", seasonNum:5, date:"மே 28, 2018", title:"ஸ்டெர்லைட் ஆலைக்குத் தமிழக அரசு நிரந்தர சீல்", filter:"verdict", tags:[["முடிவு","red"],["ஸ்டெர்லைட் சீல்","gray"],["தமிழக அரசு","gray"]], desc:"துப்பாக்கிச் சூடு சம்பவத்தால் தமிழகம் முழுவதும் வெடித்த மாபெரும் மக்கள் கொந்தளிப்பு மற்றும் எதிர்க்கட்சிகளின் தொடர் போராட்டங்களால் எடப்பாடி அரசு கடும் நெருக்கடிக்குள்ளானது. மக்களின் கோபத்தைத் தணிக்கவும் சட்டம் ஒழுங்கைப் பாதுகாக்கவும் தமிழக அரசு ஒரு மிக முக்கிய அதிரடி முடிவை எடுத்தது. தமிழக அரசின் சுற்றுச்சூழல் மற்றும் வனத்துறை பிறப்பித்த அரசாணையின்படி (G.O. No. 42) தூத்துக்குடி ஸ்டெர்லைட் ஆலையை நிரந்தரமாக மூட உத்தரவிடப்பட்டது. தூத்துக்குடி மாவட்ட அதிகாரிகள் முன்னிலையில் ஸ்டெர்லைட் ஆலையின் முதன்மை வாயில்கள் அனைத்தும் பூட்டப்பட்டு அதிகாரப்பூர்வமாக சீல் வைக்கப்பட்டது. 13 பேரின் உயிர தியாகத்திற்குப் பின் கிடைத்த இந்த வெற்றி கார்ப்பரேட் நிறுவனங்களுக்கு எதிராக அடித்தட்டு மக்கள் நடத்திய வரலாற்றுச் சிறப்புமிக்க போராட்டத்தின் சாட்சியாக மாறியது." , year:2018, parties:["aiadmk"], newsQuery:"ஸ்டெர்லைட் ஆலைக்குத் தமிழக அரசு நிரந்தர சீல் 2018"},
  { id:54, season:"பருவம் 05", seasonNum:5, date:"ஆகஸ்ட் 7, 2018", title:"திமுக தலைவர் மு. கருணாநிதி சிகிச்சை பலனின்றி மறைவு", filter:"crisis", tags:[["மறைவு","red"],["கலைஞர் கருணாநிதி","gray"],["திமுக","gray"]], desc:"தமிழக அரசியலின் மிக மூத்த தலைவரும் 5 முறை முதலமைச்சராக இருந்தவருமான திமுக தலைவர் கலைஞர் மு. கருணாநிதி வயது முதிர்வு மற்றும் உடல்நலக்குறைவால் அவதிப்பட்டு வந்தார். சென்னை ஆழ்வார்பேட்டையில் உள்ள காவேரி மருத்துவமனையில் அனுமதிக்கப்பட்டிருந்த அவர் சிகிச்சை பலனின்றி ஆகஸ்ட் 7 மாலை 6:10 மணிக்குக் காலமானார். அரை நூற்றாண்டு காலம் (50 ஆண்டுகள்) ஒரு கட்சியின் தலைவராக இருந்து இந்திய அரசியலின் திசையைத் தீர்மானித்த ஒரு மாபெரும் சகாப்தம் இத்துடன் முடிவுக்கு வந்தது. கலைஞரின் மறைவுச் செய்தி வெளியானதும் லட்சக்கணக்கான திமுக தொண்டர்கள் காவேரி மருத்துவமனை மற்றும் கோபாலபுரம் இல்லம் முன்பு கண்ணீருடன் குவிந்தனர். நவீன தமிழ்நாட்டின் உள்கட்டமைப்பு சமூக நீதி மற்றும் கலைத்துறையின் வளர்ச்சிக்கு வித்திட்ட ஒரு மாபெரும் பேனா தனது எழுத்தை நிரந்தரமாக நிறுத்திக் கொண்டது." , year:2018, parties:["dmk"], newsQuery:"திமுக தலைவர் மு. கருணாநிதி சிகிச்சை பலனின்றி மறைவு 2018"},
  { id:55, season:"பருவம் 05", seasonNum:5, date:"ஆகஸ்ட் 8, 2018", title:"சட்டப்போராட்டத்திற்குப் பின் மெரினாவில் மு. கருணாநிதி அடக்கம்", filter:"verdict", tags:[["தீர்ப்பு","red"],["மெரினா","gray"],["உயர்நீதிமன்றம்","gray"]], desc:"கருணாநிதியின் உடலை மெரினா கடற்கரையில் அண்ணா நினைவிடம் அருகே அடக்கம் செய்ய திமுக தரப்பில் இடம் கேட்கப்பட்டது; ஆனால் சட்ட விதிகளக் காட்டி எடப்பாடி அரசு மறுத்தது. ஆகஸ்ட் 7 நள்ளிரவிலேயே சென்னை உயர்நீதிமன்றத் தலைமை நீதிபதி இல்லத்தில் திமுக அவசர வழக்குத் தொடர்ந்து அனல் பறக்கும் சட்டப் போராட்டத்தை நடத்தியது. ஆகஸ்ட் 8 காலை தீர்ப்பளித்த உயர்நீதிமன்றம் மெரினாவில் கருணாநிதியை அடக்கம் செய்யத் தமிழக அரசு உடனடியாக இடம் ஒதுக்க வேண்டும் என அதிரடி உத்தரவிட்டது. நீதிமன்றத் தீர்ப்பைக் கேட்டு ராஜாஜி அரங்கில் இருந்த மு.க.ஸ்டாலின் மற்றும் திமுக தலைவர்கள் அனைவரும் மேடையிலேயே கண்ணீர் விட்டு அழுதனர். அன்று மாலையே லட்சக்கணக்கான மக்களின் கண்ணீர் அஞ்சலிக்கு இடையே தனது அரசியல் குருவான அண்ணாவின் இதயத்திற்கு மிக அருகிலேயே கருணாநிதியின் உடல் முழு அரசு மரியாதையுடன் அடக்கம் செய்யப்பட்டது." , year:2018, parties:["dmk", "aiadmk"], newsQuery:"சட்டப்போராட்டத்திற்குப் பின் மெரினாவில் மு. கருணாநிதி அடக்கம் 2018"},
  { id:56, season:"பருவம் 05", seasonNum:5, date:"ஆகஸ்ட் 28, 2018", title:"மு.க. ஸ்டாலின் திமுக தலைவராக ஒருமனதாகத் தேர்வு", filter:"alliance", tags:[["கட்சி","red"],["மு.க.ஸ்டாலின்","gray"],["திமுக தலைவர்","gray"]], desc:"கலைஞர் கருணாநிதியின் மறைவுக்குப் பின் திமுக-வின் அடுத்த தலைவரைத் தேர்ந்தெடுப்பதற்கான அதிகாரப்பூர்வ பொதுக்குழுக் கூட்டம் அண்ணா அறிவாலயத்தில் கூடியது. கடந்த பல ஆண்டுகளாகக் கட்சியின் செயல் தலைவராக இருந்து கட்சியை வழிநடத்தி வந்த மு.க. ஸ்டாலின் தலைவராகப் போட்டியிட மனுத்தாக்கல் செய்தார். பொதுக்குழுவில் உள்ள அனைத்து உறுப்பினர்களின் ஒருமனதான ஆதரவோடு மு.க. ஸ்டாலின் திமுக-வின் 2-வது தலைவராக அதிகாரப்பூர்வமாகத் தேர்ந்தெடுக்கப்பட்டார். 'என் தந்தை கலைஞரின் இடத்தை யாராலும் நிரப்ப முடியாது; ஆனால் அவரது வழியில் நின்று நான் இந்தக் கழகத்தைக் காப்பேன்' என ஸ்டாலின் உணர்ச்சிப்பூர்வமாகப் பேசினார். கருணாநிதி என்ற மாபெரும் நிழலில் இருந்து வெளிவந்து மு.க.ஸ்டாலின் தனது சொந்த ஆளுமையின் கீழ் திமுக-வை வழிநடத்தத் தொடங்கிய புதிய சகாப்தத்தின் புள்ளி இதுவாகும்." , year:2018, parties:["dmk"], newsQuery:"மு.க. ஸ்டாலின் திமுக தலைவராக ஒருமனதாகத் தேர்வு 2018"},
  { id:57, season:"பருவம் 05", seasonNum:5, date:"செப்டம்பர் 5, 2018", title:"குட்கா ஊழல்: அமைச்சர்கள், மாஜி டிஜிபி வீடுகளில் சிபிஐ அதிரடி", filter:"raid", tags:[["ரெய்டு","red"],["குட்கா ஊழல்","gray"],["சிபிஐ","gray"]], desc:"தடை செய்யப்பட்ட குட்கா மற்றும் பான் மசாலா பொருட்களைத் தமிழ்நாட்டில் சட்டவிரோதமாக விற்பனை செய்யப் பல கோடி ரூபாய் லஞ்சம் பெற்றதாகப் புகார் எழுந்தது. சென்னை உயர்நீதிமன்ற உத்தரவின்படி இந்த வழக்கை கையில் எடுத்த டெல்லி சிபிஐ (CBI) ஊழல் தடுப்புப் பிரிவினர் தமிழகம் முழுவதும் அதிரடி வேட்டையைத் தொடங்கினர். சுகாதாரத்துறை அமைச்சர் சி. விஜயபாஸ்கர், முன்னாள் டிஜிபி டி.கே. ராஜேந்திரன், முன்னாள் சென்னை கமிஷனர் எஸ். ஜார்ஜ் ஆகியோரது வீடுகள் உட்பட 40 இடங்களில் சிபிஐ நுழைந்தது. தமிழக வரலாற்றிலேயே பணியில் இருக்கும் டிஜிபி மற்றும் கமிஷனர் வீடுகளில் சிபிஐ ரெய்டு நடத்தியது இதுவே முதல்முறையாகும். இந்தச் சோதனையில் பல ரகசிய டைரிகள் மற்றும் லஞ்சம் கைமாறியதற்கான முக்கிய டிஜிட்டல் ஆதாரங்களை சிபிஐ அதிகாரிகள் கைப்பற்றி வழக்கை இன்னும் தீவிரப்படுத்தினர்." , year:2018, parties:["cbi"], newsQuery:"குட்கா ஊழல்: அமைச்சர்கள், மாஜி டிஜிபி வீடுகளில் சிபிஐ அதிரடி 2018"},
  { id:58, season:"பருவம் 06", seasonNum:6, date:"பிப்ரவரி 19, 2019", title:"மக்களவைத் தேர்தலுக்காக அதிமுக - பாஜக அதிகாரப்பூர்வ கூட்டணி", filter:"alliance", tags:[["கூட்டணி","red"],["அதிமுக-பாஜக","gray"],["எடப்பாடி பழனிசாமி","gray"]], desc:"2019 நாடாளுமன்றத் தேர்தல் நெருங்கிய வேளையில் திமுக கூட்டணியை எதிர்கொள்ள எடப்பாடி பழனிசாமி தலைமையிலான அதிமுக புதிய வியூகம் வகுத்தது. சென்னை நட்சத்திர விடுதியில் மத்திய அமைச்சர் பியூஷ் கோயல் மற்றும் முதலமைச்சர் ஈபிஎஸ், ஓபிஎஸ் முன்னிலையில் அதிமுக - பாஜக கூட்டணி ஒப்பந்தம் கையெழுத்தானது. இந்த ஒப்பந்தத்தின்படி தமிழகத்தில் பாஜக 5 இடங்களிலும், பாமக 7 இடங்களிலும், தேமுதிக 4 இடங்களிலும் போட்டியிடும் எனத் தொகுதிப் பங்கீடு அறிவிக்கப்பட்டது. ஜெயலலிதா உயிருடன் இருந்தவரை பாஜக-வுடன் கூட்டணி அமைக்காமல் தனித்து நின்ற நிலையில் இந்த மாற்றம் கட்சியின் கொள்கை சரிவு என விமர்சிக்கப்பட்டது. 'நாங்கள் அமைத்துள்ளது மெகா கூட்டணி; இந்தத் தேர்தலில் 40 இடங்களையும் வெல்வோம்' என ஈபிஎஸ் - ஓபிஎஸ் இரட்டைத் தலைமை டெல்லிக்கு உறுதி அளித்தது." , year:2019, parties:["bjp", "dmk", "aiadmk"], newsQuery:"மக்களவைத் தேர்தலுக்காக அதிமுக - பாஜக அதிகாரப்பூர்வ கூட்டணி 2019"},
  { id:59, season:"பருவம் 06", seasonNum:6, date:"பிப்ரவரி - மார்ச் 2019", title:"தமிழகத்தை உலுக்கிய பொள்ளாச்சி பாலியல் வன்கொடுமை வழக்கு", filter:"crisis", tags:[["நெருக்கடி","red"],["பொள்ளாச்சி","gray"],["சிபிஐ விசாரணை","gray"]], desc:"கோவை மாவட்டம் பொள்ளாச்சியில் கல்லூரிப் பெண்களைத் திட்டமிட்டு ஆசைவார்த்தை கூறி வரவழைத்து பாலியல் வன்கொடுமை செய்து வீடியோ எடுத்து மிரட்டிய கும்பல் அம்பலமானது. பாதிக்கப்பட்ட பெண் ஒருவர் தைரியமாகப் பொள்ளாச்சி காவல் நிலையத்தில் அளித்த புகாரின் அடிப்படையில் திருநாவுக்கரசு, சபாராஜன் உள்ளிட்ட முக்கியக் குற்றவாளிகள் கைது செய்யப்பட்டனர். இந்த வழக்கில் ஆளுங்கட்சியைச் சேர்ந்த சில முக்கியப் புள்ளிகளின் வாரிசுகளுக்குத் தொடர்பு இருப்பதாகச் செய்திகள் வெளியாகித் தமிழகம் முழுவதும் மாபெரும் கொந்தளிப்பை ஏற்படுத்தியது. பெண்களின் பாதுகாப்பைக் கேள்விக்குறியாக்கிய இந்த வழக்கின் தீவிரத்தைக் கருத்தில் கொண்டு வழக்கை சிபிசிஐடி-யில் இருந்து சிபிஐ (CBI) விசாரணைக்கு மாற்றித் தமிழக அரசு உத்தரவிட்டது. தேர்தல் நேரத்தில் வெடித்த இந்தச் சோகமான சம்பவம் ஆளுங்கட்சிக்கு எதிராகப் பொதுமக்களிடையேயும் குறிப்பாகப் பெண் வாக்காளர்களிடையேயும் கடும் அதிருப்தியை உருவாக்கியது." , year:2019, parties:["cbi"], newsQuery:"தமிழகத்தை உலுக்கிய பொள்ளாச்சி பாலியல் வன்கொடுமை வழக்கு 2019"},
  { id:60, season:"பருவம் 06", seasonNum:6, date:"ஏப்ரல் 30, 2019", title:"லாட்டரி அதிபர் மார்ட்டின் குரூப் 70 இடங்களில் முதல் ஐடி ரெய்டு", filter:"raid", tags:[["ரெய்டு","red"],["மார்ட்டின் குரூப்","gray"],["வரி ஏய்ப்பு","gray"]], desc:"இந்தியாவின் 'லாட்டரி கிங்' என்று அழைக்கப்படும் கோயம்புத்தூரைச் சேர்ந்த தொழிலதிபர் சாண்டியாகோ மார்ட்டின் வரி ஏய்ப்பு செய்வதாகப் புகார்கள் குவிந்தன. வருமான வரித்துறை புலனாய்வுப் பிரிவினர் மார்ட்டினுக்குச் சொந்தமான சென்னை, கோவை மற்றும் வடகிழக்கு மாநிலங்களில் உள்ள 70 இடங்களில் ஒரே நேரத்தில் சோதனையைத் தொடங்கினர். மார்ட்டின் குழும நிறுவனங்கள் லாட்டரி விற்பனை மூலம் வரும் கோடிக்கணக்கான ரூபாயைப் பதுக்கி வைத்துள்ளதாக எழுந்த ரகசியத் தகவலின் பேரில் இந்த ஆட்டம் திட்டமிடப்பட்டது. தேர்தல் வாக்குப்பதிவு முடிந்து சில நாட்களிலேயே இந்த ரெய்டு நடத்தப்பட்டது அரசியல் கட்சிகளுக்குப் போன தேர்தல் நிதியின் பின்னணியை நோக்கிய நகர்வாகப் பார்க்கப்பட்டது. உள்கட்டமைப்பு மற்றும் ரியல் எஸ்டேட் துறைகளில் மார்ட்டின் முதலீடு செய்திருந்த பல முக்கிய ரகசிய ஆவணங்களை அதிகாரிகள் இந்தச் சோதனையின் போது கைப்பற்றினர்." , year:2019, parties:["it_dept"], newsQuery:"லாட்டரி அதிபர் மார்ட்டின் குரூப் 70 இடங்களில் முதல் ஐடி ரெய்டு 2019"},
  { id:61, season:"பருவம் 06", seasonNum:6, date:"மே 4, 2019", title:"மார்ட்டின் ரெய்டு நிறைவு: 595 கோடி கணக்கில் வராத பணம் கண்டுபிடிப்பு", filter:"raid", tags:[["ரெய்டு","red"],["₹595 கோடி","gray"],["அமலாக்கத்துறை","gray"]], desc:"சாண்டியாகோ மார்ட்டின் மற்றும் அவரது குடும்பத்தினர் இடங்களில் 5 நாட்களாகத் தொய்வின்றி நடத்தப்பட்ட வருமான வரித்துறை சோதனை அதிகாரப்பூர்வமாக நிறைவடைந்தது. இந்தச் சோதனையின் முடிவில் மார்ட்டின் குழுமம் சுமார் ₹595 கோடி ரூபாய் மதிப்பிலான கணக்கில் வராத பணப் பரிவர்த்தனைகளைச் செய்திருப்பதை ஐடி அதிகாரிகள் கண்டுபிடித்தனர். மேலும் சோதனையின் போது பல்வேறு பதுக்கல் அறைகளில் இருந்து கோடிக்கணக்கான ரொக்கப் பணம் மற்றும் முக்கிய டிஜிட்டல் ஆவணங்கள் பறிமுதல் செய்யப்பட்டன. இந்த மெகா ரெய்டைத் தொடர்ந்து அமலாக்கத்துறை (ED) பணமோசடி தடுப்புச் சட்டத்தின் கீழ் (PMLA) மார்ட்டின் மீது தனியாக வழக்குப் பதிவு செய்து அவரது சொத்துக்களை முடக்கத் தொடங்கியது. தமிழக அரசியலின் அனைத்து முக்கியக் கட்சிகளுக்கும் நிதி ஆதாரமாக விளங்கிய ஒரு தொழிலதிபரின் மீதான இந்த நடவடிக்கை தேர்தல் களத்தின் பின்விளைவாகவே பார்க்கப்பட்டது." , year:2019, parties:["it_dept"], newsQuery:"மார்ட்டின் ரெய்டு நிறைவு: 595 கோடி கணக்கில் வராத பணம் கண்டுபிடிப்பு 2019"},
  { id:62, season:"பருவம் 06", seasonNum:6, date:"மே 23, 2019", title:"நாடாளுமன்றத் தேர்தல் முடிவுகள்: திமுக கூட்டணி 39-ல் 38 இடங்களில் மாபெரும் வெற்றி", filter:"verdict", tags:[["வெற்றி","red"],["திமுக கூட்டணி","gray"],["38 இடங்கள்","gray"]], desc:"2019 நாடாளுமன்றத் தேர்தல் வாக்கு எண்ணிக்கை முடிவுகள் வெளியாகி தமிழகத்தில் மு.க. ஸ்டாலினின் அரசியல் ஆளுமையை தேசிய அளவில் நிரூபித்தன. மு.க. ஸ்டாலின் தலைமையிலான திமுக - காங்கிரஸ் - இடதுசாரிகள் அடங்கிய 'மதச்சார்பற்ற முற்போக்கு கூட்டணி' 39 இடங்களில் 38-ல் பிரம்மாண்ட வெற்றி பெற்று சரித்திரம் படைத்தது. ஓபிஎஸ் மகன் ரவீந்திரநாத் குமார் போட்டியிட்ட தேனி தொகுதியில் மட்டுமே அதிமுக தங்களது கௌரவத்தை நூலிழையில் காப்பாற்றிக் கொண்டது; பாஜக உள்ளிட்ட கூட்டணிக் கட்சிகள் அனைத்தும் பூஜ்ஜியமாகின. கலைஞர் கருணாநிதி இல்லாத முதல் பொதுத்தேர்தலைத் தனது ஒற்றைத் தலைமையின் கீழ் வழிநடத்தி மு.க.ஸ்டாலின் பெற்ற இந்த ஸ்வீப் வெற்றி அவரது தலைமைத்துவத்திற்கு அங்கீகாரமாக அமைந்தது. மத்தியில் மோடி அலை வீசினாலும் தமிழகத்தில் அதற்கு முற்றிலும் எதிரான ஒரு தீர்ப்பை மக்கள் ஆணித்தரமாக வழங்கிய தேர்தல் நாளாக இந்த மே 23 அமைந்தது." , year:2019, parties:["bjp", "dmk", "aiadmk", "congress"], newsQuery:"நாடாளுமன்றத் தேர்தல் முடிவுகள்: திமுக கூட்டணி 39-ல் 38 இடங்களில் மாபெரும் வெற்றி 2019"},
  { id:63, season:"பருவம் 06", seasonNum:6, date:"மே 23, 2019 (தொடர்ச்சி)", title:"சட்டமன்ற இடைத்தேர்தலில் 9 இடங்களை வென்று ஆட்சியைத் தக்கவைத்த ஈபிஎஸ்", filter:"verdict", tags:[["வெற்றி","red"],["எடப்பாடி பழனிசாமி","gray"],["ஆட்சித் தற்காப்பு","gray"]], desc:"நாடாளுமன்றத் தேர்தலுடன் சேர்த்து தகுதி நீக்கம் செய்யப்பட்ட எம்.எல்.ஏ-க்களின் காலியான 22 சட்டமன்றத் தொகுதிகளுக்கான இடைத்தேர்தல் முடிவுகளும் அன்றே வெளியாகின. எடப்பாடி பழனிசாமியின் ஆட்சி நீடிப்பதற்கு இந்த 22 இடங்களில் குறைந்தபட்சம் 9 இடங்களிலாவது அதிமுக வென்றாக வேண்டும் என்ற இக்கட்டான வாழ்வா சாவா போராட்டம் நிலவியது. கொங்கு மண்டலம் மற்றும் வட மாவட்டங்களில் தீவிரப் பிரச்சாரம் மேற்கொண்ட முதலமைச்சர் ஈபிஎஸ் மிகச் சரியாக 9 இடங்களை வென்று தனது அரசைப் பத்திரமாகக் காப்பாற்றினார். திமுக 13 இடங்களை வென்றாலும் ஆட்சிக்கட்டிலைப் பிடிப்பதற்கான மேஜிக் நம்பரை அவர்களால் எட்ட முடியாமல் போனது. நாடாளுமன்றத் தேர்தலில் படுதோல்வி அடைந்தாலும் சட்டமன்ற இடைத்தேர்தல் உத்திகள் மூலம் எடப்பாடி பழனிசாமி ஒரு சாணக்கியராகத் தனது முதல்வர் நாற்காலியைக் காப்பாற்றிக் கொண்டார்." , year:2019, parties:["dmk", "aiadmk"], newsQuery:"சட்டமன்ற இடைத்தேர்தலில் 9 இடங்களை வென்று ஆட்சியைத் தக்கவைத்த ஈபிஎஸ் 2019"},
  { id:64, season:"பருவம் 06", seasonNum:6, date:"அக்டோபர் 11-12, 2019", title:"மாமல்லபுரத்தில் மோடி - ஜி ஜின்பிங் சர்வதேசச் சந்திப்பு", filter:"alliance", tags:[["கூட்டணி","red"],["நரேந்திர மோடி","gray"],["மாமல்லபுரம்","gray"]], desc:"இந்தியப் பிரதமர் நரேந்திர மோடி மற்றும் சீன அதிபர் ஜி ஜின்பிங் இடையேயான 2-வது சர்வதேச முறைசாரா உச்சி மாநாட்டிற்கு வரலாற்றுச் சிறப்புமிக்க மாமல்லபுரம் தேர்வு செய்யப்பட்டது. அக்டோபர் 11 அன்று சென்னை வந்த சீன அதிபரைத் தமிழக அரசு பாரம்பரிய முறைப்படி பூரண கும்ப மரியாதையுடன் கோலாகலமாக வரவேற்றது. பிரதமர் மோடி பாரம்பரியத் தமிழ் உடடையான வேட்டி சட்டை மற்றும் துண்டு அணிந்து சீன அதிபரை வரவேற்று மாமல்லபுரத்தின் உலகப் புகழ்பெற்ற சிற்பங்களைச் சுற்றிக் காட்டினார். கடற்கரைக் கோயிலின் பின்னணியில் இரு நாட்டுத் தலைவர்களும் அமர்ந்து இருதரப்பு உறவுகள் மற்றும் உலக அரசியல் குறித்துப் பல மணி நேரம் ரகசிய ஆலோசனைகளை மேற்கொண்டனர். தமிழகத்தின் தொன்மையான கலாச்சாரம் மற்றும் மாமல்லபுரத்தின் சிற்பக் கலை உலக அரங்கில் மிக பிரம்மாண்டமாகப் பறைசாற்றப்பட்ட பெருமைமிகு தருணமாக இந்த இரண்டு நாட்கள் அமைந்தன." , year:2019, parties:["bjp"], newsQuery:"மாமல்லபுரத்தில் மோடி - ஜி ஜின்பிங் சர்வதேசச் சந்திப்பு 2019"},
  { id:65, season:"பருவம் 06", seasonNum:6, date:"நவம்பர் 7, 2019", title:"ஜேப்பியார் கல்விக் குழுமத்தில் ஐடி ரெய்டு தொடக்கம்", filter:"raid", tags:[["ரெய்டு","red"],["ஜேப்பியார் கல்வி","gray"],["வருமான வரித்துறை","gray"]], desc:"சென்னையின் மிக முக்கியக் கல்விப் பேரரசான ஜேப்பியார் கல்வி அறக்கட்டளை மாணவர் சேர்க்கைக் கட்டணங்களில் பல கோடி ரூபாய் வரி ஏய்ப்பு செய்வதாகப் புகார்கள் எழுந்தன. வருமான வரித்துறை புலனாய்வுப் பிரிவினர் சென்னை மற்றும் செங்கல்பட்டு மாவட்டங்களில் உள்ள சத்யபாமா, பனிமலர் உள்ளிட்ட 32 கல்வி நிறுவனங்களின் வளாகங்களில் நுழைந்தனர். ஜேப்பியாரின் மறைவுக்குப் பின் அந்த நிறுவனங்களை நிர்வகித்து வந்த அவரது வாரிசுகளான டாக்டர் என். மேரி வில்சன் (மரிய வில்சன்) உள்ளிட்டோரின் வீடுகளும் குறிவைக்கப்பட்டன. கல்லூரிகளில் 'மேனேஜ்மென்ட் கோட்டா' மூலம் பெறப்பட்ட கணக்கில் வராத கட்டணப் பணம் எங்குப் பதுக்கப்பட்டுள்ளது என்பதை அறிய இந்தச் சோதனை நடத்தப்பட்டது. கல்வி நிறுவனங்களின் பெயரில் நடக்கும் நிழல் பொருளாதாரப் பரிவர்த்தனைகளை வெளிக்கொண்டு வர ஐடி துறை எடுத்த மிக முக்கிய அதிரடி நடவடிக்கையாக இது அமைந்தது." , year:2019, parties:["it_dept"], newsQuery:"ஜேப்பியார் கல்விக் குழுமத்தில் ஐடி ரெய்டு தொடக்கம் 2019"},
  { id:66, season:"பருவம் 06", seasonNum:6, date:"நவம்பர் 11, 2019", title:"மேரி வில்சன் இடங்களில் 350 கோடி கணக்கில் காட்டாத வருவாய் பறிமுதல்", filter:"raid", tags:[["ரெய்டு","red"],["மேரி வில்சன்","gray"],["₹350 கோடி","gray"]], desc:"ஜேப்பியார் குழும கல்வி நிறுவனங்கள் மற்றும் அதன் தாளாளர் டாக்டர் என். மேரி வில்சன் இல்லங்களில் 5 நாட்கள் நடந்த சோதனை அதிகாரப்பூர்வமாக நிறைவடைந்தது. இந்தச் சோதனையின் போது ரகசிய அறைகளில் மறைத்து வைக்கப்பட்டிருந்த ₹5 கோடி ரொக்கப் பணம் மற்றும் ₹3 கோடி மதிப்புள்ள தங்கக் கட்டிகளை அதிகாரிகள் பறிமுதல் செய்தனர். மேலும் கணக்கில் காட்டாமல் மாணவர்களிடம் இருந்து வசூலிக்கப்பட்ட சுமார் ₹350 கோடி ரூபாய் மதிப்பிலான கட்டண ஆவணங்கள் மற்றும் ரகசிய டைரிகள் சிக்கின. கல்வி அறக்கட்டளையின் பணத்தை வணிக ரீதியான ரியல் எஸ்டேட் தொழில்களில் முதலீடு செய்ததற்கான முக்கியப் பத்திரங்களையும் ஐடி துறை முடக்கியது. இந்தச் சோதனையில் சிக்கிய கல்வி அதிபரான டாக்டர் மேரி வில்சன் பிற்காலத்தில் (2025-ல்) தவெக-வில் இணைந்து ஆர்.கே. நகர் தொகுதியில் வெல்லப்போகும் அரசியல் திருப்பத்திற்கு இதுவே புள்ளியாக அமைந்தது." , year:2019, parties:["tvk", "it_dept"], newsQuery:"மேரி வில்சன் இடங்களில் 350 கோடி கணக்கில் காட்டாத வருவாய் பறிமுதல் 2019"},
  { id:67, season:"பருவம் 07", seasonNum:7, date:"பிப்ரவரி 5, 2020", title:"விஜய்யைக் குறிவைத்த ஐடி - நெய்வேலியில் இருந்து விசாரணைக்கு அழைப்பு", filter:"raid", tags:[["ரெய்டு","red"],["நடிகர் விஜய்","gray"],["அரசியல் மிரட்டல்","gray"]], desc:"'பிகில்' திரைப்படத்தின் பல கோடி ரூபாய் பணப் பரிவர்த்தனையில் வரி ஏய்ப்பு நடந்ததாகக் கூறி நடிகர் விஜய்யின் பனையூர் மற்றும் சாலிகிராமம் இல்லங்களில் ஐடி துறை புகுந்தது. நெய்வேலியில் 'மாஸ்டர்' படப்பிடிப்பில் இருந்த விஜய்யை படப்பிடிப்புத் தளத்திலேயே சுற்றி வளைத்த ஐடி அதிகாரிகள் அங்கேயே பல மணி நேரம் அவரிடம் விசாரணை நடத்தினர். பின்னர் அவரது காரிலேயே அதிகாரிகளுடன் சென்னைக்கு அழைத்து வரப்பட்ட விஜய் பனையூர் வீட்டில் வைத்துத் தீவிர விசாரணைக்கு உட்படுத்தப்பட்டார். உச்ச நட்சத்திரமான விஜய்யை படப்பிடிப்புத் தளத்தில் இருந்து விசாரணைக்கு அழைத்து வந்தது அவரது கோடிக்கணக்கான ரசிகர்களைக் கொந்தளிக்கச் செய்தது. இது வெறும் வரி ஏய்ப்பு சோதனை அல்ல; மெர்சல், சர்கார் போன்ற படங்களில் ஆளுங்கட்சிகளுக்கு எதிராக விஜய் பேசிய வசனங்களுக்கான 'அரசியல் மிரட்டல்' என்றே பரவலாகப் பேசப்பட்டது." , year:2020, parties:["tvk", "it_dept"], newsQuery:"விஜய்யைக் குறிவைத்த ஐடி - நெய்வேலியில் இருந்து விசாரணைக்கு அழைப்பு 2020"},
  { id:68, season:"பருவம் 07", seasonNum:7, date:"பிப்ரவரி 6, 2020", title:"23 மணி நேர ரெய்டு நிறைவு: அன்புச்செழியனிடம் ₹77 கோடி பறிமுதல்", filter:"raid", tags:[["ரெய்டு","red"],["அன்புச்செழியன்","gray"],["₹77 கோடி","gray"]], desc:"ஐ.ஆர்.எஸ் அதிகாரி கே.ஜி. அருண்ராஜ் தலைமையிலான குழுவினர் விஜய்யின் வீடுகளில் தொடர்ந்து 23 மணி நேரமாகத் தங்களது துருவித் துருவியான சோதனையை நடத்தினர். சோதனையின் முடிவில் நடிகர் விஜய்யிடம் கணக்கில் வராத பணம் அல்லது ஆவணங்கள் எதுவும் இல்லை என ஐடி துறை அதிகாரப்பூர்வமாக அறிவித்தது. ஆனால் திரைப்பட ஃபைனான்சியர் அன்புச்செழியனுக்குச் சொந்தமான ரகசிய இடங்களில் இருந்து ₹77 கோடி ரொக்கப் பணத்தை அதிகாரிகள் கட்டுக்கட்டாகப் பறிமுதல் செய்தனர். விஜய்யிடம் எந்தத் தவறும் நிரூபிக்கப்படாவிட்டாலும் அவரை மன உளைச்சலுக்கு ஆளாக்க வேண்டும் என்ற நோக்கிலேயே இந்த மெகா ரெய்டு அரங்கேறியதாக விமர்சகர்கள் குற்றம் சாட்டினர். இந்த 23 மணி நேர நெருக்கடிதான் 'நாமே அதிகாரத்திற்கு வந்தால் ஒழிய இந்த அச்சுறுத்தல்களைத் தவிர்க்க முடியாது' என்ற அரசியல் உந்துதலை விஜய்யின் மனதில் ஆழமாக விதைத்தது." , year:2020, parties:["tvk", "it_dept"], newsQuery:"23 மணி நேர ரெய்டு நிறைவு: அன்புச்செழியனிடம் ₹77 கோடி பறிமுதல் 2020"},
  { id:69, season:"பருவம் 07", seasonNum:7, date:"பிப்ரவரி 7, 2020", title:"நெய்வேலி செல்ஃபி - இணையத்தை அதிரவைத்த விஜய்யின் மாஸ் ரிட்டர்ன்", filter:"alliance", tags:[["ரசிகர்கள்","red"],["நெய்வேலி செல்ஃபி","gray"],["நடிகர் விஜய்","gray"]], desc:"ஐடி சோதனைகளை வெற்றிகரமாக எதிர்கொண்டு முடித்த கையோடு நெய்வேலியில் நடைபெற்று வந்த 'மாஸ்டர்' படப்பிடிப்புத் தளத்திற்கு விஜய் கம்பீரமாகத் திரும்பினார். தங்களின் அபிமான நடிகருக்கு ஆதரவு தெரிவிக்க பல மாவட்டங்களில் இருந்தும் பல்லாயிரக்கணக்கான ரசிகர்கள் நெய்வேலி என்.எல்.சி (NLC) கேட் முன்பு திரண்டிருந்தனர். கூட்டத்தின் ஆரவாரத்தைக் கண்ட விஜய் படப்பிடிப்பு வேனின் மீது ஏறி நின்று அந்த மாபெரும் மக்கள் கடலின் பின்னணியில் தனது செல்போனில் ஒரு செல்ஃபி எடுத்தார். 'Thank you Neyveli' என்ற ஒற்றை வரியோடு விஜய் தனது ட்விட்டர் (X) பக்கத்தில் பதிவிட்ட அந்தப் புகைப்படம் இந்திய அளவில் ட்ரெண்டாகி மாபெரும் சரித்திரம் படைத்தது. அதிகார வர்க்கத்தின் அச்சுறுத்தல்களுக்குப் பயப்படாமல் 'என் பலம் என் மக்கள்' என்பதை டெல்லிக்கும் ஆளுங்கட்சிக்கும் விஜய் சொல்லாமல் சொன்ன தருணம் இதுவாகும்." , year:2020, parties:["tvk"], newsQuery:"நெய்வேலி செல்ஃபி - இணையத்தை அதிரவைத்த விஜய்யின் மாஸ் ரிட்டர்ன் 2020"},
  { id:70, season:"பருவம் 07", seasonNum:7, date:"ஜூன் 19, 2020", title:"சாத்தான்குளம் ஜெயராஜ் - பென்னிக்ஸ் கஸ்டடி மரணம்", filter:"crisis", tags:[["நெருக்கடி","red"],["கஸ்டடி மரணம்","gray"],["சாத்தான்குளம்","gray"]], desc:"கொரோனா ஊரடங்கு காலத்தில் தூத்துக்குடி மாவட்டம் சாத்தான்குளத்தில் செல்போன் கடை வைத்திருந்த ஜெயராஜ் மற்றும் அவரது மகன் பென்னிக்ஸ் போலீசாரால் கைது செய்யப்பட்டனர். சாத்தான்குளம் காவல் நிலையத்திற்குள் வைத்து தந்தை, மகன் இருவரும் போலீசாரால் விடிய விடிய ஈவிரக்கமின்றி லத்திகளால் கொடூரமாகத் தாக்கப்பட்டனர். கோவில்பட்டி கிளைச் சிறையில் அடைக்கப்பட்ட இருவரும் கடுமையான உட்காயங்கள் மற்றும் ரத்தப்போக்கு காரணமாக அடுத்தடுத்து பரிதாபமாக மரணமடைந்தனர். இந்த இரட்டை மரணம் தேசிய அளவில் மாபெரும் அதிர்வலையை ஏற்படுத்தியதோடு காவல்துறையின் அத்துமீறல்களுக்கு எதிராகப் பெரும் மக்கள் போராட்டங்களுக்கு வித்திட்டது. மக்கள் கொந்தளிப்பைத் தொடர்ந்து இந்த வழக்கை சிபிஐ (CBI) வசம் தமிழக அரசு ஒப்படைத்தது; சம்பந்தப்பட்ட காவல் ஆய்வாளர் ஸ்ரீதர் உள்ளிட்ட போலீசார் கைது செய்யப்பட்டுச் சிறையிலடைக்கப்பட்டனர்." , year:2020, parties:["cbi"], newsQuery:"சாத்தான்குளம் ஜெயராஜ் - பென்னிக்ஸ் கஸ்டடி மரணம் 2020"},
  { id:71, season:"பருவம் 07", seasonNum:7, date:"டிசம்பர் 29, 2020", title:"'அரசியலுக்கு வரமாட்டேன்' - ரஜினிகாந்த் அதிகாரப்பூர்வ அறிவிப்பு", filter:"alliance", tags:[["அரசியல்","red"],["ரஜினிகாந்த்","gray"],["அறிவிப்பு","gray"]], desc:"சட்டமன்றத் தேர்தல் நெருங்கிய வேளையில் 2021 ஜனவரியில் அரசியல் கட்சி தொடங்கப் போவதாக நடிகர் ரஜினிகாந்த் டிசம்பர் தொடக்கத்தில் அறிவித்திருந்தார். ஆனால் 'அண்ணாத்த' படப்பிடிப்பின் போது அவருக்குத் திடீர் ரத்த அழுத்த மாறுபாடு ஏற்பட்டு ஹைதராபாத் அப்பல்லோ மருத்துவமனையில் அனுமதிக்கப்பட்டார். கொரோனா தொற்றுப் பரவலும் தீவிரமாக இருந்ததால் மருத்துவர்களின் கடுமையான எச்சரிக்கையைத் தொடர்ந்து ரஜினிகாந்த் ஒரு மிக முக்கியமான முடிவை எடுத்தார். டிசம்பர் 29 அன்று 3 பக்க அறிக்கை வெளியிட்ட அவர் 'என்னை நம்பி வருபவர்களை நடுத்தெருவில் விட விரும்பவில்லை; நான் அரசியல் கட்சி தொடங்கப் போவதில்லை' என அதிகாரப்பூர்வமாக அறிவித்தார். 25 ஆண்டுகளாகத் தமிழக அரசியலில் பெரும் எதிர்பார்ப்பை ஏற்படுத்தியிருந்த ரஜினிகாந்தின் அரசியல் வருகை அந்த ஒற்றை அறிக்கையின் மூலம் நிரந்தரமாக முடிவுக்கு வந்தது." , year:2020, parties:["unknown"], newsQuery:"'அரசியலுக்கு வரமாட்டேன்' - ரஜினிகாந்த் அதிகாரப்பூர்வ அறிவிப்பு 2020"},
  { id:72, season:"பருவம் 07", seasonNum:7, date:"ஜனவரி 27, 2021", title:"4 ஆண்டு சிறைவாசத்திற்குப் பின் சசிகலா விடுதலை", filter:"alliance", tags:[["விடுதலை","red"],["சசிகலா","gray"],["பரப்பன அக்ரஹாரா","gray"]], desc:"சொத்துக்குவிப்பு வழக்கில் பெங்களூரு பரப்பன அக்ரஹாரா சிறையில் 4 ஆண்டுகள் தண்டனையை முழுமையாக அனுபவித்த வி.கே. சசிகலா விடுதலை செய்யப்பட்டார். விடுதலைக்குச் சில நாட்கள் முன்பு அவருக்கு கொரோனா தொற்று ஏற்பட்டதால் விக்டோரியா மருத்துவமனையில் சிகிச்சை பெற்றபடியே அவர் தனது விடுதலை ஆணையைப் பெற்றார். எடப்பாடி பழனிசாமி தலைமையிலான அதிமுக அரசு சசிகலாவின் விடுதலையைத் தங்களுக்கு வரப்போகும் பெரும் ஆபத்தாகவே பார்த்துக் காய்களை நகர்த்தத் தொடங்கியது. சிறையிலிருந்து வெளியே வந்த சசிகலாவை டிடிவி தினகரன் மற்றும் நூற்றுக்கணக்கான அமுமுக தொண்டர்கள் பூங்கொத்து கொடுத்து ஆரவாரமாக வரவேற்றனர். 'நான் மீண்டும் வருவேன்' என்று ஜெயலலிதா நினைவிடத்தில் சபதம் செய்துவிட்டுச் சென்ற சசிகலா 4 ஆண்டுகளுக்குப் பின் மீண்டும் அரசியல் களத்திற்குத் திரும்பிய நாள் இது." , year:2021, parties:["dmk", "aiadmk"], newsQuery:"4 ஆண்டு சிறைவாசத்திற்குப் பின் சசிகலா விடுதலை 2021"},
  { id:73, season:"பருவம் 07", seasonNum:7, date:"பிப்ரவரி 8, 2021", title:"அதிமுக கொடியுடன் தமிழகம் வந்தார் சசிகலா", filter:"alliance", tags:[["கட்சி","red"],["சசிகலா","gray"],["அதிமுக கொடி","gray"]], desc:"பெங்களூரு மருத்துவமனையில் இருந்து டிஸ்சார்ஜ் செய்யப்பட்ட சசிகலா ஒரு வார ஓய்வுக்குப் பின் காரில் சென்னை நோக்கிப் புறப்பட்டார். அவரது காரில் அதிமுக-வின் அதிகாரப்பூர்வக் கொடி கட்டப்பட்டிருந்தது முதலமைச்சர் எடப்பாடி பழனிசாமி தரப்புக்குக் கடும் எரிச்சலையும் கோபத்தையும் ஏற்படுத்தியது. தமிழக எல்லையான ஜூஜூவாடி முதல் சென்னை தியாகராய நகர் வரை வழிநெடுகிலும் அவருக்குப் பிரம்மாண்ட வரவேற்பு அளிக்கப்பட்டது; 350 கி.மீ பயணிக்க 23 மணி நேரம் ஆனது. 'கட்சியை ஒன்றிணைப்பேன், பொது எதிரியான திமுக-வை வீழ்த்துவேன்' என அவர் செய்தியாளர்களிடம் பேசியது அதிமுக-வுக்குள் பெரும் பிளவை ஏற்படுத்தும் என எதிர்பார்க்கப்பட்டது. ஆனால் சசிகலாவின் வருகையால் எந்தவொரு அதிமுக எம்.எல்.ஏ-வும் ஓடி வந்து அவரை ஆதரிக்கவில்லை என்பது எடப்பாடியின் அதிகார பலத்தை உறுதிப்படுத்தியது." , year:2021, parties:["dmk", "aiadmk"], newsQuery:"அதிமுக கொடியுடன் தமிழகம் வந்தார் சசிகலா 2021"},
  { id:74, season:"பருவம் 07", seasonNum:7, date:"மார்ச் 3, 2021", title:"அரசியலில் இருந்து ஒதுங்குவதாக சசிகலா திடீர் அறிவிப்பு", filter:"alliance", tags:[["கட்சி","red"],["சசிகலா","gray"],["அரசியல் விலகல்","gray"]], desc:"சட்டமன்றத் தேர்தலுக்குச் சில வாரங்களே இருந்த நிலையில் சசிகலா மற்றும் தினகரன் ஆகியோர் இணைந்து அதிமுக-விற்கு எதிராக மாபெரும் சவால் விடுப்பார்கள் என எதிர்பார்க்கப்பட்டது. ஆனால் யாருமே எதிர்பாராத விதமாக மார்ச் 3 அன்று இரவு சசிகலா இரண்டு பக்கங்கள் கொண்ட ஒரு திடீர் அறிக்கையை ஊடகங்களுக்கு வெளியிட்டார். 'அம்மா அவர்களின் பொற்கால ஆட்சி தமிழகத்தில் அமைய நான் தெய்வத்திடம் பிரார்த்தனை செய்து அரசியலை விட்டு ஒதுங்கியிருப்பேன்' என அந்த அறிக்கையில் குறிப்பிட்டிருந்தார். அவரது இந்தத் திடீர் முடிவு பல ஆண்டுகளாக அவருக்காகச் செலவு செய்து காத்திருந்த அமுமுக தொண்டர்களையும் டிடிவி தினகரனையும் கடும் அதிர்ச்சியில் ஆழ்த்தியது. டெல்லியில் இருந்து வந்த கடுமையான ரகசிய அழுத்தங்களே சசிகலாவை இந்த முடிவுக்குத் தள்ளியதாக அரசியல் பார்வையாளர்கள் மத்தியில் பரவலாகப் பேசப்பட்டது." , year:2021, parties:["dmk", "aiadmk"], newsQuery:"அரசியலில் இருந்து ஒதுங்குவதாக சசிகலா திடீர் அறிவிப்பு 2021"},
  { id:75, season:"பருவம் 07", seasonNum:7, date:"மார்ச் 2021", title:"அதிரடி ஐ.ஆர்.எஸ் அதிகாரி கே.ஜி. அருண்ராஜ் இடமாற்றம்", filter:"verdict", tags:[["மாற்றம்","red"],["கே.ஜி. அருண்ராஜ்","gray"],["தேர்தல் ஆணையம்","gray"]], desc:"தேர்தல் நெருங்கிய சூழலில் தமிழகத்தில் அரசியல்வாதிகளுக்குச் சிம்ம சொப்பனமாக விளங்கிய வருமான வரித்துறை புலனாய்வு அதிகாரிகளை இடமாற்றம் செய்யத் தேர்தல் ஆணையம் முடிவெடுத்தது. சசிகலா, சேகர் ரெட்டி, விஜயபாஸ்கர் மற்றும் நடிகர் விஜய் எனப் பல முக்கியப் புள்ளிகள் மீது மெகா ரெய்டுகளை நடத்திய ஐ.ஆர்.எஸ் (IRS) அதிகாரி கே.ஜி. அருண்ராஜ் அதிரடியாக மாற்றப்பட்டார். அவர் டெல்லியில் உள்ள மத்திய நேரடி வரிகள் வாரியத்தின் (CBDT) தலைமையகத்திற்குப் பணியிட மாற்றம் செய்யப்படுவதாக மத்திய நிதி அமைச்சகம் உத்தரவு பிறப்பித்தது. நேர்மையான அதிகாரியான அவரைத் தேர்தல் நேரத்தில் இடமாற்றம் செய்தது ஆளுங்கட்சிகளுக்குச் சாதகமாகப் பணப்பட்டுவாடா தடையின்றி நடக்கவே என விமர்சனங்கள் எழுந்தன. (பின்னாளில் இவர் விருப்ப ஓய்வு பெற்று தவெக-வின் முக்கியப் பவுண்டேஷனாக மாறி சுகாதாரத்துறை அமைச்சராகப் பொறுப்பேற்கப் போகிறார் என்பது காலத்தின் பெரும் திருப்புமுனை)." , year:2021, parties:["aiadmk", "tvk", "it_dept"], newsQuery:"அதிரடி ஐ.ஆர்.எஸ் அதிகாரி கே.ஜி. அருண்ராஜ் இடமாற்றம் 2021"},
  { id:76, season:"பருவம் 07", seasonNum:7, date:"ஏப்ரல் 2, 2021", title:"மு.க. ஸ்டாலின் மகள் செந்தாமரை வீட்டில் ஐடி ரெய்டு", filter:"raid", tags:[["ரெய்டு","red"],["செந்தாமரை","gray"],["சபரீசன்","gray"]], desc:"2021 சட்டமன்றத் தேர்தல் வாக்குப்பதிவுக்குச் சரியாக 4 நாட்களே இருந்த பரபரப்பான வேளையில் திமுக தலைவர் மு.க. ஸ்டாலினின் குடும்பத்தைக் குறிவைத்து வருமான வரித்துறை இறங்கியது. ஸ்டாலினின் மகளான செந்தாமரை மற்றும் அவரது கணவர் சபரீசனுக்குச் சொந்தமான நீலாங்கரை இல்லத்தில் 25-க்கும் மேற்பட்ட ஐடி அதிகாரிகள் அதிரடியாக நுழைந்தனர். திமுக-வின் தேர்தல் வியூகங்கள் மற்றும் நிதியைக் கையாண்ட சபரீசனை முடக்கும் வகையிலேயே மத்திய அரசு இந்த அரசியல் அஸ்திரத்தைப் பிரயோகித்ததாக திமுக குற்றம் சாட்டியது. பெரம்பலூரில் பிரச்சாரத்தில் இருந்த மு.க. ஸ்டாலின் 'நான் மிசாவுக்கே பயப்படாதவன்; இந்த ரெய்டுகளுக்கெல்லாம் திமுக ஒருபோதும் அஞ்சாது' என மேடையில் கர்ஜித்தார். சோதனையின் முடிவில் ₹1.36 லட்சம் மட்டுமே கணக்கில் வந்ததாகவும் வேறு பெரிய ஆவணங்கள் ஏதும் சிக்கவில்லை என்றும் கூறப்பட்டது திமுக-வின் தேர்தல் பிரச்சாரத்திற்கு மேலும் வலுவூட்டியது." , year:2021, parties:["dmk", "it_dept"], newsQuery:"மு.க. ஸ்டாலின் மகள் செந்தாமரை வீட்டில் ஐடி ரெய்டு 2021"},
  { id:77, season:"பருவம் 07", seasonNum:7, date:"மே 2, 2021", title:"10 ஆண்டுக்குப் பின் ஆட்சி மாற்றம்: மு.க. ஸ்டாலின் முதல்வரானார்", filter:"verdict", tags:[["வெற்றி","red"],["திமுக ஆட்சி","gray"],["மு.க. ஸ்டாலின்","gray"]], desc:"10 ஆண்டுகள் எதிர்க்கட்சி வரிசையிலிருந்த திமுக தனது கூட்டணிக் கட்சிகளுடன் இணைந்து சந்தித்த 2021 சட்டமன்றத் தேர்தல் முடிவுகள் வெளியாகின. மு.க. ஸ்டாலின் தலைமையிலான மதச்சார்பற்ற முற்போக்குக் கூட்டணி 159 இடங்களைக் கைப்பற்றி (திமுக தனித்து 133 இடங்கள்) மாபெரும் வெற்றியைப் பதிவு செய்தது. முதலமைச்சர் எடப்பாடி பழனிசாமி தலைமையிலான அதிமுக கூட்டணி 75 இடங்களை மட்டுமே பிடித்துத் தோல்வியைச் சந்தித்தது. கடும் நெருக்கடிகளையும் ரெய்டுகளையும் மத்திய அரசின் அழுத்தங்களையும் தாண்டி மு.க. ஸ்டாலின் தனது ஒற்றைத் தலைமையின் கீழ் முதல்முறையாக ஆட்சியைக் கைப்பற்றினார். எடப்பாடி பழனிசாமி தனது முதலமைச்சர் பதவியை ராஜினாமா செய்ய திராவிட முன்னேற்றக் கழகம் தமிழ்நாட்டில் மீண்டும் அரியாசனம் ஏறியது." , year:2021, parties:["dmk", "aiadmk"], newsQuery:"10 ஆண்டுக்குப் பின் ஆட்சி மாற்றம்: மு.க. ஸ்டாலின் முதல்வரானார் 2021"},
  { id:78, season:"பருவம் 07", seasonNum:7, date:"மே 7, 2021", title:"மு.க. ஸ்டாலின் முதல்வராகப் பதவியேற்பு (5 கோப்புகளில் கையெழுத்து)", filter:"oath", tags:[["பதவியேற்பு","red"],["முதலமைச்சர்","gray"],["5 கையெழுத்து","gray"]], desc:"கொரோனா ஊரடங்கு காரணமாக எந்தவொரு ஆடம்பரமுமின்றி சென்னை கிண்டி ஆளுணர் மாளிகையில் மு.க. ஸ்டாலின் தமிழ்நாட்டின் முதலமைச்சராகப் பதவிப் பிரமாணம் எடுத்துக் கொண்டார். 'முத்துவேல் கருணாநிதி ஸ்டாலின் எனும் நான்...' என்று அவர் உச்சரித்த போது 50 ஆண்டுகால அவரது அரசியல் உழைப்பிற்கான அங்கீகாரம் அந்த வார்த்தைகளில் ஒலித்தது. பதவியேற்றவுடன் தலைமைச் செயலகம் சென்ற அவர் தனது தேர்தல் வாக்குறுதிகளை நிறைவேற்றும் வகையில் 5 முக்கிய கோப்புகளில் கையெழுத்திட்டார். கொரோனா நிவாரண நிதியாக அரிசி அட்டைதாரர்களுக்கு ₹4,000, ஆவின் பால் விலை ₹3 குறைப்பு மற்றும் மகளிருக்கு அரசுப் பேருந்துகளில் இலவசப் பயணம் ஆகியவை அதில் அடங்கும். மு.க. ஸ்டாலினின் இந்த ஆரம்பகட்ட நடவடிக்கைகள் மக்களிடம் பெரும் வரவேற்பைப் பெற்றன; தமிழக நிர்வாக எந்திரம் புதிய வேகத்தோடு இயங்கத் தொடங்கியது." , year:2021, parties:["dmk"], newsQuery:"மு.க. ஸ்டாலின் முதல்வராகப் பதவியேற்பு (5 கோப்புகளில் கையெழுத்து) 2021"},
  { id:79, season:"பருவம் 08", seasonNum:8, date:"ஜூலை - டிசம்பர் 2021", title:"மாஜி அதிமுக அமைச்சர்கள் வீடுகளில் லஞ்ச ஒழிப்புத்துறை (DVAC) மெகா ரெய்டுகள்", filter:"raid", tags:[["ரெய்டு","red"],["மாஜி அமைச்சர்கள்","gray"],["DVAC","gray"]], desc:"திமுக ஆட்சி அமைந்த சில மாதங்களிலேயே ஊழல் செய்த கடந்த கால அதிமுக அமைச்சர்களைச் சட்டத்தின் முன் நிறுத்தும் வாக்குறுதியை ஸ்டாலின் அரசு கையில் எடுத்தது. தமிழக லஞ்ச ஒழிப்புத்துறை (DVAC) அதிகாரிகள் ஊழல் மற்றும் வருமானத்திற்கு அதிகமாகச் சொத்து சேர்த்த புகாரில் முன்னாள் அமைச்சர்கள் மீது அதிரடி வழக்குகளைப் பதிவு செய்தனர். எம்.ஆர். விஜயபாஸ்கர், எஸ்.பி. வேலுமணி, கே.சி. வீரமணி, சி. விஜயபாஸ்கர் மற்றும் பி. தங்கமணி ஆகியோரது வீடுகள் மற்றும் நிறுவனங்களில் அடுத்தடுத்து மெகா சோதனைகள் நடந்தன. கிலோ கணக்கில் தங்கம், பல கோடி ரூபாய் ரொக்கம் மற்றும் ஆயிரக்கணக்கான கோடி மதிப்பிலான பினாமி சொத்து ஆவணங்கள் இந்த ரெய்டுகளில் கைப்பற்றப்பட்டன. எடப்பாடி பழனிசாமியின் வலதுகரங்களாகச் செயல்பட்ட முன்னாள் அமைச்சர்களின் பொருளாதார மூலதனங்களை முடக்கும் திமுக-வின் அரசியல் மற்றும் சட்ட ரீதியான முதல் தாக்குதலாக இது அமைந்தது." , year:2021, parties:["dmk", "aiadmk"], newsQuery:"மாஜி அதிமுக அமைச்சர்கள் வீடுகளில் லஞ்ச ஒழிப்புத்துறை (DVAC) மெகா ரெய்டுகள் 2021"},
  { id:80, season:"பருவம் 08", seasonNum:8, date:"ஜூன் 23, 2022", title:"அதிமுக பொதுக்குழுவில் ஒற்றைத் தலைமை மோதல் வெடிப்பு", filter:"crisis", tags:[["மோதல்","red"],["ஒற்றைத் தலைமை","gray"],["ஓபிஎஸ் அவமானம்","gray"]], desc:"ஈபிஎஸ் மற்றும் ஓபிஎஸ் இரட்டைத் தலைமையில் செயல்பட்டு வந்த அதிமுக-வுக்குள் 'யாருக்கு அதிகாரம்?' என்ற ஒற்றைத் தலைமை கோஷம் விஸ்வரூபம் எடுத்தது. சென்னை வானகரத்தில் பிரம்மாண்டமாகக் கூடிய பொதுக்குழு கூட்டத்தில் எடப்பாடி பழனிசாமி தரப்பினர் ஒற்றைத் தலைமையை வலியுறுத்தி பெரும் ரகளையில் ஈடுபட்டனர். கூட்டத்திற்கு வந்த ஓ. பன்னீர்செல்வம் மீது தண்ணீர் பாட்டில்கள் வீசப்பட்டன; 'துரோகி ஓபிஎஸ்' என முழக்கங்கள் எழுப்பப்பட்டு அவர் அவமானப்படுத்தப்பட்டார். மேடையில் இருந்த தமிழ்மகன் உசேன் தற்காலிக அவைத்தலைவராகத் தேர்ந்தெடுக்கப்பட ஓபிஎஸ் மற்றும் அவரது ஆதரவாளர்கள் பொதுக்குழுவை விட்டுப் பாதியிலேயே வெளிநடப்பு செய்தனர். சமரசமாகச் சென்று கொண்டிருந்த இரட்டைத் தலைமை என்ற மாயை உடைந்து அதிமுக இரண்டு மாபெரும் அதிகார மையங்களாக பகிரங்கமாகப் பிளவுபட்ட நாள் இது." , year:2022, parties:["dmk", "aiadmk"], newsQuery:"அதிமுக பொதுக்குழுவில் ஒற்றைத் தலைமை மோதல் வெடிப்பு 2022"},
  { id:81, season:"பருவம் 08", seasonNum:8, date:"ஜூலை 11, 2022", title:"பொதுக்குழுவில் ஈபிஎஸ் இடைக்காலப் பொதுச்செயலாளர்; ஓபிஎஸ் நீக்கம்", filter:"alliance", tags:[["கட்சி","red"],["ஈபிஎஸ் பொதுச்செயலாளர்","gray"],["ஓபிஎஸ் நீக்கம்","gray"]], desc:"நீதிமன்றத் தடைகளை உடைத்து ஜூலை 11 அன்று மீண்டும் வானகரத்தில் அதிமுக-வின் சிறப்புப் பொதுக்குழு மற்றும் செயற்குழுக் கூட்டம் ஈபிஎஸ் தலைமையில் கூடியது. கூட்டத்தில் கட்சியின் இரட்டைத் தலைமை முறை (ஒருங்கிணைப்பாளர் பதவிகள்) ரத்து செய்யப்பட்டு எடப்பாடி பழனிசாமி கட்சியின் 'இடைக்காலப் பொதுச்செயலாளராக' ஏகமனதாகத் தேர்ந்தெடுக்கப்பட்டார். அதே மேடையில் கட்சிக்கு எதிராகச் செயல்பட்டதாகக் கூறி ஓ. பன்னீர்செல்வம் மற்றும் அவரது ஆதரவாளர்கள் அனைவரையும் கட்சியின் அடிப்படை உறுப்பினரிலிருந்து அதிரடியாக நீக்கினர். ஜெயலலிதாவால் கை காட்டப்பட்ட ஓபிஎஸ்-ஐ அதே தொண்டர்களை வைத்து எடப்பாடி பழனிசாமி கட்சியை விட்டே துரத்திய இந்த நிகழ்வு தமிழக அரசியலின் உச்சகட்ட அதிகாரப் போட்டியாகும். இதன் மூலம் கொங்கு மண்டலத்தைச் சேர்ந்த எடப்பாடி பழனிசாமி எம்.ஜி.ஆர் மற்றும் ஜெயலலிதா வரிசையில் கட்சியின் ஒட்டுமொத்த அதிகாரத்தையும் தன்வசப்படுத்திக் கொண்டார்." , year:2022, parties:["dmk", "aiadmk"], newsQuery:"பொதுக்குழுவில் ஈபிஎஸ் இடைக்காலப் பொதுச்செயலாளர்; ஓபிஎஸ் நீக்கம் 2022"},
  { id:82, season:"பருவம் 08", seasonNum:8, date:"ஜூலை 11, 2022 (பிற்பகல்)", title:"ராயப்பேட்டை அதிமுக தலைமை அலுவலகம் உடைப்பு & சீல் வைப்பு", filter:"crisis", tags:[["கலவரம்","red"],["தலைமையகம் உடைப்பு","gray"],["RDO சீல்","gray"]], desc:"வானகரத்தில் ஈபிஎஸ் பொதுக்குழுவை நடத்திக் கொண்டிருந்த அதே வேளையில் ராயப்பேட்டையில் உள்ள அதிமுக தலைமை அலுவலகத்திற்கு ஓபிஎஸ் தனது ஆதரவாளர்களுடன் சென்றார். பூட்டப்பட்டிருந்த தலைமைக் கழகக் கதவுகளை ஓபிஎஸ் ஆதரவாளர்கள் கடப்பாரை கொண்டு உடைத்து உள்ளே நுழைந்ததால் இரு தரப்புக்கும் இடையே பெரும் வன்முறை வெடித்தது. கற்கள் மற்றும் தடியடி தாக்குதல்களால் அதிமுக அலுவலகம் போர்க்களமாக மாறியது; பல தொண்டர்கள் ரத்தக் காயங்களுடன் மருத்துவமனையில் அனுமதிக்கப்பட்டனர். சட்டம் ஒழுங்கு சீர்குலைந்ததைக் காரணம் காட்டி வருவாய்க் கோட்டாட்சியர் (RDO) 145-வது பிரிவின் கீழ் தலைமைக் கழகத்திற்கு அதிரடியாக சீல் வைத்தார். 50 ஆண்டுகால பாரம்பரியமிக்க எம்.ஜி.ஆர் மாளிகையின் கதவுகள் அதன் தொண்டர்களாலேயே உடைக்கப்பட்ட கறுப்பு நாளாக இந்த ஜூலை 11 முடிவடைந்தது." , year:2022, parties:["dmk", "aiadmk"], newsQuery:"ராயப்பேட்டை அதிமுக தலைமை அலுவலகம் உடைப்பு & சீல் வைப்பு 2022"},
  { id:83, season:"பருவம் 08", seasonNum:8, date:"ஜூலை 17, 2022", title:"கள்ளக்குறிச்சி மாணவி ஸ்ரீமதி மரணமும் மாபெரும் கலவரமும்", filter:"crisis", tags:[["கலவரம்","red"],["கள்ளக்குறிச்சி","gray"],["ஸ்ரீமதி மரணம்","gray"]], desc:"கள்ளக்குறிச்சி மாவட்டம் கனியாமூரில் உள்ள தனியார் பள்ளியில் விடுதியில் தங்கிப் படித்த 12-ம் வகுப்பு மாணவி ஸ்ரீமதி மர்மமான முறையில் மாடியிலிருந்து விழுந்து உயிரிழந்தார். பள்ளி நிர்வாகத்தின் விளக்கங்களில் சந்தேகம் அடைந்த பெற்றோர் மற்றும் பொதுமக்கள் மரணத்திற்கு நீதி கேட்டுப் பல நாட்களாக அமைதியான முறையில் போராடி வந்தனர். ஜூலை 17 காலை சமூக வலைதளங்கள் மூலம் ஒருங்கிணைக்கப்பட்ட ஆயிரக்கணக்கான இளைஞர்கள் பள்ளி வளாகத்திற்குள் நுழைந்து மாபெரும் வன்முறையில் ஈடுபட்டனர். பள்ளிப் பேருந்துகள் தீக்கிரையாக்கப்பட்டன; போலீஸ் வாகனங்கள் அடித்து நொறுக்கப்பட்டு மாணவர்களின் சான்றிதழ்கள் உட்படப் பள்ளி முழுமையாகச் சூறையாடப்பட்டது. உளவுத்துறையின் பெரும் தோல்வியாகப் பார்க்கப்பட்ட இந்த வன்முறைச் சம்பவம் திமுக அரசுக்குச் சட்டம் ஒழுங்கு ரீதியாக மிகப் பெரிய சவாலையும் களங்கத்தையும் ஏற்படுத்தியது." , year:2022, parties:["dmk"], newsQuery:"கள்ளக்குறிச்சி மாணவி ஸ்ரீமதி மரணமும் மாபெரும் கலவரமும் 2022"},
  { id:84, season:"பருவம் 08", seasonNum:8, date:"செப்டம்பர் 2, 2022", title:"நீதிமன்றத் தீர்ப்பின் மூலம் ஈபிஎஸ் வசம் சென்ற அதிமுக அலுவலகம்", filter:"verdict", tags:[["தீர்ப்பு","red"],["உயர்நீதிமன்றம்","gray"],["ஈபிஎஸ் வெற்றி","gray"]], desc:"சீல் வைக்கப்பட்ட அதிமுக தலைமை அலுவலகத்தின் சாவியைப் பெற ஓபிஎஸ் மற்றும் ஈபிஎஸ் என இரு தரப்பினரும் சென்னை உயர்நீதிமன்றத்தில் கடுமையான சட்டப் போராட்டத்தை நடத்தினர். இரு தரப்பு வாதங்களையும் கேட்ட நீதிமன்றம் கட்சியில் பெரும்பான்மை எம்.எல்.ஏ-க்கள் மற்றும் பொதுக்குழு உறுப்பினர்களின் ஆதரவு ஈபிஎஸ் வசமே உள்ளது என்பதை ஏற்றுக்கொண்டது. தலைமைக் கழகத்தின் சாவியை எடப்பாடி பழனிசாமி தரப்பிடம் மட்டுமே ஒப்படைக்க வேண்டும் என உயர்நீதிமன்றம் அதிரடியாக உத்தரவிட்டது. நீதிமன்ற உத்தரவின்படி சீல் அகற்றப்பட்டு கட்சி அலுவலகம் முழுமையாக ஈபிஎஸ் வசம் வந்ததைத் தொடர்ந்து அவரது ஆதரவாளர்கள் பட்டாசு வெடித்துக் கொண்டாடினர். இந்தத் தீர்ப்பு ஓ. பன்னீர்செல்வத்தின் அரசியல் பயணத்திற்கு மிகப் பெரிய முற்றுப்புள்ளியாக அமைந்தது; எடப்பாடியின் அசைக்க முடியாத பலம் சட்டபூர்வமாகவும் உறுதியானது." , year:2022, parties:["dmk", "aiadmk"], newsQuery:"நீதிமன்றத் தீர்ப்பின் மூலம் ஈபிஎஸ் வசம் சென்ற அதிமுக அலுவலகம் 2022"},
  { id:85, season:"பருவம் 08", seasonNum:8, date:"செப்டம்பர் 14, 2022", title:"கோடநாடு வழக்கு சிபிசிஐடி-க்கு (CB-CID) மாற்றம்", filter:"verdict", tags:[["விசாரணை","red"],["கோடநாடு","gray"],["சிபிசிஐடி","gray"]], desc:"2017-ல் நடந்த கோடநாடு கொலை மற்றும் கொள்ளை வழக்கு எடப்பாடி பழனிசாமி ஆட்சிக் காலத்தில் சாதாரணப் போலீஸ் விசாரணையோடு கிடப்பில் போடப்பட்டிருந்தது. வழக்கில் உள்ள பின்னணி அரசியல் மர்மங்களை வெளியே கொண்டுவருவதாக திமுக தனது தேர்தல் அறிக்கையில் உறுதியளித்திருந்த நிலையில் விசாணையைத் தீவிரப்படுத்த அரசு முடிவெடுத்தது. பல ஆண்டுகளாகத் தொய்வடைந்திருந்த இந்த வழக்கின் விசாரணையை தனிப்படையிடமிருந்து சிபிசிஐடி-க்கு (CB-CID) மாற்றித் தமிழக அரசின் உள்துறை அதிகாரப்பூர்வ அரசாணை வெளியிட்டது. முக்கியக் குற்றவாளிகளின் மரணம் மற்றும் எஸ்டேட் ஆவணங்கள் காணாமல் போனது குறித்து சிபிசிஐடி புதிதாகத் தனது வேட்டையைத் தொடங்கியது. எடப்பாடி பழனிசாமிக்குக் குடைச்சல் கொடுக்கவே இந்த வழக்கைத் திமுக அரசு தூசி தட்டுவதாக அதிமுக தரப்பில் கடுமையான அரசியல் விமர்சனங்கள் முன்வைக்கப்பட்டன." , year:2022, parties:["dmk", "aiadmk"], newsQuery:"கோடநாடு வழக்கு சிபிசிஐடி-க்கு (CB-CID) மாற்றம் 2022"},
  { id:86, season:"பருவம் 08", seasonNum:8, date:"மார்ச் 5, 2023", title:"பாஜக ஐடி விங் தலைவர் நிர்மல்குமார் அதிமுக-வில் இணைவு", filter:"alliance", tags:[["கட்சி","red"],["நிர்மல்குமார்","gray"],["பாஜக-அதிமுக","gray"]], desc:"அண்ணாமலை தமிழக பாஜக தலைவராகப் பொறுப்பேற்ற பிறகு கட்சியின் மூத்த நிர்வாகிகள் மற்றும் ஐடி விங் நிர்வாகிகள் மத்தியில் பெரும் அதிருப்தி புகைந்து கொண்டிருந்தது. தமிழக பாஜக-வின் தகவல் தொழில்நுட்பப் பிரிவு (IT Wing) மாநிலத் தலைவராகப் பணியாற்றி வந்த சி.டி.ஆர். நிர்மல்குமார் அண்ணாமலை மீது கடுமையான குற்றச்சாட்டுகளை முன்வைத்தார். 'கட்சியை ஒரு மனிதன் தன் சொந்த விளம்பரத்திற்காக அழிக்கிறார்' என்று பகிரங்கமாக அறிக்கை வெளியிட்டு பாஜக-விலிருந்து அதிரடியாக விலகினார். விலகிய அன்றே முதலமைச்சர் எடப்பாடி பழனிசாமியை அவரது இல்லத்தில் நேரில் சந்தித்து தன்னை அதிமுக-வில் அதிகாரப்பூர்வமாக இணைத்துக் கொண்டார். (அதிமுக-வின் ஐடி விங் பணிகளைக் கவனித்த இவர் பின்னாளில் ஜனவரி 2025-ல் தவெக-வில் இணைந்து சட்டம் மற்றும் மின்சாரத்துறை அமைச்சராக உருவெடுக்கப் போவது அரசியல் ஆச்சரியம்!)." , year:2023, parties:["bjp", "dmk", "aiadmk", "tvk"], newsQuery:"பாஜக ஐடி விங் தலைவர் நிர்மல்குமார் அதிமுக-வில் இணைவு 2023"},
  { id:87, season:"பருவம் 08", seasonNum:8, date:"மார்ச் 28, 2023", title:"ஈபிஎஸ்-ஐ பொதுச்செயலாளராக அங்கீகரித்த தேர்தல் ஆணையம்", filter:"verdict", tags:[["தீர்ப்பு","red"],["தேர்தல் ஆணையம்","gray"],["ஈபிஎஸ் அதிகாரம்","gray"]], desc:"ஒற்றைத் தலைமை விவகாரத்தில் பல மாதங்களாகத் தொடர்ந்த அனைத்து நீதிமன்ற வழக்குகளிலும் எடப்பாடி பழனிசாமி தரப்பே தொடர் வெற்றிகளைப் பெற்றது. உச்சநீதிமன்றமும் ஈபிஎஸ் கூட்டிய பொதுக்குழு செல்லும் எனத் தீர்ப்பளித்ததைத் தொடர்ந்து அதிமுக-வில் உள்கட்சித் தேர்தல் நடத்தப்பட்டு ஈபிஎஸ் பொதுச்செயலாளராகத் தேர்ந்தெடுக்கப்பட்டார். அனைத்து சட்டச் சிக்கல்களும் தீர்ந்த நிலையில் இந்தியத் தேர்தல் ஆணையம் (ECI) எடப்பாடி பழனிசாமியை அதிமுக-வின் அதிகாரப்பூர்வப் 'பொதுச்செயலாளராக' அங்கீகரித்தது. இரட்டை இலைச் சின்னமும் அவர் வசமே இருக்கும் என்பதைத் தேர்தல் ஆணையம் உறுதிப்படுத்தியதால் கட்சி முழுவதும் ஈபிஎஸ் என்ற ஒற்றை மனிதரின் முழுமையான கட்டுப்பாட்டுக்குள் வந்தது. ஓபிஎஸ், டிடிவி தினகரன் மற்றும் சசிகலா ஆகிய மூவரையும் அரசியல் களத்தில் இருந்து ஓரங்கட்டிவிட்டு எடப்பாடி பழனிசாமி அடைந்த உச்சகட்ட வெற்றி இதுவாகும்." , year:2023, parties:["dmk", "aiadmk"], newsQuery:"ஈபிஎஸ்-ஐ பொதுச்செயலாளராக அங்கீகரித்த தேர்தல் ஆணையம் 2023"},
  { id:88, season:"பருவம் 09", seasonNum:9, date:"மே 2023", title:"கரூரில் செந்தில் பாலாஜி ஆதரவாளர்களால் ஐடி அதிகாரிகள் மீது கொடூரத் தாக்குதல்", filter:"crisis", tags:[["கலவரம்","red"],["செந்தில் பாலாஜி","gray"],["ஐடி ரெய்டு","gray"]], desc:"மின்சாரத்துறை அமைச்சராக இருந்த வி. செந்தில் பாலாஜியின் சகோதரர் அசோக்குமார் மற்றும் அவரது ஆதரவாளர்கள் வீடுகளில் சோதனை நடத்த வருமான வரித்துறை அதிகாரிகள் கரூருக்குச் சென்றனர். அப்போது கரூரில் குவிந்த செந்தில் பாலாஜியின் நூற்றுக்கணக்கான ஆதரவாளர்கள் ஐடி அதிகாரிகளின் காரை முற்றுகையிட்டுப் பயங்கரமான வாக்குவாதத்தில் ஈடுபட்டனர். பெண் அதிகாரிகள் என்றும் பாராமல் அவர்களைத் தள்ளிவிட்டு பெண் அதிகாரியின் கையை உடைத்து அதிகாரிகளை ஓட ஓட விரட்டி கொடூரமான முறையில் தாக்கினர். மத்திய அரசு அதிகாரிகளின் மீதே தமிழகத்தில் ஆளுங்கட்சியினர் நடத்திய இந்தத் தாக்குதல் தேசிய ஊடகங்களில் வெளியாகித் தமிழக சட்டம் ஒழுங்கு சீர்குலைவை வெளிச்சம் போட்டுக் காட்டியது. கரூர் நகரக் காவல் நிலையத்தில் இந்த வன்முறை தொடர்பாகப் பலத்த பிரிவுகளின் கீழ் FIR பதியப்பட்டதுடன் செந்தில் பாலாஜியை முடக்குவதற்கான டெல்லியின் அடுத்த அதிரடி ஆட்டத்திற்கு இதுவே காரணமாக அமைந்தது." , year:2023, parties:["it_dept"], newsQuery:"கரூரில் செந்தில் பாலாஜி ஆதரவாளர்களால் ஐடி அதிகாரிகள் மீது கொடூரத் தாக்குதல் 2023"},
  { id:89, season:"பருவம் 09", seasonNum:9, date:"ஜூன் 14, 2023", title:"வேலைக்கு பணம் பெற்ற வழக்கில் அமைச்சர் செந்தில் பாலாஜி ED-ஆல் கைது", filter:"raid", tags:[["கைது","red"],["செந்தில் பாலாஜி","gray"],["அமலாக்கத்துறை","gray"]], desc:"கடந்த அதிமுக ஆட்சிக் காலத்தில் போக்குவரத்துத் துறையில் வேலை வாங்கித் தருவதாகக் கூறி பல கோடி ரூபாய் முறைகேடு செய்ததாகச் (Cash for Jobs Scam) செந்தில் பாலாஜி மீது வழக்கு இருந்தது. இதன் அடிப்படையில் ஜூன் 13 காலை முதல் சென்னை பசுமை வழிச்சாலையில் உள்ள அவரது இல்லம் மற்றும் தலைமைச் செயலகத்தில் உள்ள அவரது அலுவலகத்தில் அமலாக்கத்துறை (ED) 18 மணி நேரம் அதிரடி சோதனை நடத்தியது. சோதனையின் முடிவில் முறையான ஒத்துழைப்பு அளிக்கவில்லை எனக் கூறி ஜூன் 14 அதிகாலை நள்ளிரவில் செந்தில் பாலாஜியை அமலாக்கத்துறை அதிகாரிகள் அதிகாரப்பூர்வமாகக் கைது செய்தனர். தமிழக வரலாற்றிலேயே தலைமைச் செயலகத்தில் உள்ள ஒரு அமைச்சரின் அறையிலேயே மத்திய ஏஜென்சி புகுந்து சோதனை நடத்தி நள்ளிரவில் கைது செய்தது இதுவே முதல்முறையாகும். இந்த அதிரடி நடவடிக்கை திமுக அமைச்சரவையை நிலை குலையச் செய்ததுடன் கரூரின் மிக முக்கிய அரசியல் பவர் சென்டரை உள்ளே தள்ளிய டெல்லியின் மாஸ்டர் ஸ்ட்ரோக்காகப் பார்க்கப்பட்டது." , year:2023, parties:["dmk", "aiadmk"], newsQuery:"வேலைக்கு பணம் பெற்ற வழக்கில் அமைச்சர் செந்தில் பாலாஜி ED-ஆல் கைது 2023"},
  { id:90, season:"பருவம் 09", seasonNum:9, date:"ஜூன் 14, 2023 (நள்ளிரவு)", title:"கைதின்போது நெஞ்சுவலி: மருத்துவமனையில் செந்தில் பாலாஜி அனுமதி", filter:"crisis", tags:[["நெருக்கடி","red"],["நெஞ்சுவலி","gray"],["மருத்துவமனை","gray"]], desc:"அமலாக்கத்துறையால் நள்ளிரவில் கைது செய்யப்பட்ட போது செந்தில் பாலாஜிக்குத் திடீரெனக் கடுமையான நெஞ்சுவலி மற்றும் மூச்சுத்திணறல் ஏற்பட்டது. அவர் நெஞ்சைப் பிடித்துக் கொண்டு காரில் கதறி அழுத காட்சிகள் ஊடகங்களில் வெளியாகி ஒட்டுமொத்த அரசியல் களத்திலும் பரபரப்பைக் கூட்டின. உடனடியாக அவர் ஓமந்தூரார் அரசு பன்னோக்கு மருத்துவமனையில் அனுமதிக்கப்பட்டு அங்கு அவருக்கு இதயத் தமனிகளில் 4 அடைப்புகள் (Triple Vessel Disease) இருப்பது கண்டுபிடிக்கப்பட்டது. பின்னர் நீதிமன்ற அனுமதியுடன் சென்னை காவேரி மருத்துவமனைக்கு மாற்றப்பட்ட அவருக்கு அவசரமாகப் பைபாஸ் (Bypass) அறுவை சிகிச்சை வெற்றிகரமாகச் செய்யப்பட்டது. இந்த மருத்துவமனை நாடகம் கைதைத் தவிர்க்க எடுக்கப்பட்ட உத்தி என அமலாக்கத்துறை நீதிமன்றத்தில் வாதிட்டாலும் அவரது உடல்நிலை காரணமாகப் பல வாரங்கள் மருத்துவமனையிலேயே அவர் கழிக்க நேரிட்டது." , year:2023, parties:["unknown"], newsQuery:"கைதின்போது நெஞ்சுவலி: மருத்துவமனையில் செந்தில் பாலாஜி அனுமதி 2023"},
  { id:91, season:"பருவம் 09", seasonNum:9, date:"ஆகஸ்ட் 7, 2023", title:"செந்தில் பாலாஜி கைதை உறுதி செய்த உச்சநீதிமன்றம்", filter:"verdict", tags:[["தீர்ப்பு","red"],["உச்சநீதிமன்றம்","gray"],["ED காவல்","gray"]], desc:"செந்தில் பாலாஜியின் கைதும் அவரை அமலாக்கத்துறை காவலில் எடுத்து விசாரிக்க முற்பட்டதும் சட்டவிரோதக் காவல் எனக் கூறி அவரது மனைவி மேகலா சென்னை உயர்நீதிமன்றத்தில் ஆட்கொணர்வு மனு (Habeas Corpus) தாக்கல் செய்தார். உயர்நீதிமன்ற நீதிபதிகளின் மாறுபட்ட தீர்ப்பைத் தொடர்ந்து இந்த மிக முக்கிய வழக்கு இந்திய உச்சநீதிமன்றத்திற்கு மேல்முறையீட்டிற்குச் சென்றது. ஆகஸ்ட் 7 அன்று இறுதித் தீர்ப்பளித்த உச்சநீதிமன்றம் அமலாக்கத்துறைக்குக் கைது செய்யும் அதிகாரம் உள்ளது என்றும் செந்தில் பாலாஜியின் கைது முற்றிலும் செல்லும் என்றும் அதிரடியாகத் தீர்ப்பளித்தது. மேலும் அவரை 5 நாட்கள் காவலில் எடுத்து விசாரிக்க அமலாக்கத்துறைக்கு உச்சநீதிமன்றம் முழுமையான பச்சைக்கொடி காட்டியது. இந்தத் தீர்ப்பின் மூலம் செந்தில் பாலாஜியின் அனைத்து சட்டப்பூர்வப் புகலிடங்களும் அடைக்கப்பட்டு அவர் சென்னை புழல் மத்தியச் சிறைக்குக் கொண்டு செல்லப்பட்டார்." , year:2023, parties:["unknown"], newsQuery:"செந்தில் பாலாஜி கைதை உறுதி செய்த உச்சநீதிமன்றம் 2023"},
  { id:92, season:"பருவம் 09", seasonNum:9, date:"செப்டம்பர் 25, 2023", title:"பாஜக தலைமையிலான NDA கூட்டணியில் இருந்து அதிமுக அதிகாரப்பூர்வ வெளியேற்றம்", filter:"alliance", tags:[["கூட்டணி","red"],["அதிமுக-பாஜக முறிவு","gray"],["அண்ணாமலை","gray"]], desc:"தமிழக பாஜக தலைவராகப் பொறுப்பேற்ற அண்ணாமலை ஆளும் திமுக-வை மட்டுமன்றி தங்களது கூட்டணிக் கட்சியான அதிமுக-வையும் அதன் மாண்புகளையும் தொடர்ந்து பொதுவெளியில் விமர்சித்து வந்தார். குறிப்பாக பேரறிஞர் அண்ணா மற்றும் மறைந்த முதலமைச்சர் ஜெயலலிதா ஆகியோரைப் பற்றி அண்ணாமலை பேசிய விமர்சனங்கள் அதிமுக தொண்டர்களிடையே கொந்தளிப்பை ஏற்படுத்தின. அண்ணாமலையை மாற்ற வேண்டும் என்ற அதிமுக-வின் கோரிக்கையை டெல்லி பாஜக தலைமை பெரிய அளவில் கண்டுகொள்ளாமல் நிராகரித்தது. இதனால் அதிருப்தியடைந்த பொதுச்செயலாளர் எடப்பாடி பழனிசாமி செப்டம்பர் 25 அன்று தலைமைக் கழகத்தில் அவசரமாகக் கூடி பாஜக தலைமையிலான தேசிய ஜனநாயகக் கூட்டணியில் (NDA) இருந்து அதிமுக அதிகாரப்பூர்வமாக வெளியேறுவதாகத் தீர்மானம் நிறைவேற்றினார். ராயப்பேட்டை அலுவலகத்தில் தொண்டர்கள் பட்டாசு வெடித்துக் கொண்டாடிய இந்த முடிவு தமிழகத்தில் பாஜக - அதிமுக உறவுக்கு நிரந்தர முற்றுப்புள்ளி வைத்தது." , year:2023, parties:["bjp", "dmk", "aiadmk"], newsQuery:"பாஜக தலைமையிலான NDA கூட்டணியில் இருந்து அதிமுக அதிகாரப்பூர்வ வெளியேற்றம் 2023"},
  { id:93, season:"பருவம் 09", seasonNum:9, date:"அக்டோபர் 12, 2023", title:"லாட்டரி அதிபர் மார்ட்டின் கார்ப்பரேட் இடங்களில் மீண்டும் மெகா ஐடி ரெய்டு", filter:"raid", tags:[["ரெய்டு","red"],["மார்ட்டின் குரூப்","gray"],["வருமான வரித்துறை","gray"]], desc:"கடந்த 2019-ல் நடந்த சோதனைகளின் தொடர்ச்சியாக லாட்டரி அதிபர் சாண்டியாகோ மார்ட்டின் வெளிமாநில லாட்டரி விற்பனை மூலம் வரும் கறுப்புப் பணத்தை ரியல் எஸ்டேட்டில் முதலீடு செய்வதாக மீண்டும் புகார்கள் எழுந்தன. கோயம்புத்தூரில் உள்ள மார்ட்டினின் பிரம்மாண்ட இல்லம் அவரது கார்ப்பரேட் அலுவலகம் மற்றும் மார்ட்டின் ஹோமியோபதி மருத்துவக் கல்லூரி உட்பட 4 முக்கிய இடங்களில் ஐடி துறை மீண்டும் புகுந்தது. இந்த முறை முற்றிலும் டிஜிட்டல் பரிவர்த்தனைகள் மற்றும் வெளிநாடுகளுக்குக் கடத்தப்பட்ட நிதிகளின் ஆதாரங்களைத் தேடியே இந்தச் சோதனை நடத்தப்பட்டது. சோதனையின் முடிவில் பல கோடி ரூபாய் மதிப்பிலான சொத்துக்களை முடக்குவதற்கான முதற்கட்ட உத்தரவுகளை வருமான வரித்துறை பிறப்பித்தது. தமிழகத்தின் முக்கிய அரசியல் சக்திகளுக்குத் திரைமறைவில் நிதி வழங்கி வந்த மார்ட்டின் மீதான இந்த ரெய்டு வரப்போகும் நாடாளுமன்றத் தேர்தலுக்கான டெல்லியின் பொருளாதார முடக்க வியூகமாகவே பார்க்கப்பட்டது." , year:2023, parties:["it_dept"], newsQuery:"லாட்டரி அதிபர் மார்ட்டின் கார்ப்பரேட் இடங்களில் மீண்டும் மெகா ஐடி ரெய்டு 2023"},
  { id:94, season:"பருவம் 10", seasonNum:10, date:"பிப்ரவரி 2, 2024", title:"நடிகர் விஜய் 'தமிழக வெற்றிக் கழகம்' (TVK) கட்சியைத் தொடங்கினார்", filter:"alliance", tags:[["கட்சி","red"],["விஜய்","gray"],["தவெக","gray"]], desc:"கடந்த 15 ஆண்டுகாலமாகத் தனது 'விஜய் மக்கள் இயக்கம்' மூலம் அடிமட்டத்தில் நற்பணிகளைச் செய்து வந்த நடிகர் விஜய் தனது நீண்டகால அரசியல் கனவை அதிகாரப்பூர்வமாக உலகிற்கு அறிவித்தார். 'தமிழக வெற்றிக் கழகம்' (TVK) என்ற தனது அரசியல் கட்சியின் பெயரை அதிகாரப்பூர்வமாக அறிவித்து கைப்பட கையெழுத்திட்ட 3 பக்க கொள்கை அறிக்கையை வெளியிட்டார். '2024 நாடாளுமன்றத் தேர்தல் நமது இலக்கல்ல 2026 சட்டமன்றத் தேர்தலே நமது இலக்கு' என்று அறிவித்து அதுவரை தான் ஒப்புக்கொண்டுள்ள படங்களை முடித்துவிட்டு முழுநேர அரசியலில் ஈடுபடப்போவதாகப் பிரகடனம் செய்தார். கட்சியின் தொடக்க நாளிலிருந்தே அவரது நம்பிக்கைக்குரிய தளபதியாக 'புஸ்ஸி' ஆனந்த் மற்றும் கட்சியின் சட்ட விவகாரங்களைக் கவனிக்க வழக்கறிஞர் பி. வெங்கடரமணன் ஆகியோர் விஜய்யுடன் பயணித்தனர். 59 ஆண்டுகால திராவிடக் கட்சிகளின் ஆதிக்கத்திற்கு மாற்றாக ஒரு புதிய மாற்றுச் சக்தியாக விஜய் களம் புகுந்த இந்த நாள் தமிழக அரசியல் வரலாற்றின் புதிய சகாப்தத்தின் புள்ளி." , year:2024, parties:["tvk"], newsQuery:"நடிகர் விஜய் 'தமிழக வெற்றிக் கழகம்' (TVK) கட்சியைத் தொடங்கினார் 2024"},
  { id:95, season:"பருவம் 10", seasonNum:10, date:"ஜூன் 4, 2024", title:"2024 மக்களவைத் தேர்தல்: திமுக கூட்டணி 40/40 வெற்றி", filter:"verdict", tags:[["வெற்றி","red"],["இந்தியா கூட்டணி","gray"],["திமுக 40/40","gray"]], desc:"கலைஞர் கருணாநிதி மற்றும் ஜெயலலிதா இல்லாத 2024 நாடாளுமன்றத் தேர்தலின் வாக்கு எண்ணிக்கை முடிவுகள் ஜூன் 4 அன்று வெளியாகின. முதலமைச்சர் மு.க. ஸ்டாலின் தலைமையிலான 'இந்தியா' (INDIA) கூட்டணி தமிழகத்தின் 39 தொகுதிகள் மற்றும் புதுச்சேரி உட்பட அனைத்து 40 இடங்களையும் வென்று வரலாற்றுச் சாதனை படைத்தது. தனித்து நின்ற அதிமுக கொங்கு மண்டலத்திலும் சரிவைச் சந்தித்து அனைத்து இடங்களிலும் தோற்றது; அண்ணாமலை தலைமையிலான பாஜக கூட்டணியும் ஒரு இடத்தைக் கூட வெல்ல முடியாமல் படுதோல்வி அடைந்தது. மு.க.ஸ்டாலினின் வியூகங்களுக்கும் அவரது தேர்தல் பிரச்சாரங்களுக்கும் கிடைத்த இந்த 100% வெற்றி மத்தியில் மோடி அரசு அமைந்தாலும் தமிழகத்தில் திமுக-வின் கோட்டையை அசைக்க முடியாது என்பதை நிரூபித்தது. திராவிடக் கட்சிகளுக்கு மாற்றாகத் தன்னை அடையாளப்படுத்த நினைத்த பாஜக மற்றும் அதிமுக ஆகிய இரு கட்சிகளுக்கும் இந்தத் தீர்ப்பு மிகப்பெரிய அரசியல் பின்னடைவாக அமைந்தது." , year:2024, parties:["bjp", "dmk", "aiadmk"], newsQuery:"2024 மக்களவைத் தேர்தல்: திமுக கூட்டணி 40/40 வெற்றி 2024"},
  { id:96, season:"பருவம் 10", seasonNum:10, date:"ஜூன் 19, 2024", title:"கள்ளக்குறிச்சி விஷச்சாராய விவகாரம்: 60-க்கும் மேற்பட்டோர் பலி", filter:"crisis", tags:[["நெருக்கடி","red"],["கள்ளக்குறிச்சி","gray"],["விஷச்சாராயம்","gray"]], desc:"நாடாளுமன்றத் தேர்தல் வெற்றிக் கொண்டாட்டத்தில் இருந்த திமுக அரசுக்கு கள்ளக்குறிச்சி மாவட்டம் கருணாபுரத்தில் ஒரு மாபெரும் சோகம் இடியாக இறங்கியது. சட்டவிரோதமாக விற்கப்பட்ட மெத்தனால் கலந்த விஷச்சாராயத்தைக் குடித்த கூலித் தொழிலாளர்கள் பெண்கள் என அடுத்தடுத்து நூற்றுக்கணக்கானோர் வாந்தி, மயக்கத்துடன் மருத்துவமனையில் அனுமதிக்கப்பட்டனர். அடுத்த சில நாட்களிலேயே சிகிச்சை பலனின்றி 9 பெண்கள் உட்பட 60-க்கும் மேற்பட்ட ஏழை எளிய மக்கள் பரிதாபமாக ரத்த வாந்தி எடுத்துப் பலியாயினர். உள்ளூர் காவல்துறையின் அலட்சியமே இந்த மாபெரும் உயிர் இழப்புக்குக் காரணம் எனக் கூறி ஆளுங்கட்சிக்கு எதிராக மாநிலம் முழுவதும் மாபெரும் கொந்தளிப்பும் போராட்டங்களும் வெடித்தன. இந்தச் சோகம் உளவுத்துறையின் மிகப்பெரிய தோல்வியாகப் பார்க்கப்பட்டதுடன் முதல்வர் மு.க.ஸ்டாலின் அரசுக்கு நிர்வாக ரீதியாக மிகப்பெரிய பின்னடைவையும் களங்கத்தையும் ஏற்படுத்தியது." , year:2024, parties:["dmk"], newsQuery:"கள்ளக்குறிச்சி விஷச்சாராய விவகாரம்: 60-க்கும் மேற்பட்டோர் பலி 2024"},
  { id:97, season:"பருவம் 10", seasonNum:10, date:"செப்டம்பர் 8, 2024", title:"தவெக கட்சி ECI-ல் அதிகாரப்பூர்வமாகப் பதிவு", filter:"alliance", tags:[["கட்சி","red"],["தேர்தல் ஆணையம்","gray"],["தவெக பதிவு","gray"]], desc:"கட்சித் தொடங்கப்பட்ட பிறகு அதன் சட்டபூர்வ அங்கீகாரத்தைப் பெறுவதற்காகப் புதுடெல்லியில் உள்ள இந்தியத் தேர்தல் ஆணையத்தில் தவெக தரப்பில் மனுத்தாக்கல் செய்யப்பட்டிருந்தது. கட்சியின் சட்டதிட்டங்கள் கொள்கைகள் மற்றும் நிர்வாகிகளின் விபரங்களை ஆணையம் பல கட்டங்களாகத் தீவிரப் பரிசீலனைக்கு உட்படுத்தியது. அனைத்து சட்டபூர்வ சரிபார்ப்புகளுக்குப் பிறகு செப்டம்பர் 8 அன்று இந்தியத் தேர்தல் ஆணையம் (ECI) 'தமிழக வெற்றிக் கழகத்தை' ஒரு பதிவு செய்யப்பட்ட அரசியல் கட்சியாகத் தனது பட்டியலில் இணைத்துக் கொண்டது. இதற்கான அதிகாரப்பூர்வ அங்கீகாரக் கடிதத்தைத் தேர்தல் ஆணையம் தவெக தலைமைக் கழகத்திற்கு அனுப்பி வைத்தது. இந்தச் சட்டப்பூர்வ அங்கீகாரம் விஜய் தேர்தலை எதிர்கொள்வதற்கும் கட்சியின் அடுத்தகட்ட மாநாடுகளை நடத்துவதற்கும் மிக முக்கியமான சட்டபூர்வ பலமாக அமைந்தது." , year:2024, parties:["tvk"], newsQuery:"தவெக கட்சி ECI-ல் அதிகாரப்பூர்வமாகப் பதிவு 2024"},
  { id:98, season:"பருவம் 10", seasonNum:10, date:"செப்டம்பர் 26, 2024", title:"471 நாட்கள் சிறைவாசத்திற்குப் பின் செந்தில் பாலாஜிக்கு உச்சநீதிமன்றம் ஜாமீன்", filter:"verdict", tags:[["தீர்ப்பு","red"],["செந்தில் பாலாஜி","gray"],["ஜாமீன்","gray"]], desc:"கடந்த 2023 ஜூன் மாதம் அமலாக்கத்துறையால் கைது செய்யப்பட்டு சென்னை புழல் சிறையில் அடைக்கப்பட்டிருந்த முன்னாள் அமைச்சர் செந்தில் பாலாஜியின் ஜாமீன் மனுக்கள் பலமுறை தள்ளுபடி செய்யப்பட்டன. நீண்ட சட்டப் போராட்டத்திற்குப் பிறகு அவரது ஜாமீன் மனு மீதான இறுதி விசாரணை இந்திய உச்சநீதிமன்றத்தில் நீதிபதிகள் அபய் எஸ். ஓகா மற்றும் அகஸ்டின் ஜார்ஜ் மாசி அமர்வு முன்பு வந்தது. 'ஒருவரை விசாரணை என்ற பெயரில் காலவரையின்றிச் சிறையில் அடைத்து வைக்க முடியாது; அது அவரது அடிப்படை உரிமையைப் பறிப்பதாகும்' எனக் கூறி செந்தில் பாலாஜிக்கு உச்சநீதிமன்றம் நிபந்தனை ஜாமீன் வழங்கியது. சரியாக 471 நாட்கள் சிறைவாசத்திற்குப் பின் புழல் சிறையிலிருந்து வெளியே வந்த செந்தில் பாலாஜிக்கு திமுக தொண்டர்கள் உற்சாகமான மற்றும் பிரம்மாண்டமான வரவேற்பை அளித்தனர். இவ்வளவு நீண்ட காலம் சிறையிலிருந்தும் அவரது அரசியல் செல்வாக்கைக் கொங்கு மண்டலத்தில் தக்கவைத்துக் கொள்ள திமுக தலைமை அவருக்கு முழு ஆதரவை வழங்கியது." , year:2024, parties:["dmk"], newsQuery:"471 நாட்கள் சிறைவாசத்திற்குப் பின் செந்தில் பாலாஜிக்கு உச்சநீதிமன்றம் ஜாமீன் 2024"},
  { id:99, season:"பருவம் 10", seasonNum:10, date:"செப்டம்பர் 28, 2024", title:"உதயநிதி துணை முதல்வர் & செந்தில் பாலாஜி மீண்டும் மின்சாரத்துறை அமைச்சர்", filter:"oath", tags:[["பதவியேற்பு","red"],["உதயநிதி ஸ்டாலின்","gray"],["துணை முதல்வர்","gray"]], desc:"செந்தில் பாலாஜி ஜாமீனில் வெளிவந்த அடுத்த 48 மணி நேரத்திற்குள் தமிழக அமைச்சரவையில் ஒரு மாபெரும் அதிரடி மாற்றத்தை முதலமைச்சர் மு.க.ஸ்டாலின் நிகழ்த்தினார். இளைஞர் நலன் மற்றும் விளையாட்டு மேம்பாட்டுத் துறை அமைச்சராக இருந்த உதயநிதி ஸ்டாலின் தமிழ்நாட்டின் புதிய 'துணை முதலமைச்சராக' அதிகாரப்பூர்வமாகப் பொறுப்பேற்றார். அதே மேடையில் சிறையிலிருந்து வெளிவந்த செந்தில் பாலாஜிக்கு மீண்டும் அவர் ஏற்கனவே வகித்த மின்சாரம் மற்றும் மதுவிலக்கு ஆயத்தீர்வைத் துறை அமைச்சராகப் பதவிப் பிரமாணம் செய்து வைக்கப்பட்டது. திமுக-வின் அடுத்த வாரிசுத் தலைமையாக உதயநிதி ஸ்டாலின் அதிகாரப்பூர்வமாக நிலைநிறுத்தப்பட்ட வரலாற்று நாளாக இந்தச் செப்டம்பர் 28 அமைந்தது. ஊழல் வழக்கில் சிறை சென்று வந்த செந்தில் பாலாஜிக்கு மீண்டும் உடனடியாக அமைச்சர் பதவி வழங்கப்பட்டது எதிர்க்கட்சிகளால் கடுமையான விமர்சனங்களுக்கு உள்ளாக்கப்பட்டது." , year:2024, parties:["dmk"], newsQuery:"உதயநிதி துணை முதல்வர் & செந்தில் பாலாஜி மீண்டும் மின்சாரத்துறை அமைச்சர் 2024"},
  { id:100, season:"பருவம் 10", seasonNum:10, date:"அக்டோபர் 27, 2024", title:"விக்கிரவாண்டியில் தவெக-வின் முதல் மாநில மாநாடு", filter:"alliance", tags:[["மாநாடு","red"],["விக்கிரவாண்டி","gray"],["விஜய் உரை","gray"]], desc:"தமிழக வெற்றிக் கழகத்தின் முதல் மாநில மாநாடு விழுப்புரம் மாவட்டம் விக்கிரவாண்டி சாலைகிராமத்தில் வரலாறு காணாத மக்கள் கடலுக்கு இடையே பிரம்மாண்டமாக நடைபெற்றது. மாநாட்டுத் திடலில் அமைக்கப்பட்டிருந்த 100 அடி உயரக் கொடிக்கம்பத்தில் கட்சியின் தலைவர் விஜய் ஏறி தவெக-வின் மூன்று வண்ணக் கொடியை முறைப்படி ஏற்றி வைத்தார். மாநாட்டு மேடையில் திரண்டிருந்த லட்சக்கணக்கான தொண்டர்கள் மத்தியில் சுமார் 45 நிமிடங்கள் அனல் பறக்கும் தனது முதல் அரசியல் உரையை விஜய் நிகழ்த்தினார். 'நமது அடிப்படைக் கொள்கை தந்தை பெரியாரின் சமூக நீதி மற்றும் அண்ணலின் பகுத்தறிவு' என்று அறிவித்த அவர் ஆளும் திமுக-வை 'குடும்ப அரசியல்' என்றும் பாஜக-வை 'பிளவுவாத அரசியல்' என்றும் சாடினார். சினிமா கவர்ச்சியையும் தாண்டி விஜய்யின் இந்த அரசியல் உரை மற்றும் மாநாட்டின் பிரம்மாண்டம் 2026-ல் தவெக ஒரு தவிர்க்க முடியாத சக்தியாக உருவெடுக்கும் என்பதை திராவிடக் கட்சிகளுக்கு ஆணித்தரமாக உணர்த்தியது." , year:2024, parties:["bjp", "dmk", "tvk"], newsQuery:"விக்கிரவாண்டியில் தவெக-வின் முதல் மாநில மாநாடு 2024"},
  { id:101, season:"பருவம் 10", seasonNum:10, date:"நவம்பர் 14, 2024", title:"மார்ட்டின் & ஆதவ் அர்ஜுனா இடங்களில் அமலாக்கத்துறை (ED) மெகா ரெய்டு தொடக்கம்", filter:"raid", tags:[["ரெய்டு","red"],["மார்ட்டின்","gray"],["ஆதவ் அர்ஜுனா","gray"]], desc:"லாட்டரி அதிபர் சாண்டியாகோ மார்ட்டின் மீதான பணமோசடி வழக்கின் (PMLA) தொடர்ச்சியாக அவரது குடும்பத்தின் நிதிப் பரிவர்த்தனைகளை அமலாக்கத்துறை உன்னிப்பாகக் கவனித்து வந்தது. மார்ட்டினின் மகனான சார்லஸ் டைசன் மற்றும் அவரது மருமகனும் விசிக-வின் மூத்த நிர்வாகியுமான ஆதவ் அர்ஜுனாவின் சென்னை, கோவை இல்லங்களில் ED அதிகாரிகள் அதிரடியாக நுழைந்தனர். இந்தியா முழுவதும் மொத்தம் 22 இடங்களில் ஒரே நேரத்தில் துப்பாக்கி ஏந்திய மத்தியப் பாதுகாப்புப் படையினரின் (CRPF) பலத்த காவலுடன் இந்த மெகா சோதனை திட்டமிடப்பட்டது. விசிக-வில் இருந்து கொண்டு அரசியல் வியூகங்களை வகுத்து வந்த ஆதவ் அர்ஜுனாவை முடக்குவதே இந்த ரெய்டின் முக்கிய நோக்கம் என அரசியல் வட்டாரத்தில் பேசப்பட்டது. தேர்தலுக்கு ஒரு வருடமே இருந்த நிலையில் நடந்த இந்த ரெய்டு மார்ட்டின் குடும்பத்தின் ஒட்டுமொத்தப் பொருளாதார வளையத்தையும் டெல்லி தனது முழுமையான கட்டுப்பாட்டுக்குள் கொண்டு வர எடுத்த இறுதிப் பாய்ச்சலாகும்." , year:2024, parties:["unknown"], newsQuery:"மார்ட்டின் & ஆதவ் அர்ஜுனா இடங்களில் அமலாக்கத்துறை (ED) மெகா ரெய்டு தொடக்கம் 2024"},
  { id:102, season:"பருவம் 10", seasonNum:10, date:"நவம்பர் 16, 2024", title:"3 நாள் ED ரெய்டு நிறைவு: 12.41 கோடி ரொக்கம் முடக்கப்பட்டது", filter:"raid", tags:[["ரெய்டு","red"],["₹12.41 கோடி","gray"],["அமலாக்கத்துறை","gray"]], desc:"மார்ட்டின், சார்லஸ் மற்றும் ஆதவ் அர்ஜுனா ஆகியோரது இடங்களில் தொடர்ந்து 3 நாட்களாகப் பகல் இரவு பாராமல் அமலாக்கத்துறை அதிகாரிகள் தங்களது தீவிரச் சோதனையை நடத்தினர். சோதனையின் இறுதி நாளில் மார்ட்டின் குழும நிறுவனங்களின் ரகசிய அறைகளில் இருந்து கணக்கில் வராத ₹12.41 கோடி ரொக்கப் பணத்தை அதிகாரிகள் அதிகாரப்பூர்வமாகக் கைப்பற்றி முடக்கினர். மேலும் டிஜிட்டல் ஆவணங்கள், கிரிப்டோ கரன்சி முதலீடுகள் மற்றும் பல கோடி ரூபாய் மதிப்பிலான போலி நிறுவனங்களின் பங்குகள் பறிமுதல் செய்யப்பட்டன. இதே நவம்பர் மாதத்தில் பல வருடங்களாகத் தொய்வடைந்திருந்த கொடநாடு கொலை வழக்கை சிபிசிஐடி-யிடமிருந்து சிபிஐ (CBI) விசாரணைக்கு மாற்றி மத்திய அரசு உத்தரவிட்டது. இந்த ரெய்டுகளின் நெருக்கடி தாளாமல் அடுத்த சில வாரங்களிலேயே (டிசம்பரில்) ஆதவ் அர்ஜுனா விடுதலைச் சிறுத்தைகள் கட்சியில் (VCK) இருந்து அதிகாரப்பூர்வமாக விலகுவதாக அறிவித்தார்." , year:2024, parties:["cbi"], newsQuery:"3 நாள் ED ரெய்டு நிறைவு: 12.41 கோடி ரொக்கம் முடக்கப்பட்டது 2024"},
  { id:103, season:"பருவம் 10", seasonNum:10, date:"டிசம்பர் 2024", title:"விடுதலைச் சிறுத்தைகள் கட்சியில் (VCK) இருந்து ஆதவ் அர்ஜுனா அதிகாரப்பூர்வ விலகல்", filter:"alliance", tags:[["கட்சி","red"],["ஆதவ் அர்ஜுனா","gray"],["விசிக விலகல்","gray"]], desc:"அமலாக்கத்துறையின் மெகா ரெய்டுகள் மற்றும் திமுக கூட்டணியில் விசிக-வுக்குள் ஏற்பட்ட சில உள்கட்சி முரண்பாடுகளால் ஆதவ் அர்ஜுனா கடுமையான அரசியல் நெருக்கடிக்குள்ளானார். விடுதலைச் சிறுத்தைகள் கட்சியின் (VCK) துணைப் பொதுச்செயலாளராக இருந்த அவர் அக்கட்சியின் தலைமை மற்றும் கொள்கைகளுடன் தனக்கு முரண்பாடு இருப்பதாகக் கூறினார். டிசம்பர் இறுதி வாரத்தில் விசிக-வின் அனைத்துப் பொறுப்புகள் மற்றும் அடிப்படை உறுப்பினரிலிருந்து தான் அதிகாரப்பூர்வமாக விலகுவதாகத் தொல். திருமாவளவனுக்குக் கடிதம் அனுப்பினார். திராவிடக் கட்சிகளின் கூட்டணியில் இருந்தால் தங்களது தொழில் மற்றும் அரசியல் எதிர்காலத்திற்குப் பாதுகாப்பு இல்லை என்பதை அவர் உணர்ந்ததன் விளைவாக இந்த விலகல் பார்க்கப்பட்டது. (விசிக-விலிருந்து விலகிய இந்தத் தொழிலதிபர் அடுத்த சில நாட்களிலேயே தவெக-வில் இணைந்து 'தேர்தல் பிரச்சார வியூகப் பொதுச்செயலாளர்' என்ற மாபெரும் பொறுப்பை ஏற்கப் போகிறார் என்பதற்கான அஸ்திவாரம் இதுவே ஆகும்)." , year:2024, parties:["dmk", "tvk"], newsQuery:"விடுதலைச் சிறுத்தைகள் கட்சியில் (VCK) இருந்து ஆதவ் அர்ஜுனா அதிகாரப்பூர்வ விலகல் 2024"},
  { id:104, season:"பருவம் 10", seasonNum:10, date:"ஜனவரி 31, 2025", title:"ஆதவ் அர்ஜுனா & சி.டி.ஆர். நிர்மல் குமார் தவெக-வில் இணைவு", filter:"alliance", tags:[["கட்சி","red"],["ஆதவ் அர்ஜுனா","gray"],["நிர்மல் குமார்","gray"]], desc:"2026 சட்டமன்றத் தேர்தலை எதிர்கொள்ளத் தனக்குத் தொழில் பலமும் தொழில்நுட்பப் பலமும் தேவை என்பதை உணர்ந்த தவெக தலைவர் விஜய் ஒரு மாபெரும் அரசியல் சேர்க்கையை நிகழ்த்தினார். விசிக முன்னாள் துணைப் பொதுச்செயலாளர் ஆதவ் அர்ஜுனா மற்றும் பாஜக/அதிமுக-வின் முன்னாள் தகவல் தொழில்நுட்பப் பிரிவு (IT Wing) நிர்வாகி சி.டி.ஆர். நிர்மல் குமார் ஆகிய இருவரும் தவெக-வில் அதிகாரப்பூர்வமாக இணைந்தனர். சென்னை தவெக தலைமைக் கழகத்தில் நடந்த விழாவில் விஜய் இருவருக்கும் கட்சியின் துண்டுகளை அணிவித்து வரவேற்று முக்கியப் பதவிகளை வழங்கினார். ஆதவ் அர்ஜுனாவுக்குக் கட்சியின் மிக உயரிய 'தேர்தல் பிரச்சார வியூகப் பொதுச்செயலாளர்' பதவியும் நிர்மல்குமாருக்கு 'ஐடி விங் துணைப் பொதுச்செயலாளர்' பதவியும் வழங்கப்பட்டது. பல்துறை நிபுணர்கள் தவெக-வை நோக்கி வரத் தொடங்கிய இந்த நாள் திராவிடக் கட்சிகளின் தேர்தல் வியூகங்களை உடைப்பதற்கான தவெக-வின் முதல் அதிகாரப்பூர்வக் கட்டமைப்புப் புள்ளியாக மாறியது." , year:2025, parties:["bjp", "dmk", "aiadmk", "tvk"], newsQuery:"ஆதவ் அர்ஜுனா & சி.டி.ஆர். நிர்மல் குமார் தவெக-வில் இணைவு 2025"},
  { id:105, season:"பருவம் 10", seasonNum:10, date:"பிப்ரவரி 13, 2025", title:"தவெக 1.5 கோடி உறுப்பினர் சேர்க்கை இலக்குடன் மாபெரும் முகாம் தொடக்கம்", filter:"alliance", tags:[["கட்சி","red"],["உறுப்பினர் சேர்க்கை","gray"],["தவெக","gray"]], desc:"புதிய நிர்வாகிகள் நியமிக்கப்பட்ட கையோடு தவெக-வின் அடிமட்ட வாக்கு வங்கியை வலுப்படுத்த ஒரு மாபெரும் டிஜிட்டல் உறுப்பினர் சேர்க்கை இயக்கம் திட்டமிடப்பட்டது. பிப்ரவரி 13 அன்று சென்னை தவெக அலுவலகத்தில் 1.5 கோடி உறுப்பினர்களைக் கட்சியில் சேர்க்கும் இலக்குடன் பிரத்யேக மொபைல் ஆப் மற்றும் வாட்ஸ்அப் போட் (Bot) சேவையை விஜய் தொடங்கி வைத்தார். 'ஒவ்வொரு பூத்திலும் குறைந்தபட்சம் 500 உறுப்பினர்களையாவது சேர்க்க வேண்டும்' என்று மாவட்ட நிர்வாகிகளுக்குத் தலைவர் விஜய் கடுமையான உத்தரவுகளைப் பிறப்பித்தார். இந்த டிஜிட்டல் முகாம் தொடங்கிய சில நாட்களிலேயே லட்சக்கணக்கான இளைஞர்களும் பெண் வாக்காளர்களும் தவெக-வில் தங்களை உறுப்பினர்களாக இணைத்துக் கொண்டனர். இந்த மாபெரும் உறுப்பினர் சேர்க்கை வேகம் பாரம்பரிய திராவிடக் கட்சிகளின் உறுப்பினர் கட்டமைப்பிற்கே மிகப்பெரிய சவாலாக உருவெடுத்தது." , year:2025, parties:["tvk"], newsQuery:"தவெக 1.5 கோடி உறுப்பினர் சேர்க்கை இலக்குடன் மாபெரும் முகாம் தொடக்கம் 2025"},
  { id:106, season:"பருவம் 10", seasonNum:10, date:"மார்ச் 6, 2025", title:"கரூரில் செந்தில் பாலாஜி ஆதரவாளர்கள் 25 இடங்களில் அமலாக்கத்துறை (ED) மீண்டும் ரெய்டு", filter:"raid", tags:[["ரெய்டு","red"],["கரூர","gray"],["ED சோதனை","gray"]], desc:"ஜாமீனில் வெளிவந்து மீண்டும் அமைச்சராகப் பொறுப்பேற்ற செந்தில் பாலாஜி கரூரில் தங்களது தேர்தல் பணிகளைத் தீவிரமாகத் தொடங்கியிருந்த வேளையில் அமலாக்கத்துறை மீண்டும் பாய்ந்தது. மார்ச் 6 அதிகாலை முதல் கரூரில் உள்ள செந்தில் பாலாஜியின் முக்கிய ஆதரவாளர்கள் அரசு ஒப்பந்ததாரர்கள் மற்றும் பினாமிகளின் வீடுகள் உட்பட 25 இடங்களில் ED அதிகாரிகள் அதிரடியாக நுழைந்தனர். கடந்த முறை தாக்குதல் நடந்ததை மனதில் வைத்து இந்த முறை நூற்றுக்கணக்கான துப்பாக்கி ஏந்திய மத்தியப் பாதுகாப்புப் படையினரின் (CRPF) அதிரடிப் பாதுகாப்புடன் அதிகாரிகள் சோதனையை நடத்தினர். இந்தச் சோதனையானது முற்றிலும் கரூரின் நிதி ஆதாரங்களை வேரறுப்பதற்கும் தேர்தல் நிதிகள் பதுக்கப்பட்டுள்ள இடங்களைக் கண்டறிவதற்கும் திட்டமிடப்பட்டது. செந்தில் பாலாஜி மீண்டும் அமைச்சரானாலும் டெல்லியின் கழுகுப் பார்வை அவரை விட்டு இன்னும் அகலவில்லை என்பதை இந்த 25 இடங்களின் ரெய்டு ஆணித்தரமாக உணர்த்தியது." , year:2025, parties:["unknown"], newsQuery:"கரூரில் செந்தில் பாலாஜி ஆதரவாளர்கள் 25 இடங்களில் அமலாக்கத்துறை (ED) மீண்டும் ரெய்டு 2025"},
  { id:107, season:"பருவம் 10", seasonNum:10, date:"மார்ச் 13, 2025", title:"1000 கோடி டாஸ்மாக் முறைகேடு: ED பரபரப்பு குற்றச்சாட்டு", filter:"crisis", tags:[["நெருக்கடி","red"],["டாஸ்மாக் ஊழல்","gray"],["ED குற்றச்சாட்டு","gray"]], desc:"கரூர் சோதனைகளில் சிக்கிய டிஜிட்டல் ஆதாரங்கள் மற்றும் ரகசியக் கணக்குப் புத்தகங்களின் அடிப்படையில் அமலாக்கத்துறை டெல்லி தலைமையகம் ஒரு மாபெரும் குண்டை வீசியது. தமிழ்நாட்டின் டாஸ்மாக் (TASMAC) மதுபானக் கொள்முதலில் SNJ, Kals போன்ற முன்னணி மதுபான ஆலைகளுடன் இணைந்து சுமார் ₹1000 கோடிக்கும் மேல் முறைகேடுகள் மற்றும் கமிஷன் கைமாறியுள்ளதாக ED பகிரங்கமாகக் குற்றஞ்சாட்டியது. இந்த முறைகேட்டுப் பணமானது போலி நிறுவனங்கள் மூலம் வெளிநாடுகளுக்கு மடைமாற்றம் செய்யப்பட்டுள்ளதாக அமலாக்கத்துறை தனது செய்திக்குறிப்பில் குறிப்பிட்டது. இந்த ஊழல் புகார் ஆளும் திமுக அரசுக்கு மிகப்பெரிய அரசியல் நெருக்கடியையும் மக்கள் மத்தியில் கடும் அதிருப்தியையும் ஏற்படுத்தியது. (இருப்பினும் இந்த விவகாரத்தில் அடுத்த சில வாரங்களில் அதாவது மே 23 அன்று இந்திய உச்சநீதிமன்றம் அமலாக்கத்துறையின் விசாரணைக்கு இடைக்காலத் தடை விதித்து உத்தரவிட்டது குறிப்பிடத்தக்கது)." , year:2025, parties:["dmk"], newsQuery:"1000 கோடி டாஸ்மாக் முறைகேடு: ED பரபரப்பு குற்றச்சாட்டு 2025"},
  { id:108, season:"பருவம் 10", seasonNum:10, date:"மார்ச் 2025 (தொடர்ச்சி)", title:"2026 சட்டமன்றத் தேர்தலை நோக்கிய தவெக-வின் பூத் கமிட்டி வியூகங்கள்", filter:"alliance", tags:[["வியூகம்","red"],["பூத் கமிட்டி","gray"],["தவெக","gray"]], desc:"டாஸ்மாக் ஊழல் புகாரால் ஆளும் கட்சி பலவீனமடைந்த சூழலைத் தவெக தனது தேர்தல் பிரச்சாரத்திற்குச் சாதகமாகப் பயன்படுத்திக் கொள்ளத் திட்டமிட்டது. தேர்தல் பிரச்சார வியூகப் பொதுச்செயலாளர் ஆதவ் அர்ஜுனா தலைமையில் தமிழ்நாடு முழுவதும் உள்ள 68,000-க்கும் மேற்பட்ட வாக்குச் சாவடிகளுக்குப் (Polling Booths) புதிய பூத் கமிட்டிகள் அமைக்கும் பணி தீவிரப்படுத்தப்பட்டது. இளைஞர்கள் மற்றும் படித்த பட்டதாரிகளை பூத் ஏஜெண்டுகளாக நியமித்து அவர்களுக்கு நவீன டிஜிட்டல் பயிற்சி அளிக்க விஜய் உத்தரவிட்டார். திராவிடக் கட்சிகளின் பாரம்பரிய பூத் மேலாண்மை உத்திகளைத் தங்களது நவீன தொழில்நுட்ப வியூகங்கள் மூலம் உடைக்க தவெக முழுமையாகத் தயாரானது. 2026-ல் தமிழ்நாட்டின் ஆட்சிப் பீடத்தைக் கைப்பற்றுவதற்கான தவெக-வின் உண்மையான களப்பணிகள் அடிமட்டத்தில் முழு வீச்சில் வேரூன்றிய மிக முக்கியமான காலகட்டம் இதுவாகும்." , year:2025, parties:["tvk"], newsQuery:"2026 சட்டமன்றத் தேர்தலை நோக்கிய தவெக-வின் பூத் கமிட்டி வியூகங்கள் 2025"},
  { id:109, season:"பருவம் 11", seasonNum:11, date:"ஏப்ரல் 11, 2025", title:"2026 தேர்தலுக்காக அதிமுக - பாஜக (NDA) கூட்டணி மீண்டும் உதயம்", filter:"alliance", tags:[["கூட்டணி","red"],["அதிமுக-பாஜக","gray"],["NDA","gray"]], desc:"2026 சட்டமன்றத் தேர்தலை ஒட்டி தமிழ்நாட்டில் பலமடைந்து வரும் தவெக மற்றும் ஆளும் திமுக ஆகிய இரு முனைகளையும் எதிர்கொள்ளப் புதிய கூட்டணி உத்திகள் வகுக்கப்பட்டன. புதுடெல்லியில் மத்திய உள்துறை அமைச்சர் அமித் ஷா மற்றும் அதிமுக பொதுச்செயலாளர் எடப்பாடி பழனிசாமி முன்னிலையில் அதிமுக - பாஜக கூட்டணி மீண்டும் அதிகாரப்பூர்வமாக உருவானது. கடந்த 2023-ல் ஏற்பட்ட முறிவுக்குப் பின் திராவிட மற்றும் தேசிய வாக்கு வங்கிகளை ஒன்றிணைக்க இரு கட்சிகளின் தலைமைகளும் இந்த சமரசப் பாதையைத் தேர்ந்தெடுத்தன. இந்தத் திடீர் கூட்டணிக் கையெழுத்து ஆவணம் தமிழ்நாட்டின் தேர்தல் களத்தை ஒரு பலப்பரீட்சை களம் நோக்கி நகர்த்தியது. (இந்தக் கூட்டணி உருவான அதே வேளையில் ஏப்ரல் 27-28 தேதிகளில் தவெக பூத் ஏஜெண்டுகளுக்கான பிரம்மாண்ட பயிற்சி முகாம் கோவையில் வெற்றிகரமாக நடத்தப்பட்டது குறிப்பிடத்தக்கது)." , year:2025, parties:["bjp", "dmk", "aiadmk", "tvk"], newsQuery:"2026 தேர்தலுக்காக அதிமுக - பாஜக (NDA) கூட்டணி மீண்டும் உதயம் 2025"},
  { id:110, season:"பருவம் 11", seasonNum:11, date:"மே 22, 2025", title:"வருமான வரித்துறை கூடுதல் ஆணையர் பதவியை ராஜினாமா (VRS) செய்தார் டாக்டர் கே.ஜி. அருண்ராஜ்", filter:"alliance", tags:[["ராஜினாமா","red"],["கே.ஜி. அருண்ராஜ்","gray"],["VRS","gray"]], desc:"தமிழக அரசியலின் பல முக்கியப் புள்ளிகளின் நிழல் பொருளாதாரத்தை ரெய்டுகள் மூலம் வெளிக்கொண்டு வந்த அதிரடி ஐ.ஆர்.எஸ் (IRS) அதிகாரி டாக்டர் கே.ஜி. அருண்ராஜ் ஒரு முக்கிய முடிவை எடுத்தது. டெல்லி சிபிடிடி (CBDT) தலைமையகத்தில் கூடுதல் ஆணையராகப் பணியாற்றி வந்த அவர் தனது பதவியிலிருந்து விருப்ப ஓய்வு (VRS) பெறுவதற்கான கடிதத்தை மத்திய நிதி அமைச்சகத்திற்கு அனுப்பினார். அவரது இந்த அதிரடி ராஜினாமா முடிவு அவர் விரைவில் நேரடியாக அரசியல் களத்தில் இறங்கப் போகிறார் என்ற விவாதங்களை டெல்லி வட்டாரத்தில் கிளப்பியது. நிதி அமைச்சகம் அவரது விருப்ப ஓய்வை உடனடியாக ஏற்றுக்கொண்டதைத் தொடர்ந்து அவர் தனது அதிகாரப்பூர்வப் பொறுப்புகளில் இருந்து முழுமையாக விடுவிக்கப்பட்டார். (மறுநாளான மே 23 அன்று டாஸ்மாக் ₹1000 கோடி ஊழல் புகாரில் அமலாக்கத்துறையின் விசாரணைக்கு உச்சநீதிமன்றம் இடைக்காலத் தடை விதித்து உத்தரவிட்டதும் குறிப்பிடத்தக்கது)." , year:2025, parties:["it_dept"], newsQuery:"வருமான வரித்துறை கூடுதல் ஆணையர் பதவியை ராஜினாமா (VRS) செய்தார் டாக்டர் கே.ஜி. அருண்ராஜ் 2025"},
  { id:111, season:"பருவம் 11", seasonNum:11, date:"ஜூன் 9, 2025", title:"முன்னாள் ஐஆர்எஸ் அருண்ராஜ் & டாக்டர் மேரி வில்சன் தவெக-வில் அதிகாரப்பூர்வமாக இணைவு", filter:"alliance", tags:[["கட்சி","red"],["அருண்ராஜ்","gray"],["மேரி வில்சன்","gray"]], desc:"விருப்ப ஓய்வு பெற்ற முன்னாள் ஐ.ஆர்.எஸ் அதிகாரி டாக்டர் கே.ஜி. அருண்ராஜ் மற்றும் ஜேப்பியார் குழுமத்தைச் சேர்ந்த கல்வியாளர் டாக்டர் என். மேரி வில்சன் (மரிய வில்சன்) ஆகியோர் தவெக-வில் இணைந்தனர். சென்னை தவெக தலைமைக் கழகத்தில் நடந்த விழாவில் கட்சித் தலைவர் விஜய் இருவரையும் முறைப்படி வரவேற்று முக்கியப் பொறுப்புகளை வழங்குவதாக அறிவித்தார். டாக்டர் கே.ஜி. அருண்ராஜுக்குக் கட்சியின் மிக முக்கியப் பதவியான 'கொள்கை மற்றும் பரப்புரை பொதுச்செயலாளர்' பதவி வழங்கப்பட்டது. அரசு நிர்வாகத்தை நன்கு அறிந்த ஒரு உயர்மட்ட அதிகாரியும் கல்வி அதிபரும் தவெக-வில் இணைந்தது கட்சியின் கொள்கை மற்றும் பொருளாதாரக் கட்டமைப்பை பலமடையச் செய்தது. (இதன் தொடர்ச்சியாக ஆகஸ்ட் 21 அன்று மதுரையில் தவெக-வின் பிரம்மாண்ட 2-வது மாநாடு தென் தமிழகத்தை உலுக்கும் வகையில் நடத்தப்பட்டது)." , year:2025, parties:["tvk"], newsQuery:"முன்னாள் ஐஆர்எஸ் அருண்ராஜ் & டாக்டர் மேரி வில்சன் தவெக-வில் அதிகாரப்பூர்வமாக இணைவு 2025"},
  { id:112, season:"பருவம் 11", seasonNum:11, date:"செப்டம்பர் 8, 2025", title:"ஓரங்கட்டப்பட்ட கே.ஏ. செங்கோட்டையன் டெல்லியில் அமித் ஷாவுடன் ரகசியச் சந்திப்பு", filter:"crisis", tags:[["சந்திப்பு","red"],["செங்கோட்டையன்","gray"],["அமித் ஷா","gray"]], desc:"அதிமுக-வின் மூத்த தலைவரும் கொங்கு மண்டலத்தின் தூணாகவும் விளங்கிய கே.ஏ. செங்கோட்டையன் ஈபிஎஸ்-உடன் ஏற்பட்ட உட்கட்சிப் பூசல்களால் கட்சியின் முக்கியப் பொறுப்புகளில் இருந்து ஓரங்கட்டப்பட்டார். இதனால் அதிருப்தியடைந்த அவர் ரகசியமாகப் புதுடெல்லிக்குச் சென்று மத்திய உள்துறை அமைச்சர் அமித் ஷா மற்றும் நிதி அமைச்சர் நிர்மலா சீதாராமனைச் சந்தித்துப் பேசினார். இந்தச் சந்திப்பின் போது எடுக்கப்பட்ட புகைப்படங்கள் மற்றும் விபரங்கள் ஊடகங்களில் வெளியாகி அதிமுக மற்றும் தமிழக அரசியல் வட்டாரத்தில் மாபெரும் பூகம்பத்தைக் கிளப்பின. எடப்பாடி பழனிசாமியின் ஒற்றைத் தலைமைக்கு எதிராகச் செங்கோட்டையன் டெல்லியின் ஆதரவைத் திரட்ட முயல்கிறாரா என்ற சந்தேகத்தை இந்த நகர்வு எழுப்பியது. இந்த ரகசியச் சந்திப்பு கொங்கு மண்டலத்தில் அதிமுக-வின் அஸ்திவாரத்தை அசைப்பதற்கான ஒரு முக்கியத் தொடக்கப் புள்ளியாக மாறியது." , year:2025, parties:["bjp", "dmk", "aiadmk"], newsQuery:"ஓரங்கட்டப்பட்ட கே.ஏ. செங்கோட்டையன் டெல்லியில் அமித் ஷாவுடன் ரகசியச் சந்திப்பு 2025"},
  { id:113, season:"பருவம் 11", seasonNum:11, date:"செப்டம்பர் 27, 2025", title:"கரூர் தவெக மாநாட்டில் நெரிசல் துயரம்: 9 குழந்தைகள் உட்பட 41 பேர் பலி", filter:"crisis", tags:[["விபத்து","red"],["கரூர் மாநாடு","gray"],["உயிரிழப்பு","gray"]], desc:"கரூர் வேலுசாமிபுரத்தில் லட்சக்கணக்கான தொண்டர்கள் திரள தமிழக வெற்றிக் கழகத்தின் மிக பிரம்மாண்டமான மண்டல மாநாடு ஏற்பாடு செய்யப்பட்டிருந்தது. மாநாடு நடைபெற்றுக் கொண்டிருந்த போது திடீரென ஏற்பட்ட அள்ள முடியாத கூட்ட நெரிசலில் சிக்கி 9 குழந்தைகள் உட்பட 41 பேர் பரிதாபமாகத் மிதிக்கப்பட்டுப் பலியாயினர். இந்த அதிர்ச்சிகரமான விபத்தில் 80-க்கும் மேற்பட்ட தொண்டர்கள் படுகாயமடைந்து கரூர் அரசு மருத்துவமனையின் தீவிர சிகிச்சைப் பிரிவில் அனுமதிக்கப்பட்டனர். அரசியல் வரலாற்றிலேயே ஒரு மாநாட்டில் இவ்வளவு பெரிய உயிர்ச்சேதம் நிகழ்ந்தது ஒட்டுமொத்தத் தமிழகத்தையும் சோகத்திலும் கொந்தளிப்பிலும் ஆழ்த்தியது. விபத்தைத் தொடர்ந்து உள்கட்டமைப்பு மற்றும் பாதுகாப்பு மேலாண்மை குறைபாடுகள் குறித்து தவெக மற்றும் அதன் நிர்வாகிகள் மீது கரூர் நகரக் காவல் நிலையத்தில் பலத்த பிரிவுகளின் கீழ் FIR பதியப்பட்டது." , year:2025, parties:["tvk"], newsQuery:"கரூர் தவெக மாநாட்டில் நெரிசல் துயரம்: 9 குழந்தைகள் உட்பட 41 பேர் பலி 2025"},
  { id:114, season:"பருவம் 11", seasonNum:11, date:"செப்டம்பர் 27, 2025 (தொடர்ச்சி)", title:"மாநாட்டு விபத்துக்கு சிஎம் ஸ்டாலின் மற்றும் விஜய் நிவாரணம் அறிவிப்பு", filter:"crisis", tags:[["நிவாரணம்","red"],["ஸ்டாலின்","gray"],["விஜய்","gray"]], desc:"கரூரில் நடந்த மாநாட்டு நெரிசல் துயரத்திற்கு ஆழமான இரங்கலைத் தெரிவித்த முதலமைச்சர் மு.க.ஸ்டாலின் உயிரிழந்தவர்களின் குடும்பங்களுக்குத் தலா ₹10 லட்சம் அரசு நிவாரணம் அறிவித்தார். மாநாட்டுத் திடலில் கண்ணீருடன் காணப்பட்ட தவெக தலைவர் விஜய் உயிரிழந்த தனது சொந்தக் கழகத் தொண்டர்களின் குடும்பங்களுக்குத் தலா ₹20 லட்சம் நிவாரணம் அறிவித்தார். இந்த மாபெரும் விபத்து குறித்துத் தீவிர விசாரணை நடத்தத் தமிழ்நாடு அரசு ஓய்வுபெற்ற நீதியரசர் அருணா ஜெகதீசன் தலைமையிலான ஒரு நபர் விசாரணை ஆணையத்தை அமைத்தது. விபத்து தொடர்பாகத் தேர்தல் பிரச்சார வியூகப் பொதுச்செயலாளர் ஆதவ் அர்ஜுனா மீது பதியப்பட்ட FIR-ஐப் பின்னாளில் சென்னை உயர்நீதிமன்றம் ரத்து செய்து உத்தரவிட்டது. தவெக-வின் அரசியல் எழுச்சிக்கு மிகப்பெரிய முட்டுக்கட்டையாகவும் சோதனையாகவும் அமைந்த ஒரு இருண்ட நாளாக இந்தச் செப்டம்பர் 27 பதிவானது." , year:2025, parties:["dmk", "tvk"], newsQuery:"மாநாட்டு விபத்துக்கு சிஎம் ஸ்டாலின் மற்றும் விஜய் நிவாரணம் அறிவிப்பு 2025"},
  { id:115, season:"பருவம் 11", seasonNum:11, date:"அக்டோபர் 31, 2025", title:"கே.ஏ. செங்கோட்டையன் அதிமுகவிலிருந்து அதிரடி நீக்கம்", filter:"crisis", tags:[["நீக்கம்","red"],["செங்கோட்டையன்","gray"],["அதிமுக","gray"]], desc:"டெல்லி சந்திப்பு மற்றும் ஓபிஎஸ், டிடிவி தினகரன் ஆகியோரைச் ரகசியமாகச் சந்தித்ததாக எழுந்த புகார்களின் அடிப்படையில் கே.ஏ. செங்கோட்டையன் மீது அதிமுக தலைமை பாய நினைத்தது. அக்டோபர் 31 அன்று பொதுச்செயலாளர் எடப்பாடி பழனிசாமி வெளியிட்ட அதிகாரப்பூர்வ அறிவிப்பில் கட்சியின் கட்டுப்பாட்டை மீறியதாகக் கூறி செங்கோட்டையன் அடிப்படை உறுப்பினரிலிருந்து நீக்கப்பட்டார். 40 ஆண்டுகளுக்கும் மேலாகக் கட்சியின் விசுவாசியாக இருந்த ஒரு மூத்த தலைவரை அதிரடியாக நீக்கியது கொங்கு மண்டல அதிமுக தொண்டர்களிடையே மாபெரும் கொந்தளிப்பை ஏற்படுத்தியது. இந்த நீக்க நடவடிக்கை அதிமுக-வின் வீழ்ச்சிக்குக் கொங்கு மண்டலத்திலேயே அஸ்திவாரம் அமைக்கும் ஈபிஎஸ்-ன் தற்கொலைப்படை நகர்வாக விமர்சிக்கப்பட்டது. (இதற்கிடையே நவம்பர் 5 அன்று மாமல்லபுரத்தில் தவெக-வின் அவசரச் சிறப்புப் பொதுக்குழு கூட்டம் மிக ரகசியமாகத் திட்டமிடப்பட்டு நடத்தப்பட்டது)." , year:2025, parties:["dmk", "aiadmk", "tvk"], newsQuery:"கே.ஏ. செங்கோட்டையன் அதிமுகவிலிருந்து அதிரடி நீக்கம் 2025"},
  { id:120, season:"பருவம் 11", seasonNum:11, date:"நவம்பர் 26, 2025", title:"செங்கோட்டையன் தனது கோபிச்செட்டிப்பாளையம் எம்.எல்.ஏ பதவியை ராஜினாமா செய்தார்", filter:"alliance", tags:[["ராஜினாமா","red"],["எம்.எல்.ஏ","gray"],["கோபிச்செட்டிப்பாளையம்","gray"]], desc:"அதிமுகவிலிருந்து நீக்கப்பட்டதைத் தொடர்ந்து தன் மீதான துரோகி முத்திரையைத் துடைத்தெறியவும் தனது அரசியல் கௌரவத்தைக் காப்பாற்றவும் செங்கோட்டையன் அடுத்த அதிரடி முடிவை எடுத்தது. நவம்பர் 26 அன்று தனது பாரம்பரியமிக்க கோபிச்செட்டிப்பாளையம் சட்டமன்றத் தொகுதி உறுப்பினர் (MLA) பதவியை முறைப்படி சபாநாயகர் அப்பாவுவிடம் நேரில் சென்று ராஜினாமா செய்தார். சபாநாயகர் அவரது ராஜினாமா கடிதத்தை உடனடியாக ஏற்றுக்கொண்டு கோபிச்செட்டிப்பாளையம் தொகுதி காலியானதாக அரசிதழில் அதிகாரப்பூர்வமாக வெளியிட்டார். பதவி சுகத்திற்காகக் கட்சியில் நீடிக்கவில்லை என்பதைத் தனது ராஜினாமாவின் மூலம் கொங்கு மண்டல மக்களுக்கு அவர் நிரூபித்துக் காட்டினார். இந்த ராஜினாமா அவர் தவெக-வின் புதிய தூணாக மாறப்போகிறார் என்ற அரசியல் எதிர்பார்ப்பை மாநில அளவில் உச்சத்திற்குக் கொண்டு சென்றது." , year:2025, parties:["dmk", "aiadmk", "tvk"], newsQuery:"செங்கோட்டையன் தனது கோபிச்செட்டிப்பாளையம் எம்.எல்.ஏ பதவியை ராஜினாமா செய்தார் 2025"},
  { id:121, season:"பருவம் 11", seasonNum:11, date:"நவம்பர் 27, 2025", title:"விஜய் முன்னிலையில் தவெக-வில் இணைந்தார் கே.ஏ. செங்கோட்டையன்", filter:"alliance", tags:[["கட்சி","red"],["செங்கோட்டையன்","gray"],["தவெக","gray"]], desc:"எம்.எல்.ஏ பதவியை ராஜினாமா செய்த அடுத்த 24 மணி நேரத்திற்குள் சென்னை தவெக தலைமைக் கழகத்திற்கு கே.ஏ. செங்கோட்டையன் கம்பீரமாக வருகை தந்தார். கட்சித் தலைவர் விஜய் முன்னிலையில் அவர் தன்னை 'தமிழக வெற்றிக் கழகத்தில்' அதிகாரப்பூர்வமாக இணைத்துக் கொண்டு புதிய அரசியல் பயணத்தைத் தொடங்கினார். அவருக்குக் கட்சியின் மிக உயரிய 'நிதி மற்றும் சட்டமன்ற விவகாரங்களுக்கான முதன்மை ஆலோசகர்' என்ற பொறுப்பை விஜய் உடனடியாக வழங்கினார். திராவிடக் கட்சியின் மிக மூத்த உள்கட்டமைப்புத் தலைவர் தவெக-வில் இணைந்தது தவெக-வை ஒரு முதிர்ச்சியான மற்றும் தேர்தலைச் சந்திப்பதற்கான முழுமையான அரசியல் சக்தியாக மாற்றியது." , year:2025, parties:["tvk"], newsQuery:"விஜய் முன்னிலையில் தவெக-வில் இணைந்தார் கே.ஏ. செங்கோட்டையன் 2025"},
  { id:122, season:"பருவம் 12", seasonNum:12, date:"ஜனவரி 12, 2026", title:"கரூர் விபத்து வழக்கு: டெல்லி சிபிஐ அலுவலகத்தில் விஜய்யிடம் 7 மணி நேர முதற்கட்ட விசாரணை", filter:"verdict", tags:[["விசாரணை","red"],["சிபிஐ","gray"],["விஜய்","gray"]], desc:"கரூரில் நடந்த மாநாட்டு நெரிசல் விபத்து வழக்கை மத்திய அரசு சிபிஐ (CBI) விசாரணைக்கு மாற்றியதைத் தொடர்ந்து தவெக தலைவர் விஜய்க்கு டெல்லி தலைமையகத்திலிருந்து அதிகாரப்பூர்வ சம்மன் அனுப்பப்பட்டது. ஜனவரி 12 அன்று புதுடெல்லியில் உள்ள சிபிஐ தலைமையகத்தில் கட்சித் தலைவர் விஜய் அதிகாரிகள் முன்னிலையில் நேரில் ஆஜரானார். மாநாட்டுக்கான அனுமதி கூட்ட மேலாண்மை குறைபாடுகள் மற்றும் பாதுகாப்பு ஏற்பாடுகள் குறித்து சிபிஐ அதிகாரிகள் விஜய்யிடம் தொடர்ந்து 7 மணி நேரம் முதற்கட்ட விசாரணை நடத்தினர். தேர்தலுக்குச் சில மாதங்களே இருந்த நிலையில் தவெக தலைவரை டெல்லிக்கு வரவழைத்துச் சிபிஐ விசாரித்தது அரசியல் வட்டாரத்தில் மிகப்பெரிய பரபரப்பை ஏற்படுத்தியது. இந்த விசாரணை விஜய்யைப் பயமுறுத்திப் பணிய வைக்க டெல்லி பாஜக அரசு ஏவிவிட்ட அரசியல் பழிவாங்கும் நடவடிக்கை எனத் தவெக தொண்டர்கள் நாடு முழுவதும் கண்டனக் குரலெழுப்பினர்." , year:2026, parties:["bjp", "tvk", "cbi"], newsQuery:"கரூர் விபத்து வழக்கு: டெல்லி சிபிஐ அலுவலகத்தில் விஜய்யிடம் 7 மணி நேர முதற்கட்ட விசாரணை 2026"},
  { id:123, season:"பருவம் 12", seasonNum:12, date:"ஜனவரி 19, 2026", title:"டெல்லி சிபிஐ தலைமையகத்தில் விஜய்யிடம் இரண்டாம் கட்ட விரிவான விசாரணை", filter:"verdict", tags:[["விசாரணை","red"],["சிபிஐ","gray"],["விஜய்","gray"]], desc:"பொங்கல் விடுமுறை முடிந்த கையோடு கரூர் விபத்து வழக்கில் விடுபட்ட சில முக்கியக் கேள்விகளுக்குப் பதிலளிக்க விஜய்க்கு மீண்டும் சிபிஐ சம்மன் அனுப்பியது. ஜனவரி 19 அன்று இரண்டாவது முறையாக டெல்லி சிபிஐ தலைமையகத்திற்குச் சென்ற விஜய்யிடம் உயர் அதிகாரிகள் முன்னிலையில் விரிவான விசாரணை நடத்தப்பட்டது. மாநாட்டுக்கு நிதி திரட்டப்பட்ட விபரங்கள் மற்றும் அதன் பொருளாதாரப் பின்னணிகள் குறித்தும் அதிகாரிகள் இந்த முறை துருவித் துருவி கேள்விகள் கேட்டனர். தவெக தலைவர் விஜய் எவ்வித பதற்றமும் இன்றி தனது வழக்கறிஞர்கள் குழுவின் ஆலோசனையின்படி சிபிஐ அதிகாரிகளின் அத்தனை கேள்விகளுக்கும் முறைப்படி பதிலளித்தார். இந்தத் தொடர் விசாரணைகள் விஜய் பொதுவெளியில் பிரச்சாரத்திற்குச் செல்வதைத் தடுத்து அவரை டெல்லியிலேயே முடக்குவதற்கான திட்டமிட்ட உத்தியாகவே பார்க்கப்பட்டது." , year:2026, parties:["tvk", "cbi"], newsQuery:"டெல்லி சிபிஐ தலைமையகத்தில் விஜய்யிடம் இரண்டாம் கட்ட விரிவான விசாரணை 2026"},
  { id:124, season:"பருவம் 12", seasonNum:12, date:"மார்ச் 15, 2026", title:"தேர்தலுக்கு முன் டெல்லியில் விஜய்யிடம் 7 மணி நேரத்திற்கும் மேலாகத் தீவிர சிபிஐ விசாரணை", filter:"verdict", tags:[["விசாரணை","red"],["சிபிஐ","gray"],["விஜய்","gray"]], desc:"தேர்தல் அறிவிப்பு வெளியாக இன்னும் சில நாட்களே இருந்த இக்கட்டான வேளையில் ஞாயிற்றுக்கிழமையன்று தவெக தலைவர் விஜய்யை டெல்லிக்கு வரவழைத்துச் சிபிஐ அதிரடி காட்டியது. மார்ச் 15 அன்று மூன்றாவது முறையாக சிபிஐ அதிகாரிகள் விஜய்யிடம் 7 மணி நேரத்திற்கும் மேலாகத் தீவிரமான இறுதி விசாரணை நடத்தி அவரது அதிகாரப்பூர்வ வாக்குமூலங்களைப் பதிவு செய்தனர். கட்சியின் மூத்த நிர்வாகிகளான ஆதவ் அர்ஜுனா மற்றும் அருண்ராஜ் ஆகியோரின் மாநாட்டுப் பங்களிப்புகள் குறித்தும் இந்த விசாரணையில் முக்கியக் கேள்விகள் எழுப்பப்பட்டன. விசாரணையை முடித்துவிட்டு வெளியே வந்த விஜய் 'நாங்கள் சட்டத்தை மதிக்கிறோம்; அனைத்துச் சதிகளையும் தாண்டித் தேர்தல் களத்தில் மக்களைச் சந்திப்போம்' என உறுதியுடன் பேசினார். (விசாரணை முடிந்த அடுத்த சில நாட்களிலேயே அதாவது மார்ச் 30 அன்று இந்தியத் தேர்தல் ஆணையம் தமிழக சட்டமன்றத் தேர்தலுக்கான அதிகாரப்பூர்வ அறிவிக்கையை வெளியிட்டது)." , year:2026, parties:["tvk", "cbi"], newsQuery:"தேர்தலுக்கு முன் டெல்லியில் விஜய்யிடம் 7 மணி நேரத்திற்கும் மேலாகத் தீவிர சிபிஐ விசாரணை 2026"},
  { id:125, season:"பருவம் 12", seasonNum:12, date:"மார்ச் 30, 2026", title:"தமிழக சட்டமன்றத் தேர்தல் அறிவிக்கை (Notification) அதிகாரப்பூர்வ வெளியீடு", filter:"alliance", tags:[["தேர்தல்","red"],["அறிவிக்கை","gray"],["ECI","gray"]], desc:"இந்தியத் தேர்தல் ஆணையம் (ECI) தமிழ்நாட்டின் 17-வது சட்டமன்றத் தேர்தலுக்கான அதிகாரப்பூர்வத் தேர்தல் அட்டவணை மற்றும் அறிவிக்கையை முறைப்படி வெளியிட்டது. இதனுடன் மாநிலம் முழுவதும் தேர்தல் நடத்தை விதிகள் (Model Code of Conduct) உடனடியாக அமலுக்கு வந்ததால் அரசு நிர்வாகம் தேர்தல் ஆணையத்தின் கட்டுப்பாட்டுக்குள் சென்றது. திமுக, அதிமுக-பாஜக கூட்டணி மற்றும் மாற்றுச் சக்தியாகத் தவெக எனத் தமிழக அரசியல் களம் வரலாற்றிலேயே முதன்முறையாக மும்முனைப் போட்டியாக மாறியது. தவெக தலைவர் விஜய் டெல்லி விசாரணைகளின் சோர்வை உதறித் தள்ளிவிட்டு தமிழ்நாடு முழுவதும் அனல் பறக்கும் தனது தேர்தல் பிரச்சாரப் பயணத்தைத் தொடங்கினார்." , year:2026, parties:["bjp", "dmk", "aiadmk", "tvk"], newsQuery:"தமிழக சட்டமன்றத் தேர்தல் அறிவிக்கை (Notification) அதிகாரப்பூர்வ வெளியீடு 2026"},
  { id:126, season:"பருவம் 12", seasonNum:12, date:"ஏப்ரல் 23, 2026", title:"தமிழக தேர்தல் வாக்குப்பதிவு: வரலாறு காணாத 85.1% பதிவு", filter:"verdict", tags:[["தேர்தல்","red"],["வாக்குப்பதிவு","gray"],["85.1%","gray"]], desc:"தமிழ்நாட்டின் 234 சட்டமன்றத் தொகுதிகளுக்கும் ஒரே கட்டமாக ஏப்ரல் 23 அன்று வாக்குப்பதிவு பலத்த பாதுகாப்பு மற்றும் நவீன கண்காணிப்புகளுக்கு இடையே நடைபெற்றது. இளைஞர்கள் புதிய வாக்காளர்கள் மற்றும் பெண் வாக்காளர்கள் காலை முதலே வாக்குச் சாவடிகளில் நீண்ட வரிசையில் நின்று தங்களது ஜனநாயகக் கடமையை ஆற்றினர். வாக்குப்பதிவு நிறைவடைந்த போது தமிழக தேர்தல் வரலாற்றிலேயே இல்லாத அளவாக மிக உச்சகட்டமாக **85.1% வாக்குகள்** பதிவாகியிருப்பதாகத் தேர்தல் ஆணையம் அறிவித்தது. இந்த வரலாறு காணாத மாபெரும் வாக்குப்பதிவு ஆளும் திராவிடக் கட்சிகளுக்கு எதிராக மக்கள் ஒரு மாபெரும் மௌனப் புரட்சியை நிகழ்த்தியுள்ளனர் என்பதற்கான அசைக்க முடியாத அறிகுறியாகப் பார்க்கப்பட்டது." , year:2026, parties:["unknown"], newsQuery:"தமிழக தேர்தல் வாக்குப்பதிவு: வரலாறு காணாத 85.1% பதிவு 2026"},
  { id:127, season:"பருவம் 12", seasonNum:12, date:"மே 4, 2026", title:"சரித்திர தேர்தல் முடிவுகள்: 108 இடங்களை வென்று தனிப்பெரும் கட்சியாகத் தவெக சாதனை", filter:"verdict", tags:[["வெற்றி","red"],["தவெக","gray"],["108 இடங்கள்","gray"]], desc:"ஒட்டுமொத்த இந்தியாவே உற்று நோக்கிய தமிழக சட்டமன்றத் தேர்தலின் வாக்கு எண்ணிக்கை முடிவுகள் வெளியாகி புதிய அரசியல் சகாப்தத்தை நிலைநிறுத்தின. 59 ஆண்டு கால திராவிடக் கட்சிகளின் (திமுக / அதிமுக) ஏகபோக ஆதிக்கத்தை அடியோடு முறியடித்து **விஜய்யின் தமிழக வெற்றிக் கழகம் 108 இடங்களை வென்று தனிப்பெரும் கட்சியாக மாபெரும் சாதனை படைத்தது.** ஆளும் கட்சியாக இருந்த திராவிட முன்னேற்றக் கழகம் (DMK) வெறும் 59 இடங்களை மட்டுமே பெற்று பிரதான எதிர்க்கட்சி வரிசைக்குத் தள்ளப்பட்டது. மீண்டும் கூட்டணி அமைத்துப் போட்டியிட்ட அஇஅதிமுக கொங்கு மண்டலத்தைத் தவிர பிற இடங்களில் பெரும் சரிவைச் சந்தித்து 47 இடங்களை மட்டுமே பெற்று படுதோல்வி அடைந்தது." , year:2026, parties:["dmk", "aiadmk", "tvk"], newsQuery:"சரித்திர தேர்தல் முடிவுகள்: 108 இடங்களை வென்று தனிப்பெரும் கட்சியாகத் தவெக சாதனை 2026"},
  { id:128, season:"பருவம் 12", seasonNum:12, date:"மே 4, 2026 (தொடர்ச்சி)", title:"கொளத்தூரில் ஸ்டாலின் படுதோல்வி; திமுக-அதிமுக சரித்திரச் சரிவு", filter:"verdict", tags:[["தோல்வி","red"],["ஸ்டாலின்","gray"],["கொளத்தூர்","gray"]], desc:"தவெக தலைவர் விஜய் தான் போட்டியிட்ட பெரம்பூர் மற்றும் திருச்சி கிழக்கு ஆகிய இரண்டு தொகுதிகளிலும் பலத்த வாக்குகள் வித்தியாசத்தில் மாபெரும் வெற்றி பெற்றார். இந்தத் தேர்தலின் மிகப்பெரிய அதிரடி திருப்பமாக திமுக தலைவரும் முன்னாள் முதலமைச்சருமான மு.க.ஸ்டாலின் தனது சொந்தக் கோட்டையான கொளத்தூர் தொகுதியில் தவெக வேட்பாளர் வி.எஸ். பாபுவிடம் படுதோல்வியைச் சந்தித்தார். (இதற்கிடையே ஜூன் 19 அன்று கள்ளக்குறிச்சியில் நடந்த விஷச்சாராய சோக விபத்தில் 60-க்கும் மேற்பட்டோர் பலியானது இந்தத் தேர்தலில் ஆளுங்கட்சிக்கு மிகப்பெரிய பின்னடைவாக அமைந்தது உங்களின் தரவுகளில் உறுதியாகிறது). 1967-க்குப் பிறகு தமிழ்நாட்டில் திராவிட சித்தாந்தக் கட்சிகள் அல்லாத ஒரு புதிய பிராந்தியக் கட்சி ஆட்சிக்கட்டிலைப் பிடித்த மாபெரும் வரலாற்று நாளாக இந்த மே 4 தடம் பதித்தது." , year:2026, parties:["dmk", "aiadmk", "tvk"], newsQuery:"கொளத்தூரில் ஸ்டாலின் படுதோல்வி; திமுக-அதிமுக சரித்திரச் சரிவு 2026"},
  { id:129, season:"பருவம் 12", seasonNum:12, date:"மே 5, 2026", title:"முதலமைச்சர் பதவியை முறைப்படி ராஜினாமா செய்தார் மு.க. ஸ்டாலின்", filter:"alliance", tags:[["ராஜினாமா","red"],["மு.க.ஸ்டாலின்","gray"],["திமுக","gray"]], desc:"தேர்தல் தோல்வியையும் மக்கள் தீர்ப்பையும் முழுமையாக ஏற்றுக்கொள்வதாக திமுக தலைவர் மு.க.ஸ்டாலின் அதிகாரப்பூர்வமாக அறிவித்தார். மே 5 அன்று காலை சென்னை கிண்டியில் உள்ள ஆளுநர் மாளிகைக்குச் சென்ற அவர் ஆளுநரிடம் தனது முதலமைச்சர் பதவிக் கடிதத்தை முறைப்படி ராஜினாமா செய்தார். புதிய அரசு பதவியேற்கும் வரை தற்காலிகமாக முதலமைச்சர் பொறுப்பைக் கவனிக்குமாறு ஆளுநர் அவரைக் கேட்டுக்கொண்டார். 5 ஆண்டுகால திமுக ஆட்சியின் அதிகாரப் பிடி இத்துடன் முடிவுக்கு வர புதிய தவெக அரசின் பதவியேற்பு விழாவுக்கான ஏற்பாடுகள் தீவுத்திடலில் மிக பிராண்டமாகத் தொடங்கின." , year:2026, parties:["dmk", "tvk"], newsQuery:"முதலமைச்சர் பதவியை முறைப்படி ராஜினாமா செய்தார் மு.க. ஸ்டாலின் 2026"},
  { id:130, season:"பருவம் 12", seasonNum:12, date:"மே 11, 2026", title:"உடைந்த அதிமுக: எஸ்.பி. வேலுமணி தலைமையில் 30 எம்.எல்.ஏக்கள் அதிரடிப் பிரிவு", filter:"crisis", tags:[["பிளவு","red"],["அதிமுக","gray"],["எஸ்.பி. வேலுமணி","gray"]], desc:"தேர்தல் தோல்வியைத் தொடர்ந்து அஇஅதிமுக-விற்குள் எடப்பாடி பழனிசாமியின் ஒற்றைத் தலைமைக்கு எதிராகப் பெரும் போர்க்கொடி தூக்கப்பட்டது. மே 11 அன்று கொங்கு மண்டலத்தின் பலமான தலைவரான எஸ்.பி. வேலுமணி தலைமையில் 30 அதிமுக எம்.எல்.ஏ-க்கள் எடப்பாடியை நிராகரித்துத் தனியாகப் பிரிந்தனர். 'கட்சியைத் தவறான வழியில் நடத்தி அழித்துவிட்டார்' என்று ஈபிஎஸ் மீது குற்றம் சாட்டி அவர்கள் தவெக அரசுக்குச் சாதகமான புதிய அரசியல் நிலைப்பாட்டை எடுத்தனர். இந்தத் திடீர் உள்கட்சிப் பிளவு பிரதான எதிர்க்கட்சி அந்தஸ்தைக் கூட இழக்கும் நிலைக்கு அதிமுக-வை ஒட்டுமொத்தமாகச் சிதைத்தது." , year:2026, parties:["dmk", "aiadmk", "tvk"], newsQuery:"உடைந்த அதிமுக: எஸ்.பி. வேலுமணி தலைமையில் 30 எம்.எல்.ஏக்கள் அதிரடிப் பிரிவு 2026"},
  { id:131, season:"பருவம் 12", seasonNum:12, date:"மே 12, 2026", title:"தமிழ்நாட்டின் 22-வது முதலமைச்சராக சி. ஜோசப் விஜய் சென்னை தீவுத்திடலில் பதவியேற்பு", filter:"oath", tags:[["பதவியேற்பு","red"],["விஜய்","gray"],["முதலமைச்சர்","gray"]], desc:"சென்னை தீவுத்திடலில் லட்சக்கணக்கான தொண்டர்கள் மற்றும் பொதுமக்கள் முன்னிலையில் **தமிழ்நாட்டின் 22-வது முதலமைச்சராக சி. ஜோசப் விஜய் முறைப்படி பதவிப் பிரமாணம் எடுத்துக் கொண்டார்.** 'சி. ஜோசப் விஜய் எனும் நான்...' என்று அவர் கம்பீரமாக உச்சரித்த போது தீவுத்திடலே அதிரும் வகையில் தொண்டர்களின் ஆரவாரம் விண்ணைத் தொட்டது. தமிழக வரலாற்றில் ஒரு புதிய சகாப்தத்தைத் தொடங்கி வைத்த அவர் முதலமைச்சராகப் பொறுப்பேற்றவுடன் பொது நிர்வாகம், உள்வகை (காவல் துறை) மற்றும் பெண்கள் நலன் ஆகிய முக்கியத் துறைகளைத் தன் வசம் வைத்துக் கொண்டார்." , year:2026, parties:["tvk"], newsQuery:"தமிழ்நாட்டின் 22-வது முதலமைச்சராக சி. ஜோசப் விஜய் சென்னை தீவுத்திடலில் பதவியேற்பு 2026"},
  { id:132, season:"பருவம் 12", seasonNum:12, date:"மே 12, 2026 (தொடர்ச்சி)", title:"கேபினட் அமைச்சர்களாக செங்கோட்டையன், அருண்ராஜ், ஆதவ் அர்ஜுனா, நிர்மல்குமார் பதவியேற்பு", filter:"oath", tags:[["பதவியேற்பு","red"],["அமைச்சரவை","gray"],["தவெக","gray"]], desc:"முதலமைச்சர் விஜய்யுடன் சேர்ந்து அவரது புதிய அமைச்சரவை சகாக்களும் முறைப்படி அமைச்சர்களாகப் பதவிப் பிரமாணம் எடுத்துக் கொண்டனர். கே.ஏ. செங்கோட்டையன் (நிதி மற்றும் சட்டமன்ற விவகாரங்கள் - அவை முன்னவர்), டாக்டர் கே.ஜி. அருண்ராஜ் (சுகாதாரம், மருத்துவக் கல்வி மற்றும் மக்கள் நல்வாழ்வு) அமைச்சர்களாகப் பொறுப்பேற்றனர். தேர்தல் வியூகங்களை வகுத்த ஆதவ் அர்ஜுனா (பொதுப்பணி மற்றும் விளையாட்டுத்துறை) மற்றும் சி.டி.ஆர். நிர்மல்குமார் (சட்டம், நீதி மற்றும் எரிசக்தி வளங்கள்) கேபினட் அமைச்சர்களாகப் பொறுப்பேற்றனர். (அதே சமயம் ஆர்.கே. நகர் தொகுதியில் சுயேச்சையாக வென்ற கல்வி அதிபர் டாக்டர் என். மேரி வில்சன் சட்டசபை உறுப்பினராக முறைப்படி MLA-வாகப் பொறுப்பேற்றுக் கொண்டார்)." , year:2026, parties:["tvk"], newsQuery:"கேபினட் அமைச்சர்களாக செங்கோட்டையன், அருண்ராஜ், ஆதவ் அர்ஜுனா, நிர்மல்குமார் பதவியேற்பு 2026"},
  { id:133, season:"பருவம் 12", seasonNum:12, date:"மே 13, 2026", title:"சட்டசபையில் நம்பிக்கை வாக்கெடுப்பு: 144 வாக்குகள் பெற்று தவெக அரசு பெரும்பான்மையை நிரூபித்தது", filter:"verdict", tags:[["வாக்கெடுப்பு","red"],["தவெக","gray"],["144 வாக்குகள்","gray"]], desc:"புதிய முதலமைச்சர் விஜய் சட்டசபையில் தனது அரசின் மீதான பெரும்பான்மையை நிரூபிப்பதற்கான நம்பிக்கை வாக்கெடுப்பைக் (Floor Test) கோரினார். தவெக வசம் 108 இடங்கள் மட்டுமே இருந்த நிலையில் காங்கிரஸ் (5), விசிக (8) மற்றும் ஈபிஎஸ்-ஐ எதிர்த்துப் பிரிந்த எஸ்.பி. வேலுமணி அணியின் 30-க்கும் மேற்பட்ட எம்.எல்.ஏ-க்கள் தவெக-வுக்கு ஆதரவாக வாக்களித்தனர். வாக்கெடுப்பின் முடிவில் முதலமைச்சர் விஜய் **144 வாக்குகளைப் பெற்று** தனது பெரும்பான்மையை மிக வெற்றிகரமாக நிரூபித்து புதிய ஆட்சியைச் சட்டசபையில் நிலைநிறுத்தினார். இந்த மாபெரும் ஆதரவு தவெக அரசு அடுத்த 5 ஆண்டுகளுக்கு எவ்வித அச்சுறுத்தலும் இன்றி ஸ்திரமாக இயங்குவதை உறுதி செய்தது." , year:2026, parties:["aiadmk", "tvk", "congress"], newsQuery:"சட்டசபையில் நம்பிக்கை வாக்கெடுப்பு: 144 வாக்குகள் பெற்று தவெக அரசு பெரும்பான்மையை நிரூபித்தது 2026"},
  { id:134, season:"பருவம் 12", seasonNum:12, date:"மே 14, 2026", title:"அமைச்சர் அருண்ராஜ் கொள்கை பிரகடனம்: பெரியார் சமூக நீதி & தொகுதி மறுசீரமைப்பு எதிர்ப்பு!", filter:"alliance", tags:[["கொள்கை","red"],["அருண்ராஜ்","gray"],["தவெக","gray"]], desc:"சுகாதாரத்துறை அமைச்சராகப் பொறுப்பேற்ற பின் மே 14 அன்று ஆங்கில ஊடகத்திற்கு (Economic Times) பேட்டியளித்த முன்னாள் ஐ.ஆர்.எஸ் அதிகாரி டாக்டர் கே.ஜி. அருண்ராஜ் தவெக-வின் கொள்கைப் பிரகடனத்தை வெளியிட்டார். தவெக அரசு மத்திய அரசுடன் இணக்கமான கூட்டாட்சி (Cooperative Federalism) முறையில் இணைந்து செயல்படும் என்றும் அதேநேரம் தென்னக மாநிலங்களைப் பாதிக்கும் மக்கள் தொகையின் அடிப்படையிலான தொகுதி மறுசீரமைப்பைக் (Delimitation) கடுமையாக எதிர்க்கும் என்றும் அறிவித்தார். மேலும் தந்தை பெரியாரின் சமூக நீதி மற்றும் பகுத்தறிவுக் கொள்கையிலேயே தவெக அரசு முழுமையாக இயங்கும் என்றும் கொள்கை பிரகடனம் செய்துள்ளார். (இதன் நீட்சியாக மே 20, 2026 அன்று திமுக கூட்டணியை முழுமையாக உடைக்கும் மாஸ்டர் ஸ்ட்ரோக்காக காங்கிரஸ் மற்றும் விசிக கட்சிகளைத் தவெக அமைச்சரவையில் இணையுமாறு அமைச்சர் ஆதவ் அர்ஜுனா இன்று பகிரங்க அழைப்பு விடுத்துள்ளார்)." , year:2026, parties:["dmk", "tvk", "congress"], newsQuery:"அமைச்சர் அருண்ராஜ் கொள்கை பிரகடனம்: பெரியார் சமூக நீதி & தொகுதி மறுசீரமைப்பு எதிர்ப்பு! 2026"}
];

